// StayTW Study — TOCFL Level 3 文法
// 正本: 國家教育研究院「臺灣華語文能力基準(TBCL)」語法點表 496 点。
//   第3級 の点をそのまま並べ、最後に官方の表に無い点(書面語・進階)を足している。
//   語法點名(t)と1つ目の例文は官方のまま。説明と訳と2つ目の例文はこちらで書いた。
//   作り直し: node scripts/gen-grammar.mjs → node scripts/build-grammar.mjs
// 形式: id, cat, t=語法點名, g=一言の意味, p=文型, ex=解説, eg=例文[{z,py,j,e,k}]
const GRAMMAR_L3 = [
{"id":"g3-108","cat":"アスペクト","t":"V過2","g":{"j":"すでに〜した(完了)","e":"Already did (completion, not mere experience)","k":"이미 ~했다(완료)"},"p":{"j":"已經＋動詞＋過＋(了)","e":"yǐjīng + V + guò + (le)","k":"已經 + 동사 + 過 + (了)"},"ex":{"j":"「已經V過了」は「もうVした」という完了を表す。経験を表す「V過(曾經)」と違い、今日/昨日など特定の時点の動作がすでに終わったことを強調する。単独の「了」とほぼ同じ意味。","e":"'已經 V 過 了' emphasizes that a specific action is finished (e.g. this morning), unlike experiential 'V過' which describes past experience without a fixed time. It overlaps closely with plain 了.","k":"'已經V過了'는 특정 시점(오늘 아침 등)에 동작이 끝났음을 강조하는 완료 표현으로, 시점 제한 없이 경험을 나타내는 경험상 '過'와 다르다. 단순 '了'와 의미가 비슷하다."},"eg":[{"z":"我今天早上已經<em>看過</em>電視新聞了。","py":"Wǒ jīntiān zǎoshang yǐjīng kànguò diànshì xīnwén le.","j":"私は今日の朝、もうテレビのニュースを見ました。","e":"I already watched the TV news this morning.","k":"저는 오늘 아침에 이미 텔레비전 뉴스를 봤어요."},{"z":"他昨天已經<em>寫過</em>作業了。","py":"Tā zuótiān yǐjīng xiěguò zuòyè le.","j":"彼は昨日もう宿題をやりました。","e":"He already did his homework yesterday.","k":"그는 어제 이미 숙제를 했어요."}]},
{"id":"g3-109","cat":"アスペクト","t":"V著2","g":{"j":"〜しながら(様態・同時動作)","e":"V1 while V2-ing (manner/simultaneous action)","k":"~하면서(동시 동작)"},"p":{"j":"V1＋著＋(目的語)＋V2","e":"V1 + zhe + (Object) + V2","k":"V1 + 著 + (목적어) + V2"},"ex":{"j":"「V1著V2」は「V1しながらV2する」という同時動作・様態を表す。単独の「V著」(状態の持続、例:門開著)とは違い、必ず後ろにもう1つの動詞が続く。","e":"'V1-zhe V2' means doing V2 while V1-ing (manner/simultaneous action), always followed by a second verb — unlike standalone 'V著' which shows a persisting state (e.g. 門開著, the door is open).","k":"'V1著V2'는 'V1하면서 V2하다'라는 동시 동작·양태를 나타내며, 반드시 뒤에 동사가 하나 더 온다. 상태 지속을 나타내는 단독 'V著'(예: 門開著, 문이 열려 있다)와 다르다."},"eg":[{"z":"他們<em>吃著</em>餅乾看電視。","py":"Tāmen chīzhe bǐnggān kàn diànshì.","j":"彼らはクッキーを食べながらテレビを見ています。","e":"They are watching TV while eating cookies.","k":"그들은 과자를 먹으면서 텔레비전을 보고 있어요."},{"z":"媽媽<em>笑著</em>跟我說話。","py":"Māma xiàozhe gēn wǒ shuōhuà.","j":"お母さんは笑いながら私に話しました。","e":"Mom talked to me while smiling.","k":"엄마는 웃으면서 저에게 말했어요."}]},
{"id":"g3-110","cat":"補語","t":"V到3","g":{"j":"〜し終えて目的を達成する(結果補語)","e":"V到 = succeeded in V-ing (result complement of achievement)","k":"V到 = ~하는 데 성공함(결과보어)"},"p":{"j":"動詞＋到＋(目的語)","e":"Verb + dào + (Object)","k":"동사 + 到 + (목적어)"},"ex":{"j":"「V到」は「找到・買到・收到」のように動作が目的を達成したことを表す結果補語。到着を表す「到＋場所」や知覚を表す「看到・聽到」とは意味の種類が違うので混同しない。","e":"'V到' is a result complement showing the action succeeded in reaching its goal (找到 = managed to find, 買到 = managed to buy). Don't confuse it with 到 meaning 'arrive at a place' or with perception verbs like 看到/聽到.","k":"'V到'는 找到(찾아내다), 買到(사는 데 성공하다)처럼 동작이 목표를 달성했음을 나타내는 결과보어다. 장소 도착을 뜻하는 '到+장소'나 지각동사 看到·聽到와 혼동하지 않도록 주의한다."},"eg":[{"z":"他<em>找到</em>那家超市了。","py":"Tā zhǎodào nà jiā chāoshì le.","j":"彼はあのスーパーを見つけました。","e":"He found that supermarket.","k":"그는 그 슈퍼마켓을 찾았어요."},{"z":"我終於<em>買到</em>那本書了。","py":"Wǒ zhōngyú mǎidào nà běn shū le.","j":"私はついにあの本を買うことができました。","e":"I finally managed to buy that book.","k":"저는 드디어 그 책을 살 수 있었어요."}]},
{"id":"g3-111","cat":"副詞","t":"才1","g":{"j":"〜してようやく(遅れて成立)","e":"not until / only then","k":"~하고 나서야"},"p":{"j":"A(動作・條件)＋才＋B","e":"A, then only (after that) B","k":"A ＋ 才 ＋ B"},"ex":{"j":"「才」はBがAの後、しかも予想より遅く成立したことを示す。「才4」の数量が少ない意味や、早く成立したことを示す「就」と混同しやすいので注意。","e":"Marks that B only happens after A, later than expected. Don't confuse with 才4 (small quantity) or 就 (earlier than expected).","k":"才는 A 이후에야, 그것도 예상보다 늦게 B가 이루어짐을 나타낸다. 수량이 적음을 뜻하는 才4나, 빨리 이루어짐을 뜻하는 就와 혼동하지 않도록 주의한다."},"eg":[{"z":"他看了報告後<em>才</em>同意醫生的說法。","py":"Tā kàn le bàogào hòu cái tóngyì yīshēng de shuōfǎ.","j":"彼は報告書を読んでから、ようやく医者の見解に同意した。","e":"He only agreed with the doctor's opinion after reading the report.","k":"그는 보고서를 읽고 나서야 의사의 견해에 동의했다."},{"z":"我等了很久，公車<em>才</em>來。","py":"Wǒ děng le hěn jiǔ, gōngchē cái lái.","j":"私は長い間待って、ようやくバスが来た。","e":"I waited a long time before the bus finally came.","k":"나는 오랫동안 기다리고 나서야 버스가 왔다."}]},
{"id":"g3-112","cat":"副詞","t":"才4","g":{"j":"わずか〜/まだ〜だけ(数量が少ない)","e":"only (emphasizing a small amount)","k":"겨우/고작 ~"},"p":{"j":"才＋数量詞","e":"cái + number/quantity","k":"才 ＋ 수량사"},"ex":{"j":"「才4」は数量・程度が予想より少ない・小さいことを強調する。時間の前後関係を表す「才1」とは意味が異なるので混同しないこと。","e":"Emphasizes that a number or degree is smaller/less than expected. Distinct from 才1, which marks a delayed sequence of events.","k":"才4는 수량이나 정도가 예상보다 적음/작음을 강조한다. 사건의 시간적 순서를 나타내는 才1과는 의미가 다르므로 혼동하지 않는다."},"eg":[{"z":"我上次見到你的時候，你<em>才</em>十一歲。","py":"Wǒ shàngcì jiàndào nǐ de shíhòu, nǐ cái shíyī suì.","j":"私が前回あなたに会った時、あなたはまだ11歳でした。","e":"The last time I saw you, you were only eleven years old.","k":"지난번에 너를 만났을 때, 너는 겨우 열한 살이었어."},{"z":"現在<em>才</em>八點，我們還有時間。","py":"Xiànzài cái bā diǎn, wǒmen hái yǒu shíjiān.","j":"今はまだ8時だから、私たちにはまだ時間がある。","e":"It's only eight o'clock now, so we still have time.","k":"지금 겨우 8시니까 우리는 아직 시간이 있어."}]},
{"id":"g3-113","cat":"特殊構文","t":"讓1","g":{"j":"〜させる/〜にする(使役・結果)","e":"to make/cause someone to do or feel something","k":"~하게 하다(사역)"},"p":{"j":"A＋讓＋B＋VP","e":"A + ràng + B + VP (A causes B to VP)","k":"A ＋ 讓 ＋ B ＋ VP"},"ex":{"j":"「讓1」はある原因(A)が結果としてBにある動作・状態を引き起こすことを表す。許可を求める「讓2」とは違い、こちらは因果関係。命令のニュアンスを持つ「叫1」とも異なる。","e":"讓1 shows that A causes B to do/feel something as a result — a causal relation, unlike 讓2 (permission) or 叫1 (a direct verbal order).","k":"讓1은 A라는 원인이 결과적으로 B에게 어떤 동작이나 상태를 일으킴을 나타낸다. 허락을 나타내는 讓2나, 직접적인 명령 뉘앙스를 가진 叫1과는 다르다."},"eg":[{"z":"睡前喝杯熱牛奶，可以<em>讓</em>我睡得更好。","py":"Shuì qián hē bēi rè niúnǎi, kěyǐ ràng wǒ shuì de gèng hǎo.","j":"寝る前に温かい牛乳を一杯飲むと、もっとよく眠れるようになる。","e":"Drinking a cup of warm milk before bed can help me sleep better.","k":"자기 전에 따뜻한 우유를 한 잔 마시면 더 잘 잘 수 있게 해준다."},{"z":"這部電影<em>讓</em>我很感動。","py":"Zhè bù diànyǐng ràng wǒ hěn gǎndòng.","j":"この映画は私をとても感動させた。","e":"This movie made me very moved.","k":"이 영화는 나를 매우 감동시켰다."}]},
{"id":"g3-114","cat":"特殊構文","t":"讓2","g":{"j":"〜させてもらう/許可を求める","e":"to let/allow (asking or granting permission)","k":"~하게 해 주다(허락)"},"p":{"j":"(能不能/可不可以)＋讓＋我＋VP","e":"(Can/May) + ràng + wǒ + VP","k":"(~해 줄 수 있어?) ＋ 讓 ＋ 我 ＋ VP"},"ex":{"j":"「讓2」は相手に許可を求めたり与えたりする時に使う。因果関係を表す「讓1」とは異なり、能不能・可不可以などと一緒に使うと丁寧な依頼になる。「讓」だけで言い切ると命令的に聞こえることがある。","e":"讓2 is used to ask for or grant permission. Unlike causative 讓1, pairing it with 能不能/可以 makes a polite request; using 讓 alone can sound like a command.","k":"讓2는 상대에게 허락을 구하거나 줄 때 쓴다. 인과관계를 나타내는 讓1과 달리, 能不能/可以와 함께 쓰면 정중한 부탁이 되며, 讓만 단독으로 쓰면 명령처럼 들릴 수 있다."},"eg":[{"z":"能不能<em>讓</em>我在這裡坐著休息一下？","py":"Néng bù néng ràng wǒ zài zhèlǐ zuòzhe xiūxí yíxià?","j":"ここに座って少し休ませてもらえますか?","e":"Could you let me sit here and rest for a bit?","k":"여기 앉아서 좀 쉬게 해 주시겠어요?"},{"z":"請<em>讓</em>我看一下你的護照。","py":"Qǐng ràng wǒ kàn yíxià nǐ de hùzhào.","j":"あなたのパスポートをちょっと見せてください。","e":"Please let me take a look at your passport.","k":"여권 좀 보여 주세요."}]},
{"id":"g3-115","cat":"特殊構文","t":"叫1","g":{"j":"〜に…するように言う/命じる","e":"to tell/order someone to do something","k":"~에게 …하라고 하다"},"p":{"j":"A＋叫＋B＋VP","e":"A + jiào + B + VP (A tells B to VP)","k":"A ＋ 叫 ＋ B ＋ VP"},"ex":{"j":"「叫1」は誰かが他人に直接口頭で指示・命令することを表す使役動詞。構造は「讓1」に似るが、讓が間接的な原因も含むのに対し、叫は話し手の口頭での指示というニュアンスが強い。","e":"A causative verb meaning someone verbally instructs another person. Structurally similar to 讓1, but 叫 carries a stronger nuance of a direct spoken order, while 讓 covers broader indirect causes.","k":"叫1은 누군가가 다른 사람에게 직접 말로 지시·명령함을 나타내는 사역동사이다. 구조는 讓1과 비슷하지만, 讓이 간접적인 원인까지 포괄하는 데 비해 叫는 화자의 구두 지시라는 뉘앙스가 강하다."},"eg":[{"z":"老闆<em>叫</em>我下午跟他一起去開會。","py":"Lǎobǎn jiào wǒ xiàwǔ gēn tā yìqǐ qù kāihuì.","j":"上司は私に午後彼と一緒に会議に行くように言った。","e":"My boss told me to go to the meeting with him this afternoon.","k":"사장님은 나에게 오후에 그와 함께 회의에 가라고 했다."},{"z":"媽媽<em>叫</em>我回家吃晚飯。","py":"Māma jiào wǒ huí jiā chī wǎnfàn.","j":"お母さんは私に家に帰って晩ご飯を食べるように言った。","e":"Mom told me to come home and eat dinner.","k":"엄마는 나에게 집에 가서 저녁을 먹으라고 했다."}]},
{"id":"g3-116","cat":"特殊構文","t":"叫2","g":{"j":"「叫」で人に何かをさせる(使役)","e":"to tell/have someone do something (causative)","k":"누군가에게 무엇을 시키다(사역)"},"p":{"j":"A ＋ 叫 ＋ B ＋ 動詞句","e":"A + 叫 + B + Verb Phrase","k":"A ＋ 叫 ＋ B ＋ 동사구"},"ex":{"j":"「叫」は使役を表し、「A叫B＋動詞」でAがBに何かをさせる/頼むという意味。「請」より直接的で、「讓」よりやや強制的なニュアンスを持つ。","e":"\"叫\" expresses causation: \"A 叫 B + verb\" means A tells/has B do something, with a nuance of ordering or requesting. It is more direct than \"請\" and slightly more forceful than \"讓.\"","k":"\"叫\"는 사역을 나타내며 \"A 叫 B ＋ 동사\"는 A가 B에게 무엇을 시키다/부탁하다는 뜻이다. \"請\"보다 직접적이고 \"讓\"보다 강제성이 약간 더 있다."},"eg":[{"z":"我<em>叫人去買便當回來</em>。","py":"Wǒ jiào rén qù mǎi biàndāng huílai.","j":"私は人に弁当を買って来てもらった。","e":"I told someone to go buy lunch boxes and bring them back.","k":"나는 누군가에게 도시락을 사 오라고 시켰다."},{"z":"媽媽<em>叫我去倒垃圾</em>。","py":"Māma jiào wǒ qù dào lèsè.","j":"お母さんは私にゴミを捨てるように言った。","e":"Mom told me to take out the trash.","k":"엄마가 나한테 쓰레기를 버리라고 시켰다."}]},
{"id":"g3-117","cat":"疑問","t":"呢2","g":{"j":"疑問詞疑問文の文末に添えて語気を和らげる","e":"softens a wh-question at the end of the sentence","k":"의문사 의문문 끝에서 어기를 부드럽게 함"},"p":{"j":"疑問詞 ＋ ... ＋ 呢?","e":"Question word + ... + 呢?","k":"의문사 ＋ ... ＋ 呢?"},"ex":{"j":"疑問詞(什麼、誰、哪裡、怎麼など)を使った疑問文の文末に置く「呢」は、語気を和らげ、答えを期待する気持ちを添える。「你呢?」のような省略疑問文の「呢」とは別の用法。","e":"\"呢\" placed at the end of a wh-question (什麼, 誰, 哪裡, 怎麼, etc.) softens the tone and shows the speaker is genuinely wondering. This differs from the \"呢\" used in short elliptical questions like \"你呢?\"","k":"의문사(什麼, 誰, 哪裡, 怎麼 등)를 쓴 의문문 끝에 붙는 \"呢\"는 어기를 부드럽게 하고 답을 기대하는 느낌을 더한다. \"你呢?\"처럼 생략형 질문에 쓰이는 \"呢\"와는 다른 용법이다."},"eg":[{"z":"你什麼時候可以開始工作<em>呢</em>？","py":"Nǐ shénme shíhòu kěyǐ kāishǐ gōngzuò ne?","j":"あなたはいつから仕事を始められますか。","e":"When can you start working?","k":"당신은 언제 일을 시작할 수 있어요?"},{"z":"這件事到底是誰做的<em>呢</em>？","py":"Zhè jiàn shì dàodǐ shì shéi zuò de ne?","j":"これは一体誰がやったのだろう。","e":"Who on earth did this?","k":"이건 도대체 누가 한 거야?"}]},
{"id":"g3-118","cat":"疑問","t":"沒（有）2","g":{"j":"文末に「沒有」を置いて「〜したかどうか」を尋ねる","e":"placing \"沒有\" at the end of a sentence to ask whether something has happened","k":"문장 끝에 \"沒有\"를 놓아 \"~했는지 안 했는지\"를 묻음"},"p":{"j":"V(過) ＋ O ＋ 沒有?","e":"V(過) + O + 沒有?","k":"V(過) ＋ O ＋ 沒有?"},"ex":{"j":"「V(過)＋O＋沒有?」は「有沒有VP」と同じく経験・完了の有無を尋ねる疑問文で、文末の「沒有」が「嗎」の代わりになる。「了沒」とほぼ同じ意味で、話し言葉でよく使われる。","e":"\"V(過) + O + 沒有?\" asks whether an action has happened or been experienced, with \"沒有\" at the end functioning like \"嗎.\" It is close in meaning to \"了沒\" and common in speech.","k":"\"V(過)+O+沒有?\"는 \"有沒有VP\"처럼 경험이나 완료 여부를 묻는 의문문으로, 문장 끝의 \"沒有\"가 \"嗎\" 역할을 한다. \"了沒\"와 뜻이 비슷하며 구어에서 자주 쓰인다."},"eg":[{"z":"你們參觀過校園<em>沒有</em>？","py":"Nǐmen cānguānguò xiàoyuán méiyǒu?","j":"あなたたちはキャンパスを見学したことがありますか。","e":"Have you all visited the campus?","k":"여러분은 캠퍼스를 견학한 적이 있어요?"},{"z":"你吃過臭豆腐<em>沒有</em>？","py":"Nǐ chīguò chòudòufu méiyǒu?","j":"臭豆腐を食べたことがありますか。","e":"Have you eaten stinky tofu before?","k":"취두부를 먹어본 적이 있어요?"}]},
{"id":"g3-119","cat":"助動詞","t":"必須","g":{"j":"「必ず〜しなければならない」という強い義務","e":"must / have to (strong obligation)","k":"반드시 ~해야 한다(강한 의무)"},"p":{"j":"主語 ＋ 必須 ＋ 動詞句","e":"Subject + 必須 + Verb Phrase","k":"주어 ＋ 必須 ＋ 동사구"},"ex":{"j":"「必須」は客観的な規則や状況から生じる強い義務を表し、「應該」(〜すべき、勧め)より語気が強く、選択の余地がない。否定は「不必」(〜する必要はない)を使い、「不必須」とは言わない。","e":"\"必須\" expresses a strong, often objective obligation, stronger than \"應該\" (should), leaving no room for choice. Its negation is \"不必\" (not necessary), never \"不必須.\"","k":"\"必須\"는 객관적인 규칙이나 상황에서 오는 강한 의무를 나타내며 \"應該\"(~해야 한다, 권유)보다 어기가 강하고 선택의 여지가 없다. 부정형은 \"不必\"를 쓰며 \"不必須\"라고 하지 않는다."},"eg":[{"z":"這場會議很重要，你<em>必須</em>準時參加。","py":"Zhè chǎng huìyì hěn zhòngyào, nǐ bìxū zhǔnshí cānjiā.","j":"この会議はとても重要なので、あなたは必ず時間通りに参加しなければならない。","e":"This meeting is very important, so you must attend on time.","k":"이 회의는 매우 중요하니 당신은 반드시 제시간에 참석해야 한다."},{"z":"明天要考試，你今天晚上<em>必須</em>好好複習。","py":"Míngtiān yào kǎoshì, nǐ jīntiān wǎnshang bìxū hǎohāo fùxí.","j":"明日試験があるので、あなたは今夜しっかり復習しなければならない。","e":"There's a test tomorrow, so you must review carefully tonight.","k":"내일 시험이 있어서 당신은 오늘 밤 반드시 열심히 복습해야 한다."}]},
{"id":"g3-120","cat":"介詞","t":"到","g":{"j":"「〜まで」という範囲・到達点を表す","e":"to/until — marking the endpoint of a range","k":"\"~까지\"라는 범위나 도달점을 나타냄"},"p":{"j":"(從)A ＋ 到 ＋ B","e":"(從) A + 到 + B","k":"(從) A ＋ 到 ＋ B"},"ex":{"j":"「到」は起点(從/由などで示す)から終点までの範囲・到達点を表す用法。「從A到B」の形でよく使われ、時間・場所・順序のいずれにも使える。単独の動詞「到」(着く)との違いに注意。","e":"\"到\" here marks the endpoint of a range from a starting point (often with 從/由), used for time, place, or sequence, as in \"從A到B.\" Distinguish this from the verb \"到\" meaning \"to arrive.\"","k":"\"到\"는 시작점(從/由 등으로 표시)에서 끝점까지의 범위나 도달점을 나타내는 용법으로, \"從A到B\" 형태로 자주 쓰이며 시간·장소·순서 모두에 쓸 수 있다. \"도착하다\"라는 동사 \"到\"와 구별해야 한다."},"eg":[{"z":"三年級<em>到</em>六年級的同學，下課後都要留下來練習跳舞。","py":"Sān niánjí dào liù niánjí de tóngxué, xiàkè hòu dōu yào liú xiàlái liànxí tiàowǔ.","j":"三年生から六年生までの生徒は、放課後みんな残ってダンスの練習をしなければならない。","e":"Students from third grade to sixth grade all have to stay after school to practice dancing.","k":"3학년부터 6학년까지의 학생들은 방과 후에 모두 남아서 춤 연습을 해야 한다."},{"z":"這家店星期一<em>到</em>星期五都有營業。","py":"Zhè jiā diàn xīngqíyī dào xīngqíwǔ dōu yǒu yíngyè.","j":"この店は月曜日から金曜日まで営業しています。","e":"This shop is open from Monday to Friday.","k":"이 가게는 월요일부터 금요일까지 영업한다."}]},
{"id":"g3-121","cat":"接続","t":"要是......就......","g":{"j":"もし〜なら、〜","e":"if... then...","k":"만약 ~하면 ~하다"},"p":{"j":"要是Ａ，就Ｂ","e":"yàoshi A, jiù B","k":"要是A, 就B"},"ex":{"j":"「要是」は口語的な仮定を表し、後半の「就」と組み合わせて結果や指示を導く。「如果」より話し言葉的で日常会話に多い。「就」を落としやすいので注意。","e":"\"要是\" introduces a casual, spoken conditional and pairs with \"就\" to state the result or instruction. It's more colloquial than \"如果\"; learners often forget to add \"就\" in the second clause.","k":"\"要是\"는 구어체 조건문을 나타내며 뒤에 오는 \"就\"와 함께 결과나 지시를 나타낸다. \"如果\"보다 회화적이며 \"就\"를 빠뜨리기 쉬우니 주의해야 한다."},"eg":[{"z":"你<em>要是</em>發燒，今天<em>就</em>在家休息吧。","py":"Nǐ yàoshì fāshāo, jīntiān jiù zài jiā xiūxí ba.","j":"もし熱が出たら、今日は家で休んでね。","e":"If you have a fever, stay home and rest today.","k":"열이 나면 오늘은 집에서 쉬어."},{"z":"你<em>要是</em>不舒服，<em>就</em>早點回家休息。","py":"Nǐ yàoshì bù shūfu, jiù zǎodiǎn huíjiā xiūxí.","j":"もし調子が悪かったら、早めに帰って休んでね。","e":"If you're not feeling well, go home early and rest.","k":"몸이 안 좋으면 일찍 집에 가서 쉬어."}]},
{"id":"g3-122","cat":"接続","t":"......的話","g":{"j":"〜なら、〜の場合は","e":"if... (in that case)","k":"~하면, ~인 경우에는"},"p":{"j":"Ａ的話，就Ｂ","e":"A dehuà, jiù B","k":"A的話, 就B"},"ex":{"j":"「的話」は条件節の後に置いて仮定を強調する口語表現で、「要是」「如果」と一緒に使うことも、単独で使うこともできる。","e":"\"的話\" is placed after a clause to mark a spoken hypothesis; it can combine with \"要是/如果\" or stand alone to form a conditional sentence.","k":"\"的話\"는 조건절 뒤에 붙어 가정을 나타내는 구어체 표현으로, \"要是/如果\"와 함께 쓰거나 단독으로도 가정문을 만들 수 있다."},"eg":[{"z":"<em>下雨的話</em>，我就不去了。","py":"Xiàyǔ dehuà, wǒ jiù bú qù le.","j":"雨が降るなら、私は行きません。","e":"If it rains, I won't go.","k":"비가 오면 저는 안 갈 거예요."},{"z":"明天<em>下雪的話</em>，我們就不出門了。","py":"Míngtiān xiàxuě dehuà, wǒmen jiù bù chūmén le.","j":"明日雪が降るなら、私たちは外出しません。","e":"If it snows tomorrow, we won't go out.","k":"내일 눈이 오면 우리는 밖에 안 나갈 거예요."}]},
{"id":"g3-123","cat":"比較","t":"A沒有B（這/那麼）......","g":{"j":"AはBほど〜ではない","e":"A is not as... as B","k":"A는 B만큼 ~하지 않다"},"p":{"j":"Ａ沒有Ｂ（這麼/那麼）＋形容詞","e":"A méiyǒu B (zhème/nàme) + adjective","k":"A沒有B (這麼/那麼) + 형용사"},"ex":{"j":"AとBを比べ、Aの程度がBに及ばないことを表す否定比較構文。「A比B〜」の逆方向の比較として覚えるとよい。","e":"This compares A and B, showing A falls short of B's degree — a negative comparison, the reverse direction of \"A比B...\".","k":"A와 B를 비교하여 A의 정도가 B에 못 미침을 나타내는 부정 비교 구문으로, \"A比B~\"의 반대 방향 비교로 이해하면 좋다."},"eg":[{"z":"事情<em>沒有你想的那麼</em>嚴重。","py":"Shìqíng méiyǒu nǐ xiǎng de nàme yánzhòng.","j":"事態はあなたが思っているほど深刻ではありません。","e":"The situation isn't as serious as you think.","k":"상황은 네가 생각하는 것만큼 심각하지 않아."},{"z":"這次考試<em>沒有</em>上次<em>那麼</em>難。","py":"Zhè cì kǎoshì méiyǒu shàng cì nàme nán.","j":"今回の試験は前回ほど難しくありませんでした。","e":"This exam wasn't as hard as the last one.","k":"이번 시험은 지난번만큼 어렵지 않았어요."}]},
{"id":"g3-124","cat":"接続","t":"不但......而且......","g":{"j":"〜だけでなく、さらに〜","e":"not only... but also...","k":"~뿐만 아니라 게다가 ~"},"p":{"j":"不但Ａ，而且Ｂ","e":"búdàn A, érqiě B","k":"不但A, 而且B"},"ex":{"j":"前後の主語が同じときに使う累加構文で、Bの程度や範囲がAより強まることを示す。「而且」はやや書き言葉寄りで丁寧な印象。","e":"Used when both clauses share the same subject, showing B intensifies or adds to A. \"而且\" leans slightly more formal/written than \"還/也\".","k":"앞뒤 절의 주어가 같을 때 쓰는 첨가 구문으로, B가 A보다 정도나 범위가 더 강해짐을 나타낸다. \"而且\"는 \"還/也\"보다 약간 문어체적이다."},"eg":[{"z":"這個故事<em>不但</em>容易了解，<em>而且</em>很有意思。","py":"Zhège gùshi búdàn róngyì liǎojiě, érqiě hěn yǒuyìsi.","j":"この物語は理解しやすいだけでなく、とても面白いです。","e":"This story is not only easy to understand, but also very interesting.","k":"이 이야기는 이해하기 쉬울 뿐만 아니라 아주 재미있어요."},{"z":"這家餐廳<em>不但</em>便宜，<em>而且</em>很好吃。","py":"Zhè jiā cāntīng búdàn piányi, érqiě hěn hǎochī.","j":"このレストランは安いだけでなく、とてもおいしいです。","e":"This restaurant is not only cheap, but also very delicious.","k":"이 식당은 저렴할 뿐만 아니라 아주 맛있어요."}]},
{"id":"g3-125","cat":"接続","t":"不但......還/也......","g":{"j":"〜だけでなく、〜も","e":"not only... but also...","k":"~뿐만 아니라 ~도"},"p":{"j":"不但Ａ，還/也Ｂ","e":"búdàn A, hái/yě B","k":"不但A, 還/也B"},"ex":{"j":"不但……而且……と似た累加構文だが、「還/也」を使うと口語的で軽い印象になり、日常会話ではこちらの方がよく使われる。","e":"A similar additive structure to \"不但……而且……\", but using \"還/也\" sounds more casual and is more common in everyday spoken Mandarin than \"而且\".","k":"\"不但……而且……\"와 비슷한 첨가 구문이지만, \"還/也\"를 쓰면 더 구어체적이고 일상 회화에서 \"而且\"보다 자주 쓰인다."},"eg":[{"z":"在超商<em>不但</em>可以買東西<em>還</em>可以寄東西。","py":"Zài chāoshāng búdàn kěyǐ mǎi dōngxi hái kěyǐ jì dōngxi.","j":"コンビニでは買い物ができるだけでなく、荷物を送ることもできます。","e":"At the convenience store, you can not only buy things but also send packages.","k":"편의점에서는 물건을 살 수 있을 뿐만 아니라 물건을 보낼 수도 있어요."},{"z":"這個手機<em>不但</em>便宜<em>也</em>很好用。","py":"Zhège shǒujī búdàn piányi yě hěn hǎoyòng.","j":"この携帯電話は安いだけでなく、とても使いやすいです。","e":"This phone is not only cheap but also very easy to use.","k":"이 휴대폰은 저렴할 뿐만 아니라 아주 쓰기 편해요."}]},
{"id":"g3-126","cat":"接続","t":"而且","g":{"j":"そのうえ、しかも(情報の追加・強調)","e":"moreover, and also","k":"게다가, 그리고"},"p":{"j":"A，而且 B(Bで程度の強い情報を追加)","e":"A, érqiě B (adds further, often stronger, information)","k":"A, 而且 B (더 강조된 정보를 덧붙임)"},"ex":{"j":"而且は前の内容にさらに情報を加えて強調する時に使う。逆接の「但是」と混同しないこと。「不但…而且…」の形で使うこともあるが、単独でも使える。","e":"Use 而且 to add further, often intensifying, information to what was just said. Don't confuse it with the contrastive 但是; 而且 can stand alone or pair with 不但.","k":"而且는 앞 내용에 강조된 정보를 덧붙일 때 쓴다. 역접의 但是와 혼동하지 말 것. 不但…而且…로 짝을 이루기도 하지만 단독으로도 쓸 수 있다."},"eg":[{"z":"臺灣夏天很熱，<em>而且</em>很濕。","py":"Táiwān xiàtiān hěn rè, érqiě hěn shī.","j":"台湾の夏はとても暑くて、しかも湿気が多い。","e":"Summer in Taiwan is very hot, and moreover very humid.","k":"대만의 여름은 매우 덥고, 게다가 습해요."},{"z":"這家餐廳的東西很好吃，<em>而且</em>不貴。","py":"Zhè jiā cāntīng de dōngxi hěn hǎochī, érqiě bú guì.","j":"このレストランの料理はおいしいし、しかも高くない。","e":"The food at this restaurant is delicious, and moreover it's not expensive.","k":"이 식당 음식은 맛있고, 게다가 비싸지 않아요."}]},
{"id":"g3-127","cat":"副詞","t":"真Vs","g":{"j":"本当に〜だ(感嘆・強調)","e":"really/truly + adjective (emphasis)","k":"정말 ~하다(강조)"},"p":{"j":"真 ＋ Vs(形容詞・狀態動詞)","e":"zhēn + Vs (stative verb/adjective)","k":"真 + Vs(형용사·상태동사)"},"ex":{"j":"「真」は話者の感嘆や強調した気持ちを表し、「很」より感情がこもる。事実確認を表す「真的」と混同しないよう注意。","e":"真 expresses the speaker's genuine feeling or exclamation, stronger in tone than 很. Don't confuse it with 真的, which confirms that something is actually true.","k":"真는 화자의 감탄·강조된 감정을 나타내며 很보다 어감이 강하다. 사실을 확인하는 真的와 혼동하지 말 것."},"eg":[{"z":"那個房子<em>真不錯</em>，而且就在學校附近。","py":"Nàge fángzi zhēn búcuò, érqiě jiù zài xuéxiào fùjìn.","j":"あの家は本当にいいし、しかも学校のすぐ近くにある。","e":"That house is really great, and it's right near the school too.","k":"그 집은 정말 괜찮고, 게다가 학교 바로 근처에 있어요."},{"z":"這杯珍珠奶茶<em>真好喝</em>。","py":"Zhè bēi zhēnzhū nǎichá zhēn hǎohē.","j":"このタピオカミルクティーは本当においしい。","e":"This bubble tea is really delicious.","k":"이 버블티는 정말 맛있어요."}]},
{"id":"g3-128","cat":"特殊構文","t":"越......越......","g":{"j":"〜すればするほど〜(二つの変化が連動)","e":"the more... the more...","k":"~할수록 ~하다"},"p":{"j":"越 A 越 B(A・Bは同じ主語の動作/性質)","e":"yuè + A + yuè + B (A and B share the same subject)","k":"越 A 越 B(A, B는 같은 주어의 동작·상태)"},"ex":{"j":"越A越Bは、Aの程度が増すにつれBも強まることを表す。時間経過による変化を表す「越來越」と混同しないよう注意。","e":"越A越B shows that as A intensifies, B intensifies too, both from the same subject. Don't confuse it with 越來越, which describes one thing changing over time, not two linked actions.","k":"越A越B는 A가 심해질수록 B도 같이 심해짐을 나타낸다. 시간에 따른 변화를 나타내는 越來越와 혼동하지 말 것."},"eg":[{"z":"颱風來了，雨<em>越下越大</em>。","py":"Táifēng lái le, yǔ yuè xià yuè dà.","j":"台風が来て、雨は降れば降るほど激しくなった。","e":"The typhoon came, and the rain got heavier and heavier as it fell.","k":"태풍이 와서 비가 내릴수록 더 세게 내렸다."},{"z":"他<em>越說越生氣</em>。","py":"Tā yuè shuō yuè shēngqì.","j":"彼は話せば話すほど怒った。","e":"The more he talked, the angrier he got.","k":"그는 말할수록 더 화를 냈다."}]},
{"id":"g3-129","cat":"副詞","t":"越來越......","g":{"j":"だんだん〜になる(時間経過での変化)","e":"more and more / increasingly","k":"점점 더 ~해지다"},"p":{"j":"越來越 ＋ Vs(形容詞)","e":"yuè lái yuè + Vs (adjective/stative verb)","k":"越來越 + Vs(형용사)"},"ex":{"j":"越來越は時間の経過に伴う一方向の変化を表し、後ろは形容詞が多く、文末に「了」を伴うことが多い。二つの動作が連動する「越A越B」と混同しないこと。","e":"越來越 marks a one-directional change over time, usually followed by an adjective and often ending with 了. Don't confuse it with 越A越B, which links two different actions or qualities.","k":"越來越는 시간에 따른 한 방향의 변화를 나타내며 보통 형용사가 뒤에 오고 문장 끝에 了를 자주 쓴다. 두 동작이 연동되는 越A越B와 혼동하지 말 것."},"eg":[{"z":"他的中文<em>越來越好</em>了。","py":"Tā de Zhōngwén yuè lái yuè hǎo le.","j":"彼の中国語はだんだん上手になってきた。","e":"His Chinese has been getting better and better.","k":"그의 중국어는 점점 좋아지고 있어요."},{"z":"天氣<em>越來越冷</em>了。","py":"Tiānqì yuè lái yuè lěng le.","j":"天気はだんだん寒くなってきた。","e":"The weather has been getting colder and colder.","k":"날씨가 점점 추워지고 있어요."}]},
{"id":"g3-130","cat":"副詞","t":"本來","g":{"j":"元々、もともと(以前の状態や予定)","e":"originally, at first","k":"원래, 본래"},"p":{"j":"本來 ＋ A，後來/可是 ＋ B(A→Bへの対比)","e":"běnlái + A, hòulái/kěshì + B (contrast between the original state A and the later state B)","k":"本來 + A, 後來/可是 + B(원래 상태A와 나중 상태B의 대비)"},"ex":{"j":"本來は変化前の状態や予定を述べ、後ろに「後來」「可是」などで結果と対比させる。単独では使えず、対比の後半が必要な点に注意。","e":"本來 states the original situation or plan before a change, usually paired with 後來 or 可是 to show the contrast. It needs a following clause with the changed result — it can't stand alone.","k":"本來는 변화 전의 원래 상태나 계획을 말하며 보통 後來, 可是와 함께 대비되는 결과를 뒤에 써야 한다. 단독으로 쓸 수 없다는 점에 주의."},"eg":[{"z":"我們<em>本來</em>不認識，後來聊了一下就熟了。","py":"Wǒmen běnlái bú rènshi, hòulái liáo le yíxià jiù shú le.","j":"私たちは元々知り合いではなかったが、後で少し話したらすぐ親しくなった。","e":"We didn't know each other at first, but after chatting a bit we quickly became close.","k":"우리는 원래 서로 몰랐는데, 나중에 잠깐 이야기하고 나서 금방 친해졌어요."},{"z":"我<em>本來</em>打算今天出門，可是下雨了。","py":"Wǒ běnlái dǎsuàn jīntiān chūmén, kěshì xià yǔ le.","j":"私はもともと今日出かけるつもりだったが、雨が降ってしまった。","e":"I originally planned to go out today, but it started raining.","k":"저는 원래 오늘 나가려고 했는데, 비가 와서요."}]},
{"id":"g3-131","cat":"接続","t":"然後","g":{"j":"それから(順序を表す)","e":"then / after that (sequence)","k":"그다음에(순서를 나타냄)"},"p":{"j":"A，然後 B","e":"A, ránhòu B","k":"A, 然後 B"},"ex":{"j":"「然後」は動作や出来事を順番につなぐときに使う。同じ級の「先...再...」とセットで使われることが多いが、「然後」は単独でも文と文をつなげる。話し言葉で乱用しやすいので、書き言葉では簡潔にまとめる。「後來」(過去の出来事限定)との混同に注意。","e":"Ránhòu links actions in sequence and can start a new clause on its own, unlike hòulái, which only narrates past events, not future plans. Learners often overuse ránhòu as filler in speech; in writing, avoid chaining too many ránhòu in a row.","k":"然後는 동작을 순서대로 연결할 때 쓰며 단독으로 문장을 이어줄 수 있다. 과거 사건만 서술하는 後來와 달리 미래 계획에도 쓸 수 있다. 회화에서 然後를 남용하기 쉬우니 글에서는 반복을 피해야 한다."},"eg":[{"z":"我喜歡先吃菜再吃肉，<em>然後</em>才吃飯。","py":"Wǒ xǐhuān xiān chī cài zài chī ròu, ránhòu cái chī fàn.","j":"私はまずおかずを食べて、それから肉を食べて、最後にご飯を食べるのが好きです。","e":"I like to eat the vegetables first, then the meat, and only then the rice.","k":"저는 먼저 반찬을 먹고, 그다음에 고기를 먹고, 마지막에 밥을 먹는 걸 좋아해요."},{"z":"我先寫功課，<em>然後</em>看電視。","py":"Wǒ xiān xiě gōngkè, ránhòu kàn diànshì.","j":"私はまず宿題をして、それからテレビを見ます。","e":"I do my homework first, and then watch TV.","k":"저는 먼저 숙제를 하고 그다음에 텔레비전을 봐요."}]},
{"id":"g3-132","cat":"接続","t":"一邊......一邊......","g":{"j":"〜しながら〜する(同時進行)","e":"doing two things at the same time","k":"~하면서 ~하다(동시 진행)"},"p":{"j":"A ＋ 一邊 + 動詞1 ＋ 一邊 + 動詞2","e":"A + yìbiān + Verb1 + yìbiān + Verb2","k":"A + 一邊 + 동사1 + 一邊 + 동사2"},"ex":{"j":"「一邊」は同じ人が同時に2つの動作をする時に使い、必ず動詞の前に2回繰り返す。主語は共通で1つだけ。物理的に同時にできない動作(例:寝ながら歩く)には使えない点に注意。","e":"Yìbiān...yìbiān... needs one single subject doing two actions simultaneously, and yìbiān must be repeated before each verb. Avoid pairing actions that can't physically happen at once.","k":"一邊은 같은 주어가 동시에 두 동작을 할 때 쓰며 각 동사 앞에 반드시 반복해야 한다. 물리적으로 동시에 할 수 없는 동작에는 쓸 수 없다."},"eg":[{"z":"他<em>一邊</em>吃飯<em>一邊</em>看手機。","py":"Tā yìbiān chīfàn yìbiān kàn shǒujī.","j":"彼はご飯を食べながらスマホを見ています。","e":"He is eating while looking at his phone.","k":"그는 밥을 먹으면서 휴대폰을 봐요."},{"z":"她<em>一邊</em>聽音樂<em>一邊</em>做作業。","py":"Tā yìbiān tīng yīnyuè yìbiān zuò zuòyè.","j":"彼女は音楽を聞きながら宿題をします。","e":"She does her homework while listening to music.","k":"그녀는 음악을 들으면서 숙제를 해요."}]},
{"id":"g3-133","cat":"接続","t":"先......再......","g":{"j":"まず〜、それから〜(順序)","e":"first...then... (sequence of actions)","k":"먼저 ~하고 그다음에 ~하다(순서)"},"p":{"j":"先 ＋ 動詞1 ＋ 再 ＋ 動詞2","e":"Xiān + Verb1 + zài + Verb2","k":"先 + 동사1 + 再 + 동사2"},"ex":{"j":"「先...再...」は同じ人が2つの動作をこの順番で行うことを表す。ここでの「再」は「もう一度」ではなく「それから」の意味である点に注意。「然後」より順序性を強く示し、順番を守ることが重要な場面でよく使われる。","e":"Xiān...zài... marks the fixed order of two actions by the same subject. Note zài here means 'then', not 'again' (its more common meaning). It stresses sequence more strongly than ránhòu, which just links clauses loosely.","k":"先...再...는 같은 사람이 정해진 순서로 두 동작을 하는 것을 나타낸다. 여기서 再는 '다시'가 아니라 '그다음에'라는 뜻임에 주의해야 한다. 然後보다 순서를 더 강조한다."},"eg":[{"z":"大家<em>先</em>找位子<em>再</em>點菜。","py":"Dàjiā xiān zhǎo wèizi zài diǎncài.","j":"みんなは先に席を探して、それから料理を注文します。","e":"Everyone finds a seat first, then orders food.","k":"다들 먼저 자리를 찾고 그다음에 음식을 주문해요."},{"z":"我<em>先</em>洗手<em>再</em>吃飯。","py":"Wǒ xiān xǐshǒu zài chīfàn.","j":"私はまず手を洗ってからご飯を食べます。","e":"I wash my hands first and then eat.","k":"저는 먼저 손을 씻고 나서 밥을 먹어요."}]},
{"id":"g3-134","cat":"アスペクト","t":"就要......了","g":{"j":"もうすぐ〜する(近い未来)","e":"about to happen soon","k":"곧 ~하려고 하다(가까운 미래)"},"p":{"j":"(時間詞) ＋ 就要 ＋ 動詞/形容詞 ＋ 了","e":"(Time word) + jiù yào + Verb/Adj + le","k":"(시간사) + 就要 + 동사/형용사 + 了"},"ex":{"j":"「就要...了」は近い未来に何かが起こることを表し、「下個星期」のような具体的な時間詞と一緒によく使われる。次の項目「快要...了」との大きな違いは、「快要」は原則として具体的な未来の時間詞(明天など)の前には置けない点である。","e":"Jiù yào...le marks something about to happen soon and often pairs with a specific time word like xià ge xīngqī. A key contrast with kuàiyào...le (the next point) is that kuàiyào generally cannot follow a specific future time word like míngtiān.","k":"就要...了는 가까운 미래에 일어날 일을 나타내며 下個星期 같은 구체적 시간사와 자주 함께 쓰인다. 다음 항목인 快要...了와 달리, 快要는 明天처럼 구체적인 미래 시간사 앞에는 원칙적으로 쓸 수 없다."},"eg":[{"z":"下個星期<em>就要</em>開學<em>了</em>。","py":"Xià ge xīngqí jiù yào kāixué le.","j":"来週もうすぐ学校が始まります。","e":"School is about to start next week.","k":"다음 주에 곧 개학해요."},{"z":"火車<em>就要</em>到站<em>了</em>。","py":"Huǒchē jiù yào dào zhàn le.","j":"列車はもうすぐ駅に到着します。","e":"The train is about to arrive at the station.","k":"기차가 곧 역에 도착해요."}]},
{"id":"g3-135","cat":"アスペクト","t":"快要......了","g":{"j":"もうすぐ〜する(近い未来)","e":"about to happen soon","k":"곧 ~하려고 하다(가까운 미래)"},"p":{"j":"(主語) ＋ 快要 ＋ 動詞/形容詞 ＋ 了","e":"(Subject) + kuàiyào + Verb/Adj + le","k":"(주어) + 快要 + 동사/형용사 + 了"},"ex":{"j":"「快要...了」は「就要...了」とほぼ同じ意味で近い未来を表すが、「明天」「下星期」のような具体的な未来の時間詞の直前には置けない点が違う。誤って「明天快要...了」と言わないように注意し、その場合は「就要」を使う。","e":"Kuàiyào...le is close in meaning to jiù yào...le, but unlike jiù yào it cannot directly follow a specific future time word such as míngtiān or xià xīngqī. A common mistake is saying míngtiān kuàiyào...le — use jiù yào there instead.","k":"快要...了는 就要...了와 뜻이 비슷하지만, 明天이나 下星期처럼 구체적인 미래 시간사 바로 뒤에는 쓸 수 없다는 점이 다르다. 明天快要...了처럼 쓰지 않도록 주의하고, 그 경우에는 就要를 써야 한다."},"eg":[{"z":"暑假<em>快要</em>結束<em>了</em>。","py":"Shǔjià kuàiyào jiéshù le.","j":"夏休みはもうすぐ終わります。","e":"Summer vacation is about to end.","k":"여름 방학이 곧 끝나요."},{"z":"妹妹<em>快要</em>哭<em>了</em>。","py":"Mèimei kuàiyào kū le.","j":"妹はもうすぐ泣きそうです。","e":"My younger sister is about to cry.","k":"여동생이 곧 울 것 같아요."}]},
{"id":"g3-136","cat":"補語","t":"V一下","g":{"j":"動詞＋一下(ちょっと〜する)","e":"V + 一下 (do something briefly)","k":"동사+一下(잠깐 ~하다)"},"p":{"j":"Ｖ＋一下","e":"V + 一下","k":"V + 一下"},"ex":{"j":"動詞の後の「一下」は動作を軽く・短くし、依頼や提案を柔らかくする。回数を数える「一次」と混同しないこと。動詞を重ねる形(看看)とほぼ同じ働きだが、口語でより頻繁に使われる。","e":"\"V一下\" softens a verb into a brief, casual action or polite request (\"just take a look\"). Don't confuse it with \"V一次\", which counts occurrences. It works like verb reduplication (看看) but is far more common in speech.","k":"동사 뒤의 \"一下\"는 동작을 짧고 가볍게 만들거나 요청을 부드럽게 한다. 횟수를 세는 \"一次\"와 혼동하지 말 것. 동사 중첩(看看)과 기능은 비슷하지만 회화에서 훨씬 자주 쓰인다."},"eg":[{"z":"我帶你去附近的圖書館<em>參觀一下</em>。","py":"Wǒ dài nǐ qù fùjìn de túshūguǎn cānguān yíxià.","j":"私があなたを近くの図書館に案内して、ちょっと見学させてあげます。","e":"I'll take you to the nearby library to have a look around.","k":"제가 당신을 근처 도서관에 데려가서 좀 둘러보게 해 줄게요."},{"z":"你<em>等我一下</em>，我馬上回來。","py":"Nǐ děng wǒ yíxià, wǒ mǎshàng huílái.","j":"ちょっと待っててください、すぐ戻ります。","e":"Wait for me a moment, I'll be right back.","k":"잠깐만 기다려 주세요, 금방 돌아올게요."}]},
{"id":"g3-137","cat":"接続","t":"（當）......的時候","g":{"j":"（當）〜の時","e":"(When) ...的時候 (during the time when)","k":"(當) ~할 때"},"p":{"j":"（當）Ａ的時候，Ｂ","e":"(When) A 的時候, B","k":"(當) A 的時候, B"},"ex":{"j":"「(當)〜的時候」はある動作・状態が起きているまさにその時間帯を表す。「當」は書き言葉的で省略可能。仮定を表す「如果」と混同しないこと──的時候は実際の時点を、如果は仮定の条件を表す。","e":"\"(When)...的時候\" marks the time frame during which something is happening; \"當\" is optional and more literary. Don't confuse it with \"如果\" (if) — 的時候 states an actual time, while 如果 states a hypothetical condition.","k":"\"(當)~的時候\"는 어떤 일이 일어나는 바로 그 시점을 나타낸다. \"當\"은 문어체에 가까우며 생략 가능하다. 가정을 나타내는 \"如果\"와 혼동하지 말 것 — 的時候는 실제 시점을, 如果는 가정 조건을 나타낸다."},"eg":[{"z":"<em>他生氣的時候</em>，最好不要跟他開玩笑。","py":"Tā shēngqì de shíhòu, zuì hǎo bú yào gēn tā kāi wánxiào.","j":"彼が怒っている時は、彼をからかわない方がいい。","e":"When he's angry, it's best not to joke around with him.","k":"그가 화가 났을 때는 그를 놀리지 않는 게 좋다."},{"z":"<em>下雨的時候</em>，我喜歡在家看書。","py":"Xiàyǔ de shíhòu, wǒ xǐhuān zài jiā kàn shū.","j":"雨が降っている時、私は家で本を読むのが好きです。","e":"When it rains, I like to read books at home.","k":"비가 올 때, 나는 집에서 책 읽는 것을 좋아한다."}]},
{"id":"g3-138","cat":"補語","t":"V上","g":{"j":"動詞＋上(上へ／閉じる・付ける)","e":"V + 上 (upward, onto, closing)","k":"동사+上(위로/닫다·붙이다)"},"p":{"j":"Ｖ＋上","e":"V + 上","k":"V + 上"},"ex":{"j":"動詞+「上」は上へ移動する動作、または物にぴったり付く・閉じる動作(關上・穿上)を表す方向補語。下から持ち上げる動作を表す「起」と方向が違うので区別する。","e":"The verb + \"上\" directional complement shows upward movement, or attaching/closing something onto a surface (關上, 穿上). Distinguish it from \"起\", which emphasizes lifting something up from below.","k":"동사+\"上\"은 위로 이동하거나 물건에 딱 붙이거나 닫는 동작(關上, 穿上)을 나타내는 방향보어다. 아래에서 들어 올리는 동작을 강조하는 \"起\"와는 방향이 다르므로 구별해야 한다."},"eg":[{"z":"他剛剛又<em>走上</em>樓，不知去拿什麼東西。","py":"Tā gānggāng yòu zǒushàng lóu, bù zhī qù ná shénme dōngxi.","j":"彼はさっきまた階段を上って行った、何を取りに行ったのか分からない。","e":"He just went back upstairs again; I don't know what he went to get.","k":"그는 방금 또 위층으로 올라갔는데, 뭘 가지러 갔는지 모르겠다."},{"z":"請把窗戶<em>關上</em>。","py":"Qǐng bǎ chuānghù guānshàng.","j":"窓を閉めてください。","e":"Please close the window.","k":"창문을 닫아 주세요."}]},
{"id":"g3-139","cat":"補語","t":"V下","g":{"j":"動詞＋下(下へ／落ち着く)","e":"V + 下 (downward, settling into place)","k":"동사+下(아래로/자리잡다)"},"p":{"j":"Ｖ＋下","e":"V + 下","k":"V + 下"},"ex":{"j":"動詞+「下」は下へ移動する、または腰を落ち着ける動作(坐下・躺下)を表す方向補語。「寫下」のように「書き留める」という抽象的な意味にも広がる。方向が逆の「上」と混同しないよう注意。","e":"The verb + \"下\" directional complement shows downward movement or settling into a position (坐下, 躺下). It also extends to the abstract sense of \"recording\" something, as in 寫下. Don't confuse the direction with \"上\", its opposite.","k":"동사+\"下\"는 아래로 내려가거나 자리를 잡는 동작(坐下, 躺下)을 나타내는 방향보어다. 寫下처럼 '기록하다'라는 추상적 의미로도 확장된다. 반대 방향인 \"上\"과 혼동하지 않도록 주의."},"eg":[{"z":"他們選了一個離門口最近的位子<em>坐下</em>。","py":"Tāmen xuǎnle yí gè lí ménkǒu zuìjìn de wèizi zuòxià.","j":"彼らはドアに一番近い席を選んで座った。","e":"They chose the seat closest to the door and sat down.","k":"그들은 입구에서 가장 가까운 자리를 골라 앉았다."},{"z":"天氣太熱了，我們先<em>坐下</em>休息一下吧。","py":"Tiānqì tài rè le, wǒmen xiān zuòxià xiūxí yíxià ba.","j":"暑すぎるから、まず座って少し休みましょう。","e":"It's too hot, let's sit down and rest for a bit first.","k":"날씨가 너무 더우니까, 우리 먼저 앉아서 좀 쉬자."}]},
{"id":"g3-140","cat":"補語","t":"V起","g":{"j":"動詞＋起(持ち上げる)","e":"V + 起 (lift up)","k":"동사+起(들어 올리다)"},"p":{"j":"Ｖ＋起","e":"V + 起","k":"V + 起"},"ex":{"j":"動詞+「起」は下にある物を持ち上げる動作(拿起・撿起・舉起)を表す方向補語。動作の開始や変化を表すより複雑な「起來」とは区別する。","e":"The verb + \"起\" directional complement shows lifting something up from a lower position (拿起, 撿起, 舉起). Keep it distinct from \"起來\", a more complex, later-level pattern that adds a sense of an action starting or a change occurring.","k":"동사+\"起\"는 아래에 있는 것을 들어 올리는 동작(拿起, 撿起, 舉起)을 나타내는 방향보어다. 동작의 시작이나 변화를 나타내는 더 복잡한 후속 표현인 \"起來\"와는 구별해야 한다."},"eg":[{"z":"他<em>拿起</em>筆寫下電話和地址。","py":"Tā náqǐ bǐ xiěxià diànhuà hé dìzhǐ.","j":"彼はペンを手に取って、電話番号と住所を書き留めた。","e":"He picked up a pen and wrote down the phone number and address.","k":"그는 펜을 집어 들고 전화번호와 주소를 적었다."},{"z":"他從地上<em>撿起</em>一枝筆。","py":"Tā cóng dìshàng jiǎnqǐ yì zhī bǐ.","j":"彼は地面からペンを一本拾い上げた。","e":"He picked up a pen from the ground.","k":"그는 바닥에서 펜 한 자루를 주워 들었다."}]},
{"id":"g3-141","cat":"補語","t":"V滿","g":{"j":"動詞＋滿(いっぱいになる)","e":"V + 滿 (fill up)","k":"동사+滿(가득 차다)"},"p":{"j":"S ＋ V ＋ 滿 (＋了) ＋ O","e":"S + V + 滿 (+了) + O","k":"S + V + 滿(+了) + O"},"ex":{"j":"「動詞＋滿」で「〜した結果いっぱいになる」という状態補語。「滿了」の順序を間違えて「了滿」としないよう注意。単に「很多」と言い換えず、動作の結果として満ちる様子を表す点がポイント。","e":"\"V+滿\" is a result complement meaning the action fills something up completely. Common mistake: putting 了 before 滿 (should be V+滿+了). It marks the result of an action, not just \"a lot of.\"","k":"\"동사+滿\"은 동작의 결과로 가득 차게 됨을 나타내는 결과보어이다. \"滿了\"의 순서를 \"了滿\"으로 잘못 쓰지 않도록 주의. 단순히 많다는 뜻이 아니라 동작의 결과로 가득 참을 강조한다."},"eg":[{"z":"公車上<em>站滿</em>了人。","py":"Gōngchē shàng zhàn mǎn le rén.","j":"バスの中は人が立って満員になった。","e":"The bus was packed full of standing passengers.","k":"버스 안이 서 있는 사람들로 가득 찼다."},{"z":"教室裡<em>坐滿</em>了學生。","py":"Jiàoshì lǐ zuò mǎn le xuéshēng.","j":"教室に学生が座っていっぱいになった。","e":"The classroom was filled with seated students.","k":"교실 안이 앉아 있는 학생들로 가득 찼다."}]},
{"id":"g3-142","cat":"接続","t":"（也）......也......","g":{"j":"〜も〜も(両方とも)","e":"also...also... (both)","k":"~도 ~도(둘 다)"},"p":{"j":"A ＋ (也) ＋ V1，也 ＋ V2","e":"A + (也) + V1, 也 + V2","k":"A + (也) + V1, 也 + V2"},"ex":{"j":"前後の動詞句を「也」で結び、二つの事柄が両方とも成り立つことを表す。「又...又...」との違いは、「也」は選択肢や可能性の並列によく使い、「又」は同時に存在する状態・性質の並列に使う点。","e":"Links two verb phrases with 也...也... to show both things are true or possible. Different from 又...又...: 也...也... often pairs options/abilities, while 又...又... pairs simultaneous states or qualities.","k":"두 동사구를 \"也\"로 연결해 두 가지가 모두 성립함을 나타낸다. \"又...又...\"와의 차이: \"也...也...\"는 선택이나 가능성의 나열에, \"又...又...\"는 동시에 존재하는 상태·성질의 나열에 주로 쓰인다."},"eg":[{"z":"草莓可以做果汁<em>也</em>可以做蛋糕。","py":"Cǎoméi kěyǐ zuò guǒzhī yě kěyǐ zuò dàngāo.","j":"いちごはジュースも作れるし、ケーキも作れる。","e":"Strawberries can be made into juice, and also into cake.","k":"딸기는 주스도 만들 수 있고 케이크도 만들 수 있다."},{"z":"他<em>也</em>會說中文<em>也</em>會說英文。","py":"Tā yě huì shuō Zhōngwén yě huì shuō Yīngwén.","j":"彼は中国語も話せるし、英語も話せる。","e":"He can speak both Chinese and English.","k":"그는 중국어도 할 수 있고 영어도 할 수 있다."}]},
{"id":"g3-143","cat":"副詞","t":"有時候......有時候......","g":{"j":"時には〜、時には〜","e":"sometimes...sometimes...","k":"어떤 때는~, 어떤 때는~"},"p":{"j":"有時候 ＋ V1，有時候 ＋ V2","e":"有時候 + V1, 有時候 + V2","k":"有時候 + V1, 有時候 + V2"},"ex":{"j":"同じ主語について異なる状況・行動を交互に述べ、「時には〜、時には〜」という不規則な繰り返しを表す。同時進行を表す「一邊...一邊...」と混同しないよう注意。","e":"Describes alternating situations for the same subject — \"sometimes X, sometimes Y\" occurring irregularly over time. Don't confuse it with 一邊...一邊..., which means doing two things at the same time.","k":"같은 주어가 서로 다른 상황을 번갈아 나타낼 때 쓰며 \"어떤 때는 ~, 어떤 때는 ~\"라는 불규칙한 반복을 뜻한다. 동시 동작을 뜻하는 \"一邊...一邊...\"과 혼동하지 않도록 주의."},"eg":[{"z":"百貨公司的活動<em>有時候</em>是打折，<em>有時候</em>是送禮物。","py":"Bǎihuò gōngsī de huódòng yǒushíhòu shì dǎzhé, yǒushíhòu shì sòng lǐwù.","j":"デパートのイベントは時には割引で、時にはプレゼントをくれる。","e":"The department store's promotions are sometimes discounts, sometimes free gifts.","k":"백화점 행사는 어떤 때는 할인이고 어떤 때는 선물 증정이다."},{"z":"我<em>有時候</em>騎腳踏車上班，<em>有時候</em>搭捷運。","py":"Wǒ yǒushíhòu qí jiǎotàchē shàngbān, yǒushíhòu dā jiéyùn.","j":"私は時には自転車で通勤し、時には捷運(MRT)に乗る。","e":"Sometimes I ride my bike to work, and sometimes I take the MRT.","k":"나는 어떤 때는 자전거로 출근하고 어떤 때는 MRT를 탄다."}]},
{"id":"g3-144","cat":"介詞","t":"對","g":{"j":"〜に(対して)","e":"to/toward (someone)","k":"~에게(향해)"},"p":{"j":"A ＋ 對 ＋ B ＋ V","e":"A + 對 + B + V","k":"A + 對 + B + V"},"ex":{"j":"動作や感情が向かう対象を示す介詞で、「〜に向かって」「〜に対して」の意味。相手と一緒に行動する意味の「跟」と混同しやすいが、「對」は一方向的な働きかけを表す。","e":"A preposition marking the target of an action or emotion (\"toward/at someone\"). Easily confused with 跟 (a partner doing something together); 對 marks a one-directional action toward the target.","k":"동작이나 감정이 향하는 대상을 나타내는 개사로 \"~을 향해/~에 대해\"라는 뜻이다. 함께 행동하는 상대를 뜻하는 \"跟\"과 혼동하기 쉬우나, \"對\"는 일방향적인 행위를 나타낸다."},"eg":[{"z":"李小姐聽到消息後，開心地<em>對</em>我笑了笑。","py":"Lǐ xiǎojiě tīngdào xiāoxí hòu, kāixīn de duì wǒ xiào le xiào.","j":"李さんはその知らせを聞いた後、嬉しそうに私に向かって微笑んだ。","e":"After Miss Li heard the news, she smiled happily at me.","k":"리 씨는 그 소식을 듣고 나서 기쁘게 나를 향해 웃었다."},{"z":"老師<em>對</em>學生說了一些鼓勵的話。","py":"Lǎoshī duì xuéshēng shuō le yìxiē gǔlì de huà.","j":"先生は学生に向かって励ましの言葉を言った。","e":"The teacher said some encouraging words to the students.","k":"선생님은 학생들에게 격려의 말을 했다."}]},
{"id":"g3-145","cat":"特殊構文","t":"對......有興趣","g":{"j":"〜に興味がある","e":"interested in...","k":"~에 관심이 있다"},"p":{"j":"A ＋ 對 ＋ N ＋ 有興趣","e":"A + 對 + N + 有興趣","k":"A + 對 + N + 有興趣"},"ex":{"j":"「對＋対象＋有興趣」で「〜に興味がある」を表す固定表現。「喜歡」は好き嫌いの感情、「對...有興趣」は関心・興味を表す点で使い分ける。「興趣」を動詞のように使わないよう注意(×他興趣畫畫)。","e":"Fixed pattern \"對 + object + 有興趣\" means \"interested in ___.\" Different from 喜歡 (liking/enjoying); 有興趣 expresses curiosity or interest. Common mistake: using 興趣 as a verb (×他興趣畫畫).","k":"\"對+대상+有興趣\"는 \"~에 관심/흥미가 있다\"는 고정 표현이다. 좋고 싫음을 나타내는 \"喜歡\"과 달리 \"有興趣\"는 호기심·관심을 나타낸다. \"興趣\"를 동사처럼 쓰지 않도록 주의(×他興趣畫畫)."},"eg":[{"z":"他<em>對</em>畫畫很<em>有興趣</em>，以後想當畫家。","py":"Tā duì huàhuà hěn yǒu xìngqù, yǐhòu xiǎng dāng huàjiā.","j":"彼は絵を描くことにとても興味があり、将来画家になりたいと思っている。","e":"He is very interested in drawing and wants to be a painter in the future.","k":"그는 그림 그리는 것에 관심이 많아서 나중에 화가가 되고 싶어 한다."},{"z":"我妹妹<em>對</em>音樂很<em>有興趣</em>，每天都在練鋼琴。","py":"Wǒ mèimei duì yīnyuè hěn yǒu xìngqù, měitiān dōu zài liàn gāngqín.","j":"私の妹は音楽にとても興味があり、毎日ピアノを練習している。","e":"My younger sister is very interested in music and practices the piano every day.","k":"내 여동생은 음악에 관심이 많아서 매일 피아노를 연습한다."}]},
{"id":"g3-146","cat":"介詞","t":"替","g":{"j":"~の代わりに(~のために)","e":"on behalf of / instead of","k":"~대신에"},"p":{"j":"A ＋ 替 ＋ B ＋ 動詞句(AがBの代わりに~する)","e":"A + 替 + B + VP (A does the action for/instead of B)","k":"A ＋ 替 ＋ B ＋ 동사구"},"ex":{"j":"「替」は「〜の代わりに/〜のために」と動作の対象・受益者を導く介詞。「給」(相手に向ける動作)と混同しやすいが、「替」は代理・交代のニュアンスが強い。","e":"'替' is a coverb marking who benefits from or is substituted for in an action, similar to 'for/on behalf of'. Don't confuse it with '給', which marks the recipient of an action rather than substitution.","k":"'替'는 '~을 대신해서/~을 위해'라는 뜻으로 행위의 대상을 나타내는 개사이다. 상대에게 향하는 동작을 나타내는 '給'와 혼동하기 쉽지만 '替'는 대리·교체의 뉘앙스가 강하다."},"eg":[{"z":"你可以<em>替我</em>把禮物包起來嗎？","py":"Nǐ kěyǐ tì wǒ bǎ lǐwù bāo qǐlái ma?","j":"プレゼントを包んでもらえますか。","e":"Could you wrap up the gift for me?","k":"선물을 저 대신 포장해 주실 수 있어요?"},{"z":"媽媽生病了，我<em>替她</em>去買菜。","py":"Māma shēngbìng le, wǒ tì tā qù mǎi cài.","j":"母が病気なので、私が母の代わりに買い物に行きます。","e":"Mom is sick, so I'll go grocery shopping for her.","k":"엄마가 아파서 제가 엄마 대신 장을 보러 가요."}]},
{"id":"g3-147","cat":"接続","t":"為了","g":{"j":"~のために(目的)","e":"in order to / for the purpose of","k":"~을 위해서(목적)"},"p":{"j":"為了＋目的、主語＋動詞句(目的を先に示す)","e":"為了 + goal, Subject + VP (states the purpose before the action)","k":"為了 ＋ 목적, 주어 ＋ 동사구"},"ex":{"j":"「為了」は目的を先に示す介詞で、文頭にも主語の後にも置ける。結果を表す「因為」と違い、まだ実現していない目標を導く点に注意。","e":"'為了' introduces a purpose or goal before the action that achieves it, and can appear either before or after the subject. Unlike '因為' (which gives a reason/cause), '為了' points to an intended, not-yet-realized goal.","k":"'為了'는 목적을 먼저 제시하는 개사로 문장 앞이나 주어 뒤 어디에나 올 수 있다. 원인을 나타내는 '因為'와 달리 아직 실현되지 않은 목표를 가리킨다는 점에 유의해야 한다."},"eg":[{"z":"他<em>為了學中文</em>到臺灣來。","py":"Tā wèile xué Zhōngwén dào Táiwān lái.","j":"彼は中国語を学ぶために台湾に来た。","e":"He came to Taiwan (in order) to learn Chinese.","k":"그는 중국어를 배우기 위해 대만에 왔다."},{"z":"<em>為了考試</em>，我每天晚上都念書。","py":"Wèile kǎoshì, wǒ měi tiān wǎnshang dōu niànshū.","j":"試験のために、私は毎晩勉強しています。","e":"I study every night for the exam.","k":"시험을 위해 저는 매일 밤 공부해요."}]},
{"id":"g3-148","cat":"特殊構文","t":"動詞重疊（ABAB）","g":{"j":"動詞の重複(ちょっと~する/試す) ― 2音節動詞のABAB型","e":"verb reduplication (do a bit of / try doing) — ABAB pattern for two-syllable verbs","k":"동사 중첩(좀 ~해 보다) ― 2음절 동사의 ABAB형"},"p":{"j":"動詞(2音節) ＋ 同じ動詞(2音節)　例: 討論討論","e":"VP (2-syllable) + same VP again → ABAB (e.g. 討論討論)","k":"2음절 동사 ＋ 같은 동사 반복 (예: 討論討論)"},"ex":{"j":"「討論討論」のように二音節動詞を重ねると、「ちょっと~してみる/軽く~する」という試み・軽減のニュアンスが出る。単音節動詞のAA型(看看など)と違い、二音節全体をひとまとまりで繰り返す点に注意。","e":"Reduplicating a two-syllable verb (ABAB, e.g. 討論討論) softens the action, suggesting 'give it a try' or 'do it a bit'. Unlike one-syllable AA reduplication (看看), the whole two-syllable verb repeats as a single unit.","k":"討論討論처럼 2음절 동사를 겹치면 '한번 ~해 보다/가볍게 ~하다'는 뉘앙스가 된다. 1음절 동사의 AA형(看看 등)과 달리 2음절 전체를 그대로 반복한다는 점이 다르다."},"eg":[{"z":"寒假要去哪裡玩，我們可以一起<em>討論討論</em>。","py":"Hánjià yào qù nǎlǐ wán, wǒmen kěyǐ yìqǐ tǎolùn tǎolùn.","j":"冬休みにどこへ遊びに行くか、私たちで一緒にちょっと話し合いましょう。","e":"Where to go during winter break — let's discuss it together.","k":"겨울방학에 어디로 놀러 갈지 우리 같이 좀 의논해 봐요."},{"z":"你有空的時候，可以幫我<em>介紹介紹</em>這個地方。","py":"Nǐ yǒu kòng de shíhòu, kěyǐ bāng wǒ jièshào jièshào zhège dìfāng.","j":"時間があるときに、この場所についてちょっと紹介してもらえますか。","e":"When you have time, could you tell me a bit about this place?","k":"시간 있을 때 이곳을 좀 소개해 주실 수 있어요?"}]},
{"id":"g3-149","cat":"特殊構文","t":"狀態動詞重疊做謂語AA/AABB","g":{"j":"状態動詞の重複でようすを強調する述語(AA的/AABB的)","e":"reduplicated stative verb as predicate (AA的/AABB的) — intensifies description","k":"상태동사 중첩으로 상태를 강조하는 서술어(AA的/AABB的)"},"p":{"j":"主語(＋名詞)＋状態動詞の重複(AA的/AABB的)","e":"Subject (+ noun) + reduplicated stative verb (AA的/AABB的)","k":"주어(＋명사)＋상태동사 중첩형(AA的/AABB的)"},"ex":{"j":"1音節の状態動詞はAA的(大大的)、2音節はAABB的(乾乾淨淨的)の形で重ね、様子を生き生きと強調する述語になる。「試み」を表す動詞重疊(討論討論など)とは意味も品詞も別物なので混同しないこと。","e":"A one-syllable stative verb reduplicates as AA的 (大大的) and a two-syllable one as AABB的 (乾乾淨淨的), forming a vivid descriptive predicate. Don't confuse this with verb reduplication like 討論討論, which signals 'trying a bit', not intensified description.","k":"1음절 상태동사는 AA的(大大的), 2음절은 AABB的(乾乾淨淨的) 형태로 겹쳐 생생한 묘사의 서술어가 된다. '討論討論'처럼 시도를 나타내는 동사 중첩과는 의미와 품사가 다르므로 혼동하지 말아야 한다."},"eg":[{"z":"我的室友眼睛<em>大大的</em>，頭髮<em>長長的</em>。","py":"Wǒ de shìyǒu yǎnjīng dàdà de, tóufǎ chángcháng de.","j":"私のルームメイトは目が大きくて、髪が長い。","e":"My roommate has big eyes and long hair.","k":"제 룸메이트는 눈이 크고 머리카락이 길어요."},{"z":"他把房間打掃得<em>乾乾淨淨的</em>。","py":"Tā bǎ fángjiān dǎsǎo de gāngānjìngjìng de.","j":"彼は部屋をきれいさっぱり掃除した。","e":"He cleaned the room until it was spotless.","k":"그는 방을 깨끗하게 청소했어요."}]},
{"id":"g3-150","cat":"特殊構文","t":"狀態動詞重疊做定語","g":{"j":"状態動詞の重複を連体修飾語(定語)として使う(AA的＋名詞)","e":"reduplicated stative verb as an attributive modifier (AA的 + noun)","k":"상태동사 중첩을 관형어(정어)로 사용(AA的＋명사)"},"p":{"j":"状態動詞の重複(AA的)＋名詞　例: 短短的時間","e":"reduplicated stative verb (AA的) + noun (e.g. 短短的時間)","k":"상태동사 중첩(AA的)＋명사 (예: 短短的時間)"},"ex":{"j":"「短短的時間」のようにAA的の形で名詞を修飾し、様子を強調する連体修飾語になる。述語として使うAA的(狀態動詞重疊做謂語)と形は同じでも、名詞の前に置かれ修飾語として働く点が違う。","e":"AA的 (e.g. 短短的) modifies a following noun as an attributive, emphasizing the quality vividly. It has the same AA的 form used as a predicate (see the related point on stative-verb reduplication as predicate), but here it sits before a noun as a modifier instead.","k":"'短短的'처럼 AA的 형태로 명사를 수식하여 상태를 생생하게 강조하는 관형어가 된다. 서술어로 쓰이는 AA的(관련 문법점 참고)와 형태는 같지만 명사 앞에서 수식어로 쓰인다는 점이 다르다."},"eg":[{"z":"這間店的蛋糕很有名，總在<em>短短的</em>時間內就賣完了。","py":"Zhè jiān diàn de dàngāo hěn yǒumíng, zǒng zài duǎnduǎn de shíjiān nèi jiù mài wán le.","j":"この店のケーキは有名で、いつも短い時間内に売り切れてしまう。","e":"This shop's cakes are famous — they always sell out within a short time.","k":"이 가게의 케이크는 유명해서 늘 짧은 시간 안에 다 팔려요."},{"z":"公園裡有一棵<em>高高的</em>樹，很多小朋友喜歡在下面玩。","py":"Gōngyuán lǐ yǒu yī kē gāogāo de shù, hěnduō xiǎopéngyǒu xǐhuān zài xiàmiàn wán.","j":"公園には高い木が一本あって、たくさんの子どもがその下で遊ぶのが好きです。","e":"There's a tall tree in the park, and lots of kids like playing underneath it.","k":"공원에는 키가 큰 나무가 한 그루 있는데, 많은 아이들이 그 아래에서 노는 것을 좋아해요."}]},
{"id":"g3-151","cat":"副詞","t":"狀態動詞重疊做狀語","g":{"j":"状態動詞の重畳を副詞的に使う","e":"repeating a state verb (AABB) as an adverb","k":"상태동사 중첩을 부사어로 사용"},"p":{"j":"AABB(狀態動詞疊詞)＋地＋動詞","e":"AABB (reduplicated state verb) + 地 + Verb","k":"AABB(상태동사 중첩) + 地 + 동사"},"ex":{"j":"状態動詞(安靜→安安靜靜)をAABB形式に重ね「地」をつけて動作の様子を描写する。二音節語はAABB、一音節語はAA(慢慢)になる点に注意。","e":"Reduplicate a disyllabic state verb into AABB and add 地 to describe how an action is done; monosyllabic ones instead double as AA (e.g. 慢慢). Don't confuse with plain repetition used only for emphasis.","k":"이음절 상태동사를 AABB 형태로 겹치고 地를 붙여 동작의 모습을 표현한다. 단음절어는 AA형(慢慢)이 된다는 점에 주의."},"eg":[{"z":"<em>安安靜靜地</em>坐著。","py":"Ān'ānjìngjìng de zuò zhe.","j":"静かに座っている。","e":"He's sitting quietly.","k":"조용히 앉아 있다."},{"z":"孩子們<em>高高興興地</em>玩遊戲。","py":"Háizimen gāogāoxìngxìng de wán yóuxì.","j":"子どもたちは楽しそうに遊んでいる。","e":"The children are playing happily.","k":"아이들이 즐겁게 놀고 있다."}]},
{"id":"g3-152","cat":"特殊構文","t":"VV看","g":{"j":"「ちょっと~してみる」","e":"try doing V once","k":"한번 ~해 보다"},"p":{"j":"V＋V＋看","e":"V + V + 看","k":"V + V + 看"},"ex":{"j":"動詞を短く重ねて「看」を付け、「試しに~してみる」という軽い提案を表す。過去のことには使えず(×吃吃看了)、否定文にも使わない点に注意。","e":"Reduplicating a verb and adding 看 means \"try V-ing and see (what happens)\" — a light suggestion. It's not used for past events (avoid ×吃吃看了) or in negative sentences.","k":"동사를 겹치고 뒤에 看을 붙여 \"한번 ~해 보다\"라는 가벼운 제안을 나타낸다. 과거형(×吃吃看了)이나 부정문에는 쓰지 않는다."},"eg":[{"z":"這個麵包很好吃，你<em>吃吃看</em>。","py":"Zhège miànbāo hěn hǎochī, nǐ chīchi kàn.","j":"このパンはとてもおいしいから、食べてみて。","e":"This bread is delicious, try eating it.","k":"이 빵은 아주 맛있어요, 한번 먹어 보세요."},{"z":"這件衣服你<em>穿穿看</em>。","py":"Zhè jiàn yīfú nǐ chuānchuan kàn.","j":"この服を着てみて。","e":"Try on this piece of clothing.","k":"이 옷을 한번 입어 보세요."}]},
{"id":"g3-153","cat":"否定","t":"還沒（有）","g":{"j":"「まだ~していない」","e":"not yet","k":"아직 ~하지 않았다"},"p":{"j":"還沒（有）＋動詞(句)","e":"還沒(有) + Verb (Phrase)","k":"還沒(有) + 동사(구)"},"ex":{"j":"動作がまだ実現していないことを表す。「有」は省略可能(還沒吃＝還沒有吃)。「不」との違いは、「不」が意志的な非実現/一般否定であるのに対し、「還沒」は「これから起こる可能性がある未実現」を表す点。","e":"Marks an action that hasn't happened yet; 有 is optional (還沒吃 = 還沒有吃). Unlike 不 (plain negation), 還沒 implies the action is still expected to happen later.","k":"아직 일어나지 않은 동작을 나타낸다. 有는 생략 가능(還沒吃=還沒有吃). 不과 달리 앞으로 일어날 가능성이 있는 미실현을 나타낸다."},"eg":[{"z":"我<em>還沒</em>給你剛剛買火車票的錢。","py":"Wǒ hái méi gěi nǐ gānggāng mǎi huǒchēpiào de qián.","j":"さっき列車の切符を買ったお金を、私はまだあなたに渡していません。","e":"I haven't given you the money for the train ticket I just bought yet.","k":"저는 방금 기차표를 산 돈을 아직 당신에게 주지 않았어요."},{"z":"他<em>還沒</em>吃早餐。","py":"Tā hái méi chī zǎocān.","j":"彼はまだ朝ご飯を食べていない。","e":"He hasn't eaten breakfast yet.","k":"그는 아직 아침을 안 먹었어요."}]},
{"id":"g3-154","cat":"否定","t":"不太/不很","g":{"j":"「あまり~ない」","e":"not very / not too","k":"그다지 ~하지 않다"},"p":{"j":"不太／不很＋形容詞(動詞)","e":"不太/不很 + Adj (Verb)","k":"不太/不很 + 형용사(동사)"},"ex":{"j":"程度がそれほど高くないと婉曲的に言う表現。「不太」は口語でよく使われ、「不很」はやや書き言葉的で使用頻度が低い。「很不」(強い否定)とは意味が異なる点に注意。","e":"A softened way to say something isn't very (adj/verb); 不太 is common in speech while 不很 is more formal and less frequent. Don't confuse it with 很不 (a strong negative).","k":"정도가 그리 높지 않음을 완곡하게 말하는 표현. 不太는 구어에서 많이 쓰이고 不很은 다소 문어체로 빈도가 낮다. 很不(강한 부정)와 혼동하지 않도록 주의한다."},"eg":[{"z":"你住的地方<em>不太</em>好找，我花了一點時間才找到。","py":"Nǐ zhù de dìfāng bú tài hǎo zhǎo, wǒ huāle yìdiǎn shíjiān cái zhǎodào.","j":"あなたの住んでいる場所はあまり見つけやすくないので、少し時間がかかってやっと見つけました。","e":"The place where you live isn't very easy to find, so it took me a while to find it.","k":"당신이 사는 곳은 그다지 찾기 쉽지 않아서, 저는 시간이 좀 걸려서야 찾았어요."},{"z":"這部電影<em>不太</em>好看。","py":"Zhè bù diànyǐng bú tài hǎokàn.","j":"この映画はあまり面白くない。","e":"This movie isn't very good.","k":"이 영화는 그다지 재미있지 않다."}]},
{"id":"g3-155","cat":"助動詞","t":"不用/不必","g":{"j":"「~する必要はない」","e":"don't need to / no need to","k":"~할 필요 없다"},"p":{"j":"不用／不必＋動詞(句)","e":"不用/不必 + Verb (Phrase)","k":"不用/不必 + 동사(구)"},"ex":{"j":"「必要がない」ことを表す。「不用」は口語でよく使い、「不必」はやや書き言葉的でやわらかい印象。「不能」(禁止・不可能)と混同しないよう注意(不用來≠不能來)。","e":"Expresses that something isn't necessary; 不用 is common in speech, 不必 sounds slightly more formal/polite. Don't confuse with 不能 (cannot/not allowed) — 不用來 (\"no need to come\") ≠ 不能來 (\"can't come\").","k":"\"~할 필요가 없다\"를 나타낸다. 不用은 구어에서 많이 쓰고 不必은 다소 문어체로 부드러운 느낌이다. 不能(불가능/금지)과 혼동하지 말 것(不用來≠不能來)."},"eg":[{"z":"他在外面租了房子，這學期<em>不用</em>再住在學校了。","py":"Tā zài wàimiàn zūle fángzi, zhè xuéqí bú yòng zài zhù zài xuéxiào le.","j":"彼は外に部屋を借りたので、今学期はもう学校に住む必要がなくなった。","e":"He rented a place outside, so he doesn't need to live at school this semester anymore.","k":"그는 밖에 방을 구했기 때문에, 이번 학기에는 더 이상 학교에 살 필요가 없어졌다."},{"z":"你<em>不必</em>擔心這件事。","py":"Nǐ bú bì dānxīn zhè jiàn shì.","j":"この事について心配する必要はありません。","e":"You don't need to worry about this.","k":"이 일에 대해 걱정할 필요 없어요."}]},
{"id":"g3-156","cat":"疑問","t":"是不是+VP","g":{"j":"〜かどうか(推測疑問)","e":"Is it that...? (softened guessing question)","k":"~인지 아닌지(추측 의문)"},"p":{"j":"是不是＋VP","e":"Shì bu shì + VP","k":"是不是 + VP"},"ex":{"j":"「是不是」は文をやわらかい推測疑問に変える。動詞句の前に直接挿入できる点が「是嗎」と違い、後者は文全体にしか付けられない。","e":"\"Shì bu shì\" turns a statement into a soft guessing question and can be inserted right before the verb phrase—unlike \"是嗎,\" which only tags the whole sentence.","k":"'是不是'는 문장을 부드러운 추측 의문문으로 바꾸며, 동사구 앞에 바로 삽입할 수 있다. 문장 전체만 확인하는 '是嗎'와는 다르다."},"eg":[{"z":"你臉色不太好，<em>是不是</em>生病了？","py":"Nǐ liǎnsè bú tài hǎo, shì bu shì shēngbìng le?","j":"顔色があまり良くないけど、病気になったんじゃない？","e":"You don't look so well—are you sick?","k":"안색이 별로 안 좋은데, 혹시 아픈 거 아니야?"},{"z":"你<em>是不是</em>忘記帶傘了？","py":"Nǐ shì bu shì wàngjì dài sǎn le?","j":"傘を持ってくるのを忘れたんじゃない？","e":"Did you forget to bring your umbrella?","k":"너 혹시 우산 가져오는 거 잊어버린 거 아니야?"}]},
{"id":"g3-157","cat":"疑問","t":"好不好","g":{"j":"〜しない？(誘い・同意を求める)","e":"How about...? (seeking agreement)","k":"~할까요?(동의를 구함)"},"p":{"j":"VP＋好不好","e":"VP + hǎo bu hǎo","k":"VP + 好不好"},"ex":{"j":"「好不好」は提案や誘いの後につけて相手の同意を求める。「好嗎」より口語的でくだけた印象を与える。","e":"\"Hǎo bu hǎo\" follows a suggestion to seek the listener's agreement, sounding more casual and spoken than the similar \"好嗎.\"","k":"'好不好'는 제안이나 권유 뒤에 붙여 상대의 동의를 구하는 표현으로, '好嗎'보다 더 구어적이고 친근하게 들린다."},"eg":[{"z":"我們選個地點，開店做生意<em>好不好</em>？","py":"Wǒmen xuǎn ge dìdiǎn, kāidiàn zuò shēngyì hǎo bu hǎo?","j":"場所を選んで、お店を開いて商売をするのはどう？","e":"Let's pick a location and open a shop to do business, how about that?","k":"우리 장소를 골라서 가게를 열고 장사하는 게 어때?"},{"z":"我們明天一起去看電影<em>好不好</em>？","py":"Wǒmen míngtiān yìqǐ qù kàn diànyǐng hǎo bu hǎo?","j":"明日一緒に映画を見に行かない？","e":"Shall we go watch a movie together tomorrow?","k":"우리 내일 같이 영화 보러 갈까?"}]},
{"id":"g3-158","cat":"数量","t":"好+幾/多/些+量詞","g":{"j":"かなり多くの〜(数量強調)","e":"quite a lot of... (emphasizing quantity)","k":"꽤 많은 ~(수량 강조)"},"p":{"j":"好＋幾/多/些＋量詞","e":"hǎo + jǐ/duō/xiē + measure word","k":"好 + 幾/多/些 + 양사"},"ex":{"j":"「好」は「幾/多/些」＋量詞の前に置いて、思ったより数量が多いという強調を表す。単なる「幾/多/些」より量の多さを際立たせる。","e":"\"Hǎo\" before \"jǐ/duō/xiē\" + measure word emphasizes that the quantity is larger than expected, unlike the neutral \"jǐ/duō/xiē\" alone.","k":"'好'는 '幾/多/些' + 양사 앞에 놓여 예상보다 수량이 많음을 강조한다. 단순히 '幾/多/些'만 쓸 때보다 양이 많다는 느낌을 준다."},"eg":[{"z":"他很喜歡吃餃子，每次都吃<em>好幾</em>盤。","py":"Tā hěn xǐhuān chī jiǎozi, měicì dōu chī hǎojǐ pán.","j":"彼は餃子が大好きで、毎回何皿も食べる。","e":"He loves eating dumplings—he eats several plates every time.","k":"그는 만두를 아주 좋아해서 매번 여러 접시나 먹는다."},{"z":"我等公車等了<em>好幾個</em>小時。","py":"Wǒ děng gōngchē děngle hǎojǐ ge xiǎoshí.","j":"私はバスを何時間も待った。","e":"I waited for the bus for several hours.","k":"나는 버스를 몇 시간이나 기다렸다."}]},
{"id":"g3-159","cat":"副詞","t":"結構助詞「地」","g":{"j":"〜のように(様態を表す連用修飾)","e":"adverbial marker showing manner","k":"~하게(양태를 나타내는 부사어)"},"p":{"j":"形容詞/擬態語＋地＋動詞","e":"Adj/manner word + de + Verb","k":"형용사/의태어 + 地 + 동사"},"ex":{"j":"「地」は様態を表す語と動詞の間に置く助詞で、発音は軽声「de」。所有・修飾を表す「的」や結果補語を導く「得」と混同しやすいので注意。","e":"\"Dì\" (read as neutral \"de\") links a manner word to the following verb. Learners often confuse it with \"的\" (attributive) or \"得\" (complement), all pronounced \"de.\"","k":"'地'는 양태를 나타내는 말과 동사 사이에 쓰는 조사로 경성 'de'로 읽는다. 발음이 같은 '的'(수식)이나 '得'(보어)와 혼동하기 쉬우니 주의해야 한다."},"eg":[{"z":"他<em>慢慢地</em>走。","py":"Tā mànman de zǒu.","j":"彼はゆっくりと歩く。","e":"He walks slowly.","k":"그는 천천히 걷는다."},{"z":"她<em>開心地</em>笑了。","py":"Tā kāixīn de xiào le.","j":"彼女は嬉しそうに笑った。","e":"She smiled happily.","k":"그녀는 기쁘게 웃었다."}]},
{"id":"g3-160","cat":"特殊構文","t":"不知道......","g":{"j":"〜かどうかわからない","e":"I wonder whether... / not sure if...","k":"~인지 모르겠다"},"p":{"j":"不知道＋(是不是/能不能/會不會等)＋子句","e":"Bù zhīdào + (yes/no question) + clause","k":"不知道 + (是不是/能不能/會不會 등) + 절"},"ex":{"j":"文頭の「不知道」の後に「是不是/能不能/會不會」などの疑問形をそのまま続け、間接疑問文（〜かどうかわからない）を作る。主語「我」は省略されることが多い。","e":"\"Bù zhīdào\" at the start of a sentence introduces an embedded yes/no question (是不是/能不能/會不會...), meaning \"I wonder whether...\"; the subject \"我\" is usually dropped.","k":"문두의 '不知道' 뒤에 '是不是/能不能/會不會' 같은 의문형을 그대로 이어 붙여 '~인지 모르겠다'는 간접 의문문을 만든다. 주어 '我'는 흔히 생략된다."},"eg":[{"z":"<em>不知道</em>明天早上六點能不能起得來。","py":"Bù zhīdào míngtiān zǎoshang liù diǎn néng bu néng qǐ de lái.","j":"明日の朝六時に起きられるかどうかわからない。","e":"I wonder if I'll be able to get up at six tomorrow morning.","k":"내일 아침 6시에 일어날 수 있을지 모르겠다."},{"z":"<em>不知道</em>他今天會不會來上課。","py":"Bù zhīdào tā jīntiān huì bu huì lái shàngkè.","j":"彼が今日授業に来るかどうかわからない。","e":"I wonder whether he'll come to class today.","k":"그가 오늘 수업에 올지 안 올지 모르겠다."}]},
{"id":"g3-161","cat":"接続","t":"那麼","g":{"j":"それでは、そうすると","e":"then, in that case","k":"그러면, 그렇다면"},"p":{"j":"如果／要是...，那麼...","e":"If..., then...","k":"如果/要是...，那麼..."},"ex":{"j":"「那麼」は「もし〜なら」という前提を受けて結論や提案を導く際に使う。話し言葉ではより口語的な「那」に短縮されることが多い。「如果」「要是」など条件文の後半でよく使われる。","e":"\"那麼\" introduces a conclusion or suggestion based on a stated condition, similar to \"then/in that case.\" In casual speech it's often shortened to \"那.\" Common after \"如果/要是\" clauses.","k":"「那麼」는 조건을 받아 결론이나 제안을 이끌 때 쓰며 '그렇다면/그러면'에 해당한다. 회화체에서는 흔히 「那」로 줄여 쓴다. 「如果/要是」 조건문 뒤에 자주 나온다."},"eg":[{"z":"如果你不同意，<em>那麼</em>你建議我們該怎麼做呢？","py":"Rúguǒ nǐ bù tóngyì, nàme nǐ jiànyì wǒmen gāi zěnme zuò ne?","j":"もしあなたが同意しないなら、それでは私たちはどうするべきだと思いますか？","e":"If you don't agree, then what do you suggest we should do?","k":"만약 당신이 동의하지 않는다면, 그러면 우리가 어떻게 해야 한다고 생각하세요?"},{"z":"你不想去看電影，<em>那麼</em>我們去逛街吧。","py":"Nǐ bù xiǎng qù kàn diànyǐng, nàme wǒmen qù guàngjiē ba.","j":"あなたが映画を見に行きたくないなら、それでは買い物に行きましょう。","e":"If you don't want to go watch a movie, then let's go shopping.","k":"당신이 영화를 보러 가고 싶지 않다면, 그러면 우리 쇼핑하러 가요."}]},
{"id":"g3-162","cat":"接続","t":"那","g":{"j":"それなら（口語）","e":"then, in that case (casual)","k":"그럼, 그러면 (구어)"},"p":{"j":"(前の状況)，那＋主語＋(就)...","e":"(situation), then subject + (就)...","k":"(상황)，那＋주어＋(就)..."},"ex":{"j":"「那」は前の発言や状況を受けて、話し言葉で結論や次の行動を導く。「那麼」より口語的でくだけた言い方で、「就」と一緒に使われることが多い。","e":"\"那\" picks up on what was just said or the current situation and introduces a spoken conclusion, more casual than \"那麼.\" Often paired with \"就.\"","k":"「那」는 앞의 상황을 받아 구어체로 결론을 이끄는 표현으로 「那麼」보다 더 회화적이다. 「就」와 함께 자주 쓰인다."},"eg":[{"z":"謝謝，<em>那</em>我就不客氣了。","py":"Xièxie, nà wǒ jiù bú kèqì le.","j":"ありがとう、それなら遠慮なくいただきます。","e":"Thanks, then I won't stand on ceremony.","k":"고마워요, 그럼 사양하지 않을게요."},{"z":"你已經吃飽了，<em>那</em>我就把剩下的都吃了。","py":"Nǐ yǐjīng chībǎo le, nà wǒ jiù bǎ shèngxià de dōu chī le.","j":"あなたはもうお腹いっぱいなんですね、それなら残りは私が全部食べます。","e":"You're already full, then I'll just eat the rest.","k":"당신은 이미 배부르시군요, 그럼 남은 건 제가 다 먹을게요."}]},
{"id":"g3-163","cat":"否定","t":"（請）別","g":{"j":"〜しないで（禁止・忠告）","e":"don't (prohibition / friendly reminder)","k":"~하지 마세요 (금지/당부)"},"p":{"j":"（請）＋別＋VP","e":"(please) + don't + VP","k":"（請）＋別＋VP"},"ex":{"j":"「別」は「不要」の口語的な短縮形で、禁止や忠告を表す。「請別」にするとより丁寧になる。「不要」より柔らかく日常会話でよく使われる。","e":"\"別\" is a colloquial contraction of \"不要,\" used for prohibitions or friendly reminders. Adding \"請\" makes it more polite; it's softer and more common in daily speech than \"不要.\"","k":"「別」는 「不要」의 구어체 축약형으로 금지나 당부를 나타낸다. 「請別」로 쓰면 더 공손해진다. 「不要」보다 부드럽고 일상 회화에서 많이 쓰인다."},"eg":[{"z":"下了飛機以後，<em>別</em>忘了打個電話。","py":"Xiàle fēijī yǐhòu, bié wàngle dǎ ge diànhuà.","j":"飛行機を降りたら、電話をかけるのを忘れないでね。","e":"After you get off the plane, don't forget to make a phone call.","k":"비행기에서 내린 후에, 전화하는 것 잊지 마세요."},{"z":"<em>別</em>擔心，一切都會沒事的。","py":"Bié dānxīn, yíqiè dōu huì méishì de.","j":"心配しないで、すべてうまくいくよ。","e":"Don't worry, everything will be fine.","k":"걱정하지 마세요, 다 잘될 거예요."}]},
{"id":"g3-164","cat":"基本文型","t":"（請）+VP","g":{"j":"〜してください（丁寧な命令文）","e":"please + VP (polite command)","k":"~해 주세요 (공손한 명령문)"},"p":{"j":"（請）＋動詞(句)","e":"(please) + verb (phrase)","k":"（請）＋동사(구)"},"ex":{"j":"動詞（句）だけで命令文になり、「請」を前につけると丁寧になる。目上の人や客には「請」をつけるのが望ましく、裸の動詞文は指示・標語などにも使われる。","e":"A verb phrase alone forms a command; adding \"請\" makes it polite, appropriate for elders or customers. Bare verb commands also appear in instructions and signs.","k":"동사(구)만으로 명령문이 되며, 앞에 「請」을 붙이면 공손해진다. 윗사람이나 손님에게는 「請」을 붙이는 것이 바람직하며, 동사만 쓰는 명령문은 안내문이나 표어에도 쓰인다."},"eg":[{"z":"<em>請</em>小心開車！","py":"Qǐng xiǎoxīn kāichē!","j":"運転はお気をつけて！","e":"Please drive carefully!","k":"운전 조심하세요!"},{"z":"<em>請</em>安靜一點，寶寶正在睡覺。","py":"Qǐng ānjìng yìdiǎn, bǎobao zhèngzài shuìjiào.","j":"少し静かにしてください、赤ちゃんが今寝ています。","e":"Please be a little quieter, the baby is sleeping right now.","k":"좀 조용히 해 주세요, 아기가 지금 자고 있어요."}]},
{"id":"g3-165","cat":"特殊構文","t":"還是......吧","g":{"j":"やっぱり〜しよう（比較検討後の提案）","e":"let's just... instead (suggestion after weighing options)","k":"그냥 ~하자 (비교 후 제안)"},"p":{"j":"...，還是＋VP＋吧","e":"..., let's just + VP + (吧)","k":"...，還是＋VP＋吧"},"ex":{"j":"いくつかの選択肢を比べた末に「やっぱりこうしよう」と穏やかに提案する言い方。「還是」は「やはり」の意味を、「吧」は勧誘の語気を表し、単独の「吧」文より慎重に選んだ感じが出る。","e":"Used to suggest a choice after weighing options, meaning \"let's just... instead.\" \"還是\" conveys \"after all,\" while \"吧\" softens it into a suggestion, implying more deliberation than a plain \"吧\" suggestion.","k":"몇 가지를 비교해 본 후 '역시 이렇게 하자'라고 부드럽게 제안하는 표현이다. 「還是」는 '역시'라는 뜻을, 「吧」는 제안·권유의 어기를 나타내며, 단순한 「吧」 권유문보다 신중하게 고른 느낌을 준다."},"eg":[{"z":"現在排隊的人太多了，我們<em>還是</em>等一下再來<em>吧</em>！","py":"Xiànzài páiduì de rén tài duō le, wǒmen háishì děng yíxià zài lái ba!","j":"今並んでいる人が多すぎるから、私たちはやっぱりちょっと待ってからまた来ましょう！","e":"There are too many people in line right now, let's just wait a bit and come back later!","k":"지금 줄 선 사람이 너무 많으니까, 우리 그냥 좀 기다렸다가 다시 오자!"},{"z":"外面下雨了，我們<em>還是</em>明天再去爬山<em>吧</em>。","py":"Wàimiàn xiàyǔ le, wǒmen háishì míngtiān zài qù páshān ba.","j":"外は雨が降っているから、私たちはやっぱり明日また登山に行きましょう。","e":"It's raining outside, let's just go hiking again tomorrow instead.","k":"밖에 비가 오니까, 우리 그냥 내일 다시 등산 가자."}]},
{"id":"g3-166","cat":"助動詞","t":"應該1","g":{"j":"~すべきだ(義務・助言)","e":"should / ought to (obligation, advice)","k":"~해야 한다 (의무·조언)"},"p":{"j":"S＋應該＋VP","e":"S + 應該 + VP","k":"S + 應該 + VP"},"ex":{"j":"「應該」は話し手が「そうするのが当然だ、そうしたほうがいい」と考える義務・助言を表す。「可以」(許可)や「會」(推測・可能性)と混同しやすいので注意。後ろに動詞句を直接続ける。","e":"\"應該\" expresses what the speaker believes ought to be done — obligation or advice. Don't confuse it with \"可以\" (permission) or \"會\" (future likelihood). It's followed directly by a verb phrase.","k":"\"應該\"는 화자가 당연하다고 여기는 의무나 조언을 나타낸다. 허가를 뜻하는 \"可以\", 가능성을 뜻하는 \"會\"와 혼동하지 않도록 주의하며 뒤에 동사구가 바로 온다."},"eg":[{"z":"運動後<em>應該</em>把汗擦乾。","py":"Yùndòng hòu yīnggāi bǎ hàn cā gān.","j":"運動後は汗を拭き取るべきだ。","e":"You should wipe off your sweat after exercising.","k":"운동 후에는 땀을 닦아야 한다."},{"z":"天氣冷，你<em>應該</em>多穿一件外套。","py":"Tiānqì lěng, nǐ yīnggāi duō chuān yí jiàn wàitào.","j":"寒いから、上着をもう一枚着るべきだ。","e":"It's cold, so you should put on another jacket.","k":"날씨가 추우니까 외투를 한 벌 더 입어야 해요."}]},
{"id":"g3-167","cat":"助動詞","t":"應該2","g":{"j":"~すべきだ(規則・当然の期待)","e":"should (norm-based expectation)","k":"~해야 한다 (규칙에 따른 당연한 기대)"},"p":{"j":"S＋應該＋VP","e":"S + 應該 + VP","k":"S + 應該 + VP"},"ex":{"j":"こちらの「應該」も基本用法は同じで「そうすべきだ」という義務を表すが、個人的な助言よりも規則・常識に基づく「当然そうなるはずだ」という期待を表す場面で使われやすい。","e":"This use of \"應該\" shares the same core meaning (\"should/ought to\") but tends to appear when the obligation comes from a rule or common expectation rather than personal advice — e.g. deadlines, procedures.","k":"이 \"應該\"도 기본 의미는 같아 \"~해야 한다\"는 의무를 나타내지만, 개인적인 조언보다는 규칙이나 상식에 따른 당연한 기대를 말할 때 자주 쓰인다."},"eg":[{"z":"作業<em>應該</em>準時交給老師。","py":"Zuòyè yīnggāi zhǔnshí jiāo gěi lǎoshī.","j":"宿題は時間通りに先生に提出すべきだ。","e":"Homework should be handed in to the teacher on time.","k":"숙제는 제시간에 맞춰 선생님께 제출해야 한다."},{"z":"開會<em>應該</em>提前五分鐘到。","py":"Kāihuì yīnggāi tíqián wǔ fēnzhōng dào.","j":"会議には5分前に着くべきだ。","e":"You should arrive five minutes early for the meeting.","k":"회의에는 5분 일찍 도착해야 한다."}]},
{"id":"g3-168","cat":"助動詞","t":"可以3","g":{"j":"~できる(効果・可能性をもたらす)","e":"can (bring about a result)","k":"~할 수 있다 (효과·가능성)"},"p":{"j":"A＋可以＋讓/使＋B＋Adj/VP","e":"A + 可以 + 讓/使 + B + result","k":"A + 可以 + 讓/使 + B + 결과"},"ex":{"j":"「可以」はここでは許可ではなく、「~によって…という良い結果が起こり得る」という可能性・効果を表す。「讓/使」と組み合わせて結果を導く文型に多い。「可以1(許可)」「可以2(能力)」と区別する。","e":"Here \"可以\" doesn't mean permission — it expresses that something can bring about a beneficial result, often paired with 讓/使 + outcome. Distinguish it from 可以1 (permission) and 可以2 (ability).","k":"여기서 \"可以\"는 허가가 아니라 \"~함으로써 …라는 좋은 결과가 생길 수 있다\"는 가능성/효과를 나타낸다. 주로 讓/使와 함께 결과를 이끄는 문형에 쓰이며, 허가를 뜻하는 可以1, 능력을 뜻하는 可以2와 구별해야 한다."},"eg":[{"z":"游泳<em>可以</em>讓身體更健康。","py":"Yóuyǒng kěyǐ ràng shēntǐ gèng jiànkāng.","j":"水泳は体をもっと健康にすることができる。","e":"Swimming can make your body healthier.","k":"수영은 몸을 더 건강하게 만들 수 있다."},{"z":"多喝水<em>可以</em>讓皮膚變好。","py":"Duō hē shuǐ kěyǐ ràng pífū biàn hǎo.","j":"水をたくさん飲むと肌が良くなる。","e":"Drinking plenty of water can improve your skin.","k":"물을 많이 마시면 피부가 좋아질 수 있다."}]},
{"id":"g3-169","cat":"補語","t":"V起來2","g":{"j":"~し始める","e":"start to (do)","k":"~하기 시작하다"},"p":{"j":"V＋起來(開始)","e":"V + 起來 (begin to V)","k":"V + 起來 (~하기 시작하다)"},"ex":{"j":"「V起來」はここで「~し始める」という動作の開始を表す(起動相)。「站起來」のような上向きの動作(方向補語)とは違うので注意。感情・音を表す動詞(笑う、泣く、歌うなど)によく使われる。","e":"Here \"V起來\" marks the start of an action (\"begin to V\"), unlike the directional \"V起來\" (e.g. 站起來 \"stand up\"). It's common with verbs of emotion or sound, like laughing, crying, or singing.","k":"여기서 \"V起來\"는 \"~하기 시작하다\"라는 동작의 시작을 나타낸다. \"站起來\"처럼 위로 향하는 방향보어와는 다르며, 웃다·울다·노래하다 등 감정·소리 동사와 자주 쓰인다."},"eg":[{"z":"他一聽到消息就開心地<em>笑起來</em>。","py":"Tā yì tīngdào xiāoxí jiù kāixīn de xiào qǐlái.","j":"彼はニュースを聞くとすぐに嬉しそうに笑い出した。","e":"As soon as he heard the news, he burst out laughing happily.","k":"그는 소식을 듣자마자 기쁘게 웃기 시작했다."},{"z":"小寶寶一看到媽媽就<em>哭起來</em>了。","py":"Xiǎo bǎobao yí kàndào māma jiù kū qǐlái le.","j":"赤ちゃんはお母さんを見るとすぐに泣き出した。","e":"The baby started crying as soon as she saw her mother.","k":"아기는 엄마를 보자마자 울기 시작했다."}]},
{"id":"g3-170","cat":"補語","t":"V起來3","g":{"j":"まとめてしまう/片付ける","e":"put away / gather up","k":"정리해서 치우다"},"p":{"j":"V＋起來(收攏/收好)","e":"V + 起來 (put away/gather)","k":"V + 起來 (정리해서 치우다)"},"ex":{"j":"「V起來」はここで「まとめてしまう・片付ける」という結果を表す。「收起來」「摺起來」「包起來」など、物をひとまとまりにする動詞によく使われ、方向補語(立ち上がる)や起動相(笑い出す)とは異なる意味なので区別する。","e":"Here \"V起來\" indicates the result of gathering, closing up, or putting something away — as in 收起來, 摺起來, 包起來. It differs from the directional sense (standing up) and the inchoative sense (starting to laugh), so keep them distinct.","k":"여기서 \"V起來\"는 정리하거나 한데 모아 치운다는 결과를 나타낸다. 收起來, 摺起來, 包起來처럼 물건을 한데 모으는 동사와 자주 쓰이며, 방향(일어서다)이나 동작 시작(웃기 시작하다)을 뜻하는 의미와는 다르므로 구별해야 한다."},"eg":[{"z":"夏天到了，冬天的衣服可以<em>收起來</em>了。","py":"Xiàtiān dào le, dōngtiān de yīfú kěyǐ shōu qǐlái le.","j":"夏になったから、冬服はしまってもいい。","e":"Summer has arrived, so the winter clothes can be put away.","k":"여름이 됐으니까 겨울옷은 넣어 둬도 된다."},{"z":"東西用完了，記得把工具<em>收起來</em>。","py":"Dōngxi yòng wán le, jìde bǎ gōngjù shōu qǐlái.","j":"使い終わったら、道具を片付けるのを忘れないで。","e":"When you're done using it, remember to put the tools away.","k":"다 쓰고 나면 도구를 정리하는 것을 잊지 마세요."}]},
{"id":"g3-171","cat":"アスペクト","t":"V下去2","g":{"j":"〜し続ける","e":"keep on V-ing","k":"계속 ~하다"},"p":{"j":"V ＋ 下去(継続)","e":"V + 下去 (continue V-ing)","k":"V + 下去 (계속 V하다)"},"ex":{"j":"「V下去」は進行中の動作をこのまま継続する意味で、「不能再V下去了」は「もうこれ以上V続けられない」となる。方向を表す「下去(降りていく)」の用法と混同しないよう注意。","e":"\"V下去\" marks continuing an action already in progress; \"不能再V下去了\" means \"can't keep V-ing anymore.\" Don't confuse this aspectual use with the directional \"go down\" sense of 下去.","k":"\"V下去\"는 이미 진행 중인 동작을 계속 이어간다는 뜻으로, \"不能再V下去了\"는 \"더 이상 계속 V할 수 없다\"는 의미다. 방향을 나타내는 \"내려가다\"의 下去와 혼동하지 않도록 주의한다."},"eg":[{"z":"時間到了，我不能再<em>說下去</em>了。","py":"Shíjiān dào le, wǒ bùnéng zài shuō xiàqù le.","j":"時間になったので、もうこれ以上話し続けられません。","e":"Time's up, I can't keep talking anymore.","k":"시간이 다 되어서 더 이상 이야기를 계속할 수 없어요."},{"z":"這場比賽太無聊了，我不想再<em>看下去</em>了。","py":"Zhè chǎng bǐsài tài wúliáo le, wǒ bùxiǎng zài kàn xiàqù le.","j":"この試合はつまらなすぎて、もう見続けたくない。","e":"This game is too boring; I don't want to keep watching it anymore.","k":"이 경기는 너무 지루해서 더 이상 계속 보고 싶지 않아요."}]},
{"id":"g3-172","cat":"副詞","t":"才2","g":{"j":"〜してこそ(必要条件)","e":"only then (necessary condition)","k":"~해야만 (필수 조건)"},"p":{"j":"(要/只有)A，才 ＋ B","e":"(要/只有) A, 才 + B","k":"(要/只有) A, 才 + B"},"ex":{"j":"この「才」は「その条件を満たしてはじめて〜できる」という必要条件を表し、「要…才…」「只有…才…」の形でよく使われる。時間が早い/意外に少ないことを表す「才」の用法とは別物なので混同しないこと。","e":"Here \"才\" marks a necessary condition — \"only if/by doing A can B happen,\" often paired with \"要…才…\" or \"只有…才…\". Don't confuse it with the \"才\" that comments on something being surprisingly early or small in amount.","k":"여기서 \"才\"는 \"그 조건을 충족해야만 비로소 ~할 수 있다\"는 필수 조건을 나타내며 \"要…才…\"나 \"只有…才…\" 형태로 자주 쓰인다. 시간이 이르거나 수량이 적음을 뜻하는 \"才\" 용법과 혼동하지 않도록 주의한다."},"eg":[{"z":"學語言要多練習，<em>才</em>能學得好。","py":"Xué yǔyán yào duō liànxí, cái néng xué de hǎo.","j":"言語を学ぶには練習をたくさんしてこそ、うまく学べる。","e":"Only with a lot of practice can you learn a language well.","k":"언어를 배우려면 연습을 많이 해야만 잘 배울 수 있다."},{"z":"你要先預約，<em>才</em>能進去參觀。","py":"Nǐ yào xiān yùyuē, cái néng jìnqù cānguān.","j":"まず予約しなければ、中に入って見学できません。","e":"You have to make a reservation first before you can go in and visit.","k":"먼저 예약을 해야만 안에 들어가서 견학할 수 있어요."}]},
{"id":"g3-173","cat":"副詞","t":"才3","g":{"j":"〜したばかりで(すぐに)","e":"just did X (then immediately)","k":"막 ~하자마자"},"p":{"j":"A ＋ 才 ＋ V1，就 ＋ V2","e":"A + 才 + V1, 就 + V2","k":"A + 才 + V1, 就 + V2"},"ex":{"j":"この「才」は「〜したばかり」という時間的な近さを示し、後半の「就」と組み合わさって二つの出来事がほぼ同時に起きたことを表す。同じ「才2(必要条件)」とは意味が違うので注意。","e":"Here \"才\" shows something just happened, and paired with \"就\" it presents two events occurring in quick succession. Don't confuse this with \"才2,\" which marks a necessary condition (\"only if...then\").","k":"여기서 \"才\"는 \"막 ~한 지 얼마 안 되어\"라는 시간적 근접성을 나타내며, 뒤의 \"就\"와 함께 두 사건이 거의 동시에 일어났음을 보여준다. 필수 조건을 뜻하는 \"才2\"와 혼동하지 않도록 주의한다."},"eg":[{"z":"他<em>才</em>出門，就開始下雨了。","py":"Tā cái chūmén, jiù kāishǐ xiàyǔ le.","j":"彼は家を出たばかりなのに、すぐ雨が降り出した。","e":"He had just gone out when it started to rain.","k":"그는 막 나가자마자 비가 오기 시작했어요."},{"z":"我<em>才</em>到公司，就接到客戶的電話。","py":"Wǒ cái dào gōngsī, jiù jiēdào kèhù de diànhuà.","j":"私は会社に着いたばかりなのに、すぐお客様から電話がかかってきた。","e":"I had just arrived at the office when I got a call from a client.","k":"저는 회사에 도착하자마자 바로 고객의 전화를 받았어요."}]},
{"id":"g3-174","cat":"副詞","t":"就2","g":{"j":"〜だけでもう(強調)","e":"even just X already... (emphasis)","k":"~만 해도 벌써 (강조)"},"p":{"j":"光/只 ＋ A，就 ＋ B","e":"光/只 + A, 就 + B","k":"光/只 + A, 就 + B"},"ex":{"j":"「光…就…」は「〜だけですでに(予想以上に)…だ」と、程度の高さを強調する言い方。範囲を限定する「光/只」とセットで使われ、単に時間の前後を示す「就(すぐに)」とは働きが違う。","e":"\"光…就…\" emphasizes that even a limited part alone already reaches a surprising degree (\"just X alone already...\"). It pairs with a limiting word like 光/只, unlike the \"就\" that simply marks sequence (\"then, right away\").","k":"\"光…就…\"는 \"그것만으로도 이미(예상보다) …하다\"라는 정도의 높음을 강조하는 표현이다. 범위를 제한하는 \"光/只\"과 짝을 이루며, 단순히 시간의 순서를 나타내는 \"就(바로)\"와는 쓰임이 다르다."},"eg":[{"z":"這條街有很多銀行，光這個路口<em>就</em>有四家。","py":"Zhè tiáo jiē yǒu hěn duō yínháng, guāng zhège lùkǒu jiù yǒu sì jiā.","j":"この通りには銀行がたくさんある。この交差点だけでもう4軒ある。","e":"There are a lot of banks on this street—just this intersection alone has four.","k":"이 거리에는 은행이 아주 많아요. 이 교차로만 해도 벌써 네 곳이나 있어요."},{"z":"這家店的東西很貴，光一杯咖啡<em>就</em>要兩百塊。","py":"Zhè jiā diàn de dōngxi hěn guì, guāng yì bēi kāfēi jiù yào liǎng bǎi kuài.","j":"この店の商品はとても高い。コーヒー一杯だけでもう二百元もする。","e":"The stuff at this shop is expensive—just one cup of coffee alone costs two hundred dollars.","k":"이 가게 물건은 아주 비싸요. 커피 한 잔만 해도 벌써 200위안이나 해요."}]},
{"id":"g3-175","cat":"比較","t":"還1","g":{"j":"〜より更に(比較の強調)","e":"even more than... (comparison)","k":"~보다 더욱 (비교 강조)"},"p":{"j":"A ＋ 比 ＋ B ＋ 還 ＋ 形容詞","e":"A + 比 + B + 還 + adjective","k":"A + 比 + B + 還 + 형용사"},"ex":{"j":"比較文「A比B還+形容詞」の「還」は「もっと/さらに」という程度の強調で、話し手の意外さを含むことが多い。単純な比較の「更」とほぼ同じ意味だが、話し言葉でよく使われる点に注意。","e":"In the comparative pattern \"A比B還+adjective,\" \"還\" adds emphasis meaning \"even more,\" often implying the result is surprising. It functions much like \"更\" but is more common in spoken Taiwanese Mandarin.","k":"비교문 \"A比B還+형용사\"에서 \"還\"는 \"더욱/한층 더\"라는 정도를 강조하며 의외성을 내포하는 경우가 많다. \"更\"와 거의 같은 뜻이지만 구어체에서 더 자주 쓰인다는 점에 유의한다."},"eg":[{"z":"這家餐廳的水比飲料<em>還</em>貴。","py":"Zhè jiā cāntīng de shuǐ bǐ yǐnliào hái guì.","j":"このレストランは水が飲み物よりもっと高い。","e":"At this restaurant, the water is even more expensive than the drinks.","k":"이 식당은 물이 음료수보다 더 비싸요."},{"z":"妹妹的中文比姊姊<em>還</em>好。","py":"Mèimei de Zhōngwén bǐ jiějie hái hǎo.","j":"妹は中国語が姉よりもっと上手だ。","e":"The younger sister's Chinese is even better than the older sister's.","k":"여동생의 중국어가 언니보다 더 잘해요."}]},
{"id":"g3-176","cat":"助動詞","t":"願意","g":{"j":"~するつもりがある(喜んで引き受ける)","e":"willing to (do)","k":"기꺼이 ~하다 / ~할 의향이 있다"},"p":{"j":"主語＋願意＋動詞(＋目的語)","e":"Subject + 願意 + Verb (+ Object)","k":"주어 + 願意 + 동사(+목적어)"},"ex":{"j":"「願意」は依頼や誘いに対して「同意して引き受ける」ことを表し、単なる願望を表す「想/要」とは違う。否定形は「不願意」。","e":"願意 expresses consent or willingness to do something, often in response to a request or offer — different from 想/要 which express simple desire. Negate with 不願意.","k":"願意는 단순한 바람(想/要)이 아니라 부탁이나 제안에 '동의하여 기꺼이 하다'는 뜻이다. 부정형은 不願意이다."},"eg":[{"z":"如果有適合的工作，你<em>願意</em>接受嗎？","py":"Rúguǒ yǒu shìhé de gōngzuò, nǐ yuànyì jiēshòu ma?","j":"もし適した仕事があれば、あなたは引き受けるつもりがありますか?","e":"If there is a suitable job, would you be willing to accept it?","k":"만약 적합한 일자리가 있다면, 당신은 받아들일 의향이 있습니까?"},{"z":"她<em>願意</em>幫我們搬家。","py":"Tā yuànyì bāng wǒmen bānjiā.","j":"彼女は私たちの引っ越しを手伝ってくれるつもりです。","e":"She is willing to help us move.","k":"그녀는 우리 이사를 도와줄 의향이 있어요."}]},
{"id":"g3-177","cat":"接続","t":"只要......就......","g":{"j":"~しさえすれば、~だ","e":"as long as... then...","k":"~하기만 하면 ~하다"},"p":{"j":"只要＋条件句，就＋結果句","e":"只要 + condition, 就 + result","k":"只要 + 조건, 就 + 결과"},"ex":{"j":"「只要~就~」は「~さえすれば十分」という十分条件を表す。「只有~才~」(必要条件・唯一の方法)と混同しやすいので注意。","e":"只要...就... states a sufficient condition — this alone is enough. Learners often confuse it with 只有...才..., which states a necessary/exclusive condition.","k":"只要~就~는 '~하기만 하면 충분하다'는 충분조건을 나타낸다. 필요조건·유일조건을 나타내는 只有~才~와 혼동하기 쉬우니 주의하자."},"eg":[{"z":"他<em>只要</em>有空，<em>就</em>會去參加這次的派對。","py":"Tā zhǐyào yǒu kòng, jiù huì qù cānjiā zhè cì de pàiduì.","j":"彼は暇さえあれば、このパーティーに参加しに行くつもりだ。","e":"As long as he has free time, he will go to attend this party.","k":"그는 시간만 있으면 이번 파티에 참가하러 갈 것이다."},{"z":"<em>只要</em>你努力，<em>就</em>會成功。","py":"Zhǐyào nǐ nǔlì, jiù huì chénggōng.","j":"頑張りさえすれば、成功するだろう。","e":"As long as you work hard, you will succeed.","k":"열심히 하기만 하면 성공할 것이다."}]},
{"id":"g3-178","cat":"接続","t":"只有......才......","g":{"j":"~してこそ初めて~","e":"only if...then... (exclusive condition)","k":"~해야만 비로소 ~하다"},"p":{"j":"只有＋唯一の条件，才＋結果","e":"只有 + the only condition, 才 + result","k":"只有 + 유일 조건, 才 + 결과"},"ex":{"j":"「只有~才~」は「これ以外に方法がない」という必要条件・唯一の条件を表し、十分条件を表す「只要~就~」より条件が厳しい。混同に注意。","e":"只有...才... marks a necessary/exclusive condition (no other way works), stricter than the sufficient-condition 只要...就.... A common mistake is using 只要 when 只有 is meant.","k":"只有~才~는 '이것 외에는 방법이 없다'는 필요조건·유일조건을 나타내며, 충분조건인 只要~就~보다 조건이 엄격하다. 只要와 혼동하지 않도록 주의한다."},"eg":[{"z":"你<em>只有</em>在學中文的環境<em>才</em>學得好。","py":"Nǐ zhǐyǒu zài xué Zhōngwén de huánjìng cái xué de hǎo.","j":"あなたは中国語を学ぶ環境にいてこそ、初めてうまく学べる。","e":"Only in an environment where you study Chinese can you learn it well.","k":"당신은 중국어를 배우는 환경에 있어야만 비로소 잘 배울 수 있다."},{"z":"<em>只有</em>多練習，<em>才</em>能進步。","py":"Zhǐyǒu duō liànxí, cái néng jìnbù.","j":"たくさん練習してこそ、初めて進歩できる。","e":"Only by practicing a lot can you make progress.","k":"많이 연습해야만 비로소 발전할 수 있다."}]},
{"id":"g3-179","cat":"副詞","t":"只好","g":{"j":"~するしかない(仕方なく)","e":"have no choice but to","k":"~할 수밖에 없다"},"p":{"j":"主語＋只好＋動詞句","e":"Subject + 只好 + Verb Phrase","k":"주어 + 只好 + 동사구"},"ex":{"j":"「只好」は状況に迫られて「仕方なく~するしかない」という消極的な選択を表す。「只要/只有」のような条件文とは違い、結果としてのやむを得ない行動を表す。","e":"只好 expresses a reluctant, forced choice given the circumstances — 'have no choice but to.' Unlike 只要...就.../只有...才... (which state conditions), 只好 marks the resulting action, not a condition.","k":"只好는 상황에 떠밀려 '어쩔 수 없이 ~할 수밖에 없다'는 소극적 선택을 나타낸다. 조건을 나타내는 只要/只有와 달리, 只好는 결과로서의 부득이한 행동을 나타낸다."},"eg":[{"z":"外面下起了大雨，我們<em>只好</em>留在飯店裡。","py":"Wàimiàn xiàqǐ le dàyǔ, wǒmen zhǐhǎo liú zài fàndiàn lǐ.","j":"外は大雨が降り出したので、私たちはホテルの中に留まるしかなかった。","e":"It started raining heavily outside, so we had no choice but to stay in the hotel.","k":"밖에 큰비가 내리기 시작해서, 우리는 호텔 안에 머물 수밖에 없었다."},{"z":"手機沒電了，我<em>只好</em>用公共電話。","py":"Shǒujī méi diàn le, wǒ zhǐhǎo yòng gōnggòng diànhuà.","j":"携帯電話の電池が切れたので、公衆電話を使うしかなかった。","e":"My phone died, so I had no choice but to use a public phone.","k":"휴대폰 배터리가 다 돼서, 공중전화를 쓸 수밖에 없었다."}]},
{"id":"g3-180","cat":"接続","t":"不管......都......","g":{"j":"~であろうと、どんな~でも","e":"no matter... always...","k":"~하든지 관계없이"},"p":{"j":"不管＋疑問詞/選択句，都＋結果","e":"不管 + question word/alternative, 都 + result","k":"不管 + 의문사/선택구, 都 + 결과"},"ex":{"j":"「不管」の後には疑問詞(什麼/誰/怎麼)や「A不A」のような選択形が来て、「どんな場合でも結果は変わらない」ことを表す。後半の「都」は省略できない。","e":"不管 is followed by a question word (什麼/誰/怎麼) or an alternative form (A不A) to show the result stays the same regardless of the variable. The following 都 is required and should not be dropped.","k":"不管 뒤에는 의문사(什麼/誰/怎麼)나 'A不A' 같은 선택형이 와서 '어떤 경우라도 결과는 같다'는 뜻을 나타낸다. 뒤에 오는 都는 생략할 수 없다."},"eg":[{"z":"如果你有問題 ，<em>不管</em>什麼時候<em>都</em>可以打電話給我。","py":"Rúguǒ nǐ yǒu wèntí, bùguǎn shénme shíhòu dōu kěyǐ dǎ diànhuà gěi wǒ.","j":"もし問題があれば、いつでも私に電話してもいいですよ。","e":"If you have any problem, no matter what time it is, you can call me.","k":"만약 문제가 있으면, 언제든지 저에게 전화해도 됩니다."},{"z":"<em>不管</em>天氣好不好，我們<em>都</em>會出發。","py":"Bùguǎn tiānqì hǎo bù hǎo, wǒmen dōu huì chūfā.","j":"天気が良くても悪くても、私たちは出発します。","e":"No matter whether the weather is good or not, we will set off.","k":"날씨가 좋든 안 좋든, 우리는 출발할 거예요."}]},
{"id":"g3-181","cat":"比較","t":"一M比一M......","g":{"j":"日ごとにますます〜","e":"more and more, [unit] by [unit]","k":"날이 갈수록 점점 더"},"p":{"j":"一M比一M＋形容詞","e":"yī + M + bǐ + yī + M + adjective","k":"一M比一M + 형용사"},"ex":{"j":"「一天比一天」のように量詞を繰り返して「〜ごとにますます」という変化を表す。「越來越」と似ているが、こちらは単位ごとの比較を強調する点が異なる。よくある間違いは量詞を片方だけにしてしまうこと。","e":"Repeats a measure word (day, year, etc.) to show a gradual, ongoing change, followed by an adjective. Similar to 越來越, but emphasizes comparison unit-by-unit. Common mistake: writing the measure word only once instead of twice.","k":"一天比一天처럼 양사를 반복하여 '~할수록 점점 더'라는 변화를 나타내며 뒤에 형용사가 온다. 越來越와 비슷하지만 단위별 비교를 강조하는 점이 다르다. 양사를 한 번만 쓰는 실수에 주의."},"eg":[{"z":"秋天到了，天氣開始<em>一天比一天</em>冷。","py":"Qiūtiān dào le, tiānqì kāishǐ yì tiān bǐ yì tiān lěng.","j":"秋がやってきて、天気は日ごとに寒くなり始めた。","e":"Autumn has arrived, and the weather is getting colder day by day.","k":"가을이 되어, 날씨가 하루하루 추워지기 시작했다."},{"z":"他的中文<em>一天比一天</em>好。","py":"Tā de Zhōngwén yì tiān bǐ yì tiān hǎo.","j":"彼の中国語は日ごとに上手になっている。","e":"His Chinese is getting better day by day.","k":"그의 중국어는 하루하루 좋아지고 있다."}]},
{"id":"g3-182","cat":"比較","t":"Vs得多","g":{"j":"〜よりずっと…だ","e":"much more ~ (than)","k":"훨씬 더 ~하다"},"p":{"j":"A＋比＋B＋Vs＋得多","e":"A + bǐ + B + stative verb + de duō","k":"A + 比 + B + 형용사 + 得多"},"ex":{"j":"比較文で差が大きいことを強調する表現。「得多」は形容詞の直後に置き、「很多」と入れ替え可能。よくある間違いは「得多」を比較対象の前など別の位置に置いてしまうこと。","e":"Used after a 比 comparison to emphasize a large difference; 得多 attaches right after the stative verb and is interchangeable with 很多 in this position. Common mistake: placing 得多 somewhere else in the sentence instead of right after the adjective.","k":"比 비교문에서 차이가 크다는 것을 강조하는 표현. 得多는 형용사 바로 뒤에 붙이며 很多와 위치를 바꿔 쓸 수 있다. 흔한 실수는 得多를 형용사 뒤가 아닌 다른 위치에 두는 것."},"eg":[{"z":"他哥哥的年紀比他<em>大得多</em>。","py":"Tā gēge de niánjì bǐ tā dà de duō.","j":"彼のお兄さんは彼よりずっと年上だ。","e":"His older brother is much older than him.","k":"그의 형은 그보다 나이가 훨씬 많다."},{"z":"這件衣服比那件<em>貴得多</em>。","py":"Zhè jiàn yīfu bǐ nà jiàn guì de duō.","j":"この服はあの服よりずっと高い。","e":"This piece of clothing is much more expensive than that one.","k":"이 옷은 저 옷보다 훨씬 비싸다."}]},
{"id":"g3-183","cat":"副詞","t":"尤其（是）","g":{"j":"特に〜","e":"especially","k":"특히"},"p":{"j":"A，尤其（是）B","e":"A, especially (is) B","k":"A, 尤其（是）B"},"ex":{"j":"前の内容の中で特に際立つ例を挙げるときに使う。「是」は省略できるが、名詞句の前では付けたほうが自然。「特別」と近いが、「尤其」は既出の全体から一部を強調する点が特徴。","e":"Highlights a standout example within something already mentioned; 是 is optional but sounds more natural before a noun phrase. Similar to 特別, but 尤其 specifically singles out part of a group or situation already stated.","k":"앞서 말한 내용 중에서 특히 두드러진 예를 강조할 때 쓴다. 是는 생략할 수 있지만 명사구 앞에서는 붙이는 것이 더 자연스럽다. 特別와 비슷하지만 尤其는 이미 언급된 것 중 일부를 강조한다는 점이 다르다."},"eg":[{"z":"百貨公司常常有很多人，<em>尤其是</em>週末和假日。","py":"Bǎihuò gōngsī chángcháng yǒu hěn duō rén, yóuqí shì zhōumò hé jiàrì.","j":"デパートはいつも人が多いが、特に週末や祝日はそうだ。","e":"Department stores are often crowded, especially on weekends and holidays.","k":"백화점은 항상 사람이 많은데, 특히 주말과 휴일에 그렇다."},{"z":"我喜歡吃水果，<em>尤其是</em>芒果。","py":"Wǒ xǐhuān chī shuǐguǒ, yóuqí shì mángguǒ.","j":"私は果物が好きだが、特にマンゴーが好きだ。","e":"I like fruit, especially mangoes.","k":"나는 과일을 좋아하는데, 특히 망고를 좋아한다."}]},
{"id":"g3-184","cat":"補語","t":"V 得/不 了","g":{"j":"〜しきれる／しきれない","e":"can/cannot manage to finish V","k":"다 ~할 수 있다/없다"},"p":{"j":"V＋得/不＋了(liǎo)","e":"V + de/bù + liǎo","k":"V + 得/不 + 了(liǎo)"},"ex":{"j":"量や能力の限界から「やりきれるか」を尋ねる可能性補語。ここの「了」は\"liǎo\"と読み、完了を表す\"le\"とは別物。よくある間違いは\"le\"と発音してしまうこと。数量のある対象と一緒に使う点にも注意。","e":"A potential complement asking whether something can be finished or handled, due to quantity or ability limits. Here 了 is pronounced 'liǎo', not the aspect particle 'le' — a common mistake is misreading it as 'le'. It normally pairs with a quantifiable object.","k":"양이나 능력의 한계 때문에 '다 해낼 수 있는지'를 묻는 가능보어. 이때 了는 'liǎo'로 읽으며 완료를 나타내는 'le'와는 다르다. 'le'로 잘못 읽는 실수에 주의하고, 보통 수량이 있는 대상과 함께 쓴다."},"eg":[{"z":"這麼多東西你<em>拿得了</em>嗎？","py":"Zhème duō dōngxi nǐ ná de liǎo ma?","j":"こんなに多くの荷物、あなたは持てますか？","e":"Can you carry this many things?","k":"이렇게 많은 물건을 너 다 들 수 있어?"},{"z":"這件事我一個人<em>做不了</em>。","py":"Zhè jiàn shì wǒ yí ge rén zuò bù liǎo.","j":"この件は私一人ではやりきれない。","e":"I can't handle this matter by myself.","k":"이 일은 나 혼자서는 다 할 수 없다."}]},
{"id":"g3-185","cat":"補語","t":"V得/不......（表可能）","g":{"j":"〜できる／〜できない(可能補語)","e":"can/cannot V (achieve the result)","k":"~할 수 있다/없다"},"p":{"j":"V＋得/不＋結果補語","e":"V + de/bù + result complement","k":"V + 得/不 + 결과보어"},"ex":{"j":"動詞と結果補語の間に「得」（可能）または「不」（不可能）を挟み、その結果まで到達できるかを表す。g3-184の「V得/不了」は数量的に「やりきれるか」に使うのに対し、こちらは「懂・完・見」など特定の結果補語と組み合わせる点が違う。形容詞単独には使えない点にも注意。","e":"Inserts 得 (possible) or 不 (impossible) between a verb and its result complement to show whether that result can be achieved. Unlike g3-184's V得/不了 (about finishing a quantity), this pairs with specific result complements like 懂/完/見. It cannot be used with a bare adjective.","k":"동사와 결과보어 사이에 得(가능) 또는 不(불가능)를 넣어 그 결과에 도달할 수 있는지를 나타낸다. g3-184의 V得/不了는 수량을 '다 해낼 수 있는지'에 쓰이는 반면, 이것은 懂/完/見 같은 특정 결과보어와 결합한다는 점이 다르다. 형용사 하나에만 쓸 수는 없다는 점에 주의."},"eg":[{"z":"他<em>看得懂</em>中文菜單。","py":"Tā kàn de dǒng Zhōngwén càidān.","j":"彼は中国語のメニューを見て理解できる。","e":"He can read and understand Chinese menus.","k":"그는 중국어 메뉴를 보고 이해할 수 있다."},{"z":"我<em>聽不懂</em>台語。","py":"Wǒ tīng bù dǒng Táiyǔ.","j":"私は台湾語を聞いて理解できない。","e":"I can't understand Taiwanese when I hear it.","k":"나는 대만어를 듣고 이해하지 못한다."}]},
{"id":"g3-186","cat":"補語","t":"V 得/不 下","g":{"j":"容器や場所に入るかどうか","e":"whether something fits (into a space)","k":"들어갈 수 있는지 여부"},"p":{"j":"名詞 ＋ V ＋ 得/不 ＋ 下（＋ 目的語）","e":"Noun + Verb + 得/不 + 下 (+ Object)","k":"명사 + 동사 + 得/不 + 下 (+목적어)"},"ex":{"j":"「V得下/不下」は場所や容器がその物を収容できるかどうかを表す可能複文。単なる能力を表す「V得了/不了」ではなく、空間的な容量に注目する点が特徴。","e":"\"V 得/不下\" expresses whether a space or container has enough room for something, focusing on physical capacity rather than general ability (which uses 得了/不了).","k":"\"V 得/不下\"는 장소나 용기가 그것을 담을 수 있는지, 즉 물리적 공간 여유를 나타내는 가능보어이다. 능력을 뜻하는 得了/不了와 구별해야 한다."},"eg":[{"z":"這個房間<em>放得下</em>沙發嗎？","py":"Zhège fángjiān fàng de xià shāfā ma?","j":"この部屋にソファは置けますか?","e":"Can a sofa fit in this room?","k":"이 방에 소파를 놓을 수 있어요?"},{"z":"這台冰箱太小，<em>放不下</em>這麼多菜。","py":"Zhè tái bīngxiāng tài xiǎo, fàng bu xià zhème duō cài.","j":"この冷蔵庫は小さすぎて、こんなにたくさんの料理は入らない。","e":"This fridge is too small; it can't fit all this food.","k":"이 냉장고는 너무 작아서 이렇게 많은 음식을 넣을 수 없어요."}]},
{"id":"g3-187","cat":"特殊構文","t":"疑問代詞","g":{"j":"疑問詞＋都で「〜でも」の意味","e":"question word + 都/也 = \"any-/every-\"","k":"의문사+都/也로 \"~든지\""},"p":{"j":"疑問詞 ＋（都／也）＋ 可以/好/知道 等","e":"Question word + (都/也) + Verb/Adjective","k":"의문사 + (都/也) + 술어"},"ex":{"j":"「誰/什麼/哪裡」などの疑問詞に「都/也」を伴わせると、疑問ではなく「〜でも全部」という任意指示になる。実際の質問文とは別物なので混同しないこと。","e":"A question word (誰/什麼/哪裡…) followed by 都/也 loses its question meaning and instead means \"any-/every-\" — different from an actual question, a common confusion for beginners.","k":"의문사(誰/什麼/哪裡 등) 뒤에 都/也가 오면 질문이 아니라 \"누구든/무엇이든\" 같은 전칭 의미가 된다. 실제 의문문과 혼동하지 않도록 주의."},"eg":[{"z":"這裡有很多位子，你想坐在<em>哪裡都</em>可以。","py":"Zhèlǐ yǒu hěnduō wèizi, nǐ xiǎng zuò zài nǎlǐ dōu kěyǐ.","j":"ここは席がたくさんあるので、どこに座ってもいいですよ。","e":"There are lots of seats here, so you can sit anywhere you like.","k":"여기 자리가 많으니까 아무 데나 앉아도 돼요."},{"z":"他人很隨和，<em>什麼時候</em>找他聊天<em>都</em>可以。","py":"Tā rén hěn suíhé, shénme shíhòu zhǎo tā liáotiān dōu kěyǐ.","j":"彼は気さくだから、いつ話しかけても大丈夫。","e":"He's easygoing, so you can chat with him anytime.","k":"그는 성격이 편해서 언제 말을 걸어도 괜찮아요."}]},
{"id":"g3-188","cat":"副詞","t":"差不多","g":{"j":"だいたい・ほぼ","e":"almost, roughly","k":"거의, 대략"},"p":{"j":"（主語）＋ 差不多 ＋（都）＋ 述語","e":"Subject + 差不多 + (都) + Predicate","k":"주어 + 差不多 + (都) + 술어"},"ex":{"j":"「差不多」は「ほぼ・だいたい」という程度・数量・時間の近似を表す副詞。「都」と組み合わせて「ほとんど全部」を強調することが多い。「大概/應該」との違いは、差不多は実際の値にかなり近いという含みが強い点。","e":"差不多 means \"almost/roughly\" for degree, quantity, or time, often paired with 都 to stress \"nearly all.\" Unlike the guess-word 大概, 差不多 implies the value is genuinely close to the actual one.","k":"差不多는 정도·수량·시간이 \"거의/대략\" 비슷함을 나타내는 부사로, 都와 함께 쓰여 \"거의 다\"를 강조하는 경우가 많다. 추측을 나타내는 大概/應該보다 실제 값에 더 가깝다는 뉘앙스가 있다."},"eg":[{"z":"我們派對可以開始了，客人<em>差不多</em>都到了。","py":"Wǒmen pàiduì kěyǐ kāishǐ le, kèrén chàbùduō dōu dào le.","j":"パーティーを始めていいよ、お客さんはだいたいもう着いたから。","e":"We can start the party now — the guests have pretty much all arrived.","k":"파티 시작해도 돼요, 손님들이 거의 다 도착했어요."},{"z":"現在<em>差不多</em>五點了，我們該回家了。","py":"Xiànzài chàbùduō wǔ diǎn le, wǒmen gāi huíjiā le.","j":"もうだいたい5時だから、そろそろ家に帰らないと。","e":"It's about five o'clock now, we should head home.","k":"지금 거의 다섯 시니까 우리 집에 가야 해요."}]},
{"id":"g3-189","cat":"補語","t":"Vs極了/得不得了/得很","g":{"j":"すごく〜だ（程度が高い）","e":"extremely (adjective)~","k":"매우 ~하다 (정도가 심함)"},"p":{"j":"Vs ＋ 極了／得不得了／得很","e":"Stative Verb + 極了/得不得了/得很","k":"상태동사 + 極了/得不得了/得很"},"ex":{"j":"「極了/得不得了/得很」はどれも形容詞(状態動詞)の後ろについて「非常に〜」という程度の強さを表す。極了は口語で最も自然、得不得了は誇張して驚きを表す、得很はやや書き言葉的で中立的。いずれも状態動詞にしか使えず、一般の動作動詞には使えない点に注意。","e":"極了/得不得了/得很 all attach after a stative verb (adjective) to mean \"extremely,\" but differ in tone: 極了 is the most natural colloquial choice, 得不得了 exaggerates for emphasis/surprise, and 得很 is more neutral/written. None of the three can follow an ordinary action verb — only stative verbs.","k":"極了/得不得了/得很은 모두 상태동사(형용사) 뒤에 붙어 \"매우~\"라는 높은 정도를 나타내지만 뉘앙스가 다르다: 極了은 가장 자연스러운 구어체, 得不得了은 놀라움을 강조하는 과장된 느낌, 得很은 다소 문어체적이고 중립적이다. 셋 다 일반 동작동사에는 쓸 수 없고 상태동사에만 쓴다."},"eg":[{"z":"他終於買到演唱會的門票，心裡<em>高興極了</em>。","py":"Tā zhōngyú mǎidào yǎnchànghuì de ménpiào, xīnlǐ gāoxìng jíle.","j":"彼はついにコンサートのチケットを買えて、心の中で嬉しくてたまらなかった。","e":"He finally got concert tickets, and he was over the moon.","k":"그는 드디어 콘서트 티켓을 사서 마음속으로 너무 기뻤다."},{"z":"這家餐廳的牛肉麵<em>好吃得不得了</em>，我們常常去吃。","py":"Zhè jiā cāntīng de niúròumiàn hǎochī de bùdéliǎo, wǒmen chángcháng qù chī.","j":"このレストランの牛肉麺はめちゃくちゃおいしくて、私たちはよく食べに行く。","e":"This restaurant's beef noodles are incredibly delicious — we go eat there often.","k":"이 식당 우육면은 정말 엄청 맛있어서 우리는 자주 먹으러 가요."}]},
{"id":"g3-190","cat":"補語","t":"Vs死了","g":{"j":"死ぬほど〜だ","e":"unbearably/to death (extreme)","k":"죽을 만큼 ~하다"},"p":{"j":"Vs ＋ 死了","e":"Stative Verb + 死了","k":"상태동사 + 死了"},"ex":{"j":"「Vs死了」は形容詞の後について「死ぬほど〜」という誇張した程度を表す口語表現。「極了」よりさらに大げさで、疲れた・忙しい・暑いなど否定的・激しい感情の愚痴でよく使われる。「死了」は比喩で実際の死とは無関係。","e":"\"Vs死了\" follows a stative verb to mean \"unbearably/to death,\" an even more exaggerated, colloquial version of 極了 — typically used to complain about negative or intense feelings (busy, tired, hot). 死了 here is purely figurative, not literal death.","k":"\"Vs死了\"는 상태동사 뒤에 붙어 \"죽을 만큼 ~하다\"는 과장된 정도를 나타내는 구어체 표현이다. 極了보다 더 과장되어 있으며, 바쁘다/피곤하다/덥다 같은 부정적이고 강한 감정을 투덜대듯 표현할 때 자주 쓴다. 死了는 비유일 뿐 실제 죽음과 무관하다."},"eg":[{"z":"學校裡的功課<em>忙死了</em>，下課還要去打工。","py":"Xuéxiào lǐ de gōngkè máng sǐle, xiàkè hái yào qù dǎgōng.","j":"学校の宿題が忙しくてたまらない、授業が終わってもバイトに行かないといけない。","e":"School work is killing me with how busy it is, and after class I still have to go to my part-time job.","k":"학교 숙제 때문에 너무 바빠 죽겠어요, 수업 끝나고도 아르바이트하러 가야 해요."},{"z":"今天天氣<em>熱死了</em>，我一直流汗。","py":"Jīntiān tiānqì rè sǐle, wǒ yìzhí liú hàn.","j":"今日は暑くてたまらない、ずっと汗をかいている。","e":"It's boiling hot today — I keep sweating like crazy.","k":"오늘 더워 죽겠어요, 계속 땀이 나요."}]},
{"id":"g3-191","cat":"補語","t":"Vs壞了","g":{"j":"程度が甚だしいことを表す(すごく〜だ)","e":"Expresses an extreme degree ('extremely ~')","k":"정도가 매우 심함을 나타냄('너무/몹시 ~하다')"},"p":{"j":"Vs ＋ 壞了","e":"Stative Verb + 壞了","k":"Vs + 壞了"},"ex":{"j":"「壞了」は本来「壊れた」だが、Vsの後につくと程度が極端であることを強調する話し言葉の表現。「餓壞了」「嚇壞了」など決まった組み合わせが多く、直訳しないこと。","e":"'壞了' literally means 'broken,' but after a stative verb it's a colloquial intensifier meaning 'extremely.' Common fixed pairs include 餓壞了, 嚇壞了, 累壞了 — don't translate literally.","k":"'壞了'는 원래 '고장 났다'는 뜻이지만 상태동사 뒤에 붙으면 '너무/몹시 ~하다'는 뜻의 구어체 강조 표현이 된다. 餓壞了, 嚇壞了처럼 정해진 조합이 많으니 직역하지 말 것."},"eg":[{"z":"他忙了一整天都沒吃東西，肚子<em>餓壞了</em>。","py":"Tā máng le yì zhěngtiān dōu méi chī dōngxi, dùzi è huài le.","j":"彼は一日中忙しくて何も食べなかったので、お腹がぺこぺこだ。","e":"He was busy all day and didn't eat anything, so he's starving.","k":"그는 하루 종일 바빠서 아무것도 못 먹어서 배가 너무 고프다."},{"z":"妹妹走丟了，媽媽<em>急壞了</em>。","py":"Mèimei zǒu diū le, māma jí huài le.","j":"妹が迷子になって、お母さんはとても心配した。","e":"My little sister got lost, and mom was worried sick.","k":"여동생이 길을 잃어서 엄마가 너무 걱정했다."}]},
{"id":"g3-192","cat":"補語","t":"Vs了一點","g":{"j":"程度がわずかに超えていることを表す(少し〜)","e":"Expresses a slight excess in degree ('a little too ~')","k":"정도가 약간 초과함을 나타냄('조금 ~하다')"},"p":{"j":"Vs ＋ 了一點","e":"Stative Verb + 了一點","k":"Vs + 了一點"},"ex":{"j":"「Vs了一點」は基準よりわずかに程度が超えていることを表す。「有點Vs」と似ているが、「有點」は動詞の前に置き比較のニュアンスがないのに対し、「了一點」は動詞の後に置いて変化・比較の意味を含む。","e":"'Vs了一點' shows the degree slightly exceeds a standard, often implying a comparison or change. Unlike '有點Vs' (placed before the verb, no comparison implied), '了一點' goes after and suggests 'a bit more than expected/before.'","k":"'Vs了一點'은 기준보다 정도가 약간 초과했음을 나타내며 비교나 변화의 뉘앙스를 포함한다. 동사 앞에 오는 '有點Vs'와 달리 '了一點'은 동사 뒤에 와서 비교의 의미를 담는다."},"eg":[{"z":"雖然排隊的人<em>多了一點</em>，但這間店的牛肉麵非常有名。","py":"Suīrán páiduì de rén duō le yìdiǎn, dàn zhè jiān diàn de niúròumiàn fēicháng yǒumíng.","j":"並んでいる人は少し多いけれど、この店の牛肉麵はとても有名だ。","e":"Although there are a few more people in line, this restaurant's beef noodle soup is very famous.","k":"줄 선 사람이 좀 많지만, 이 가게의 우육면은 아주 유명하다."},{"z":"這件衣服<em>貴了一點</em>，但品質很好。","py":"Zhè jiàn yīfu guì le yìdiǎn, dàn pǐnzhí hěn hǎo.","j":"この服はちょっと高いけど、品質はとてもいい。","e":"This piece of clothing is a bit expensive, but the quality is very good.","k":"이 옷은 좀 비싸지만 품질은 아주 좋다."}]},
{"id":"g3-193","cat":"特殊構文","t":"把O V（一）V","g":{"j":"動作を短時間・軽く行うことを表す(把構文＋動詞の重ね型)","e":"Expresses doing an action briefly/lightly, using the 把-construction with a reduplicated verb","k":"동작을 짧고 가볍게 하는 것을 나타냄(把구문 + 동사 중첩)"},"p":{"j":"把 ＋ O ＋ V(一)V","e":"把 + Object + V(一)V","k":"把 + O + V(一)V"},"ex":{"j":"把構文の後で動詞を「V一V」の形で重ねると、その動作を軽く・少しだけ行うニュアンスになる。単に「把衣服洗」だけだと不自然で、動詞を重ねることで口語らしい柔らかさが出る。","e":"Reduplicating the verb (V一V) after 把+Object softens the action, implying it's done briefly or casually. Just '把衣服洗' alone sounds incomplete/unnatural — the reduplication is what makes it colloquial and natural.","k":"把+목적어 뒤에서 동사를 'V一V' 형태로 중첩하면 동작을 가볍게, 잠깐 하는 뉘앙스가 된다. '把衣服洗'만 쓰면 어색하며, 동사 중첩이 있어야 자연스러운 구어체가 된다."},"eg":[{"z":"今天天氣不錯，記得出門前<em>把衣服洗一洗</em>。","py":"Jīntiān tiānqì bùcuò, jìde chūmén qián bǎ yīfu xǐ yi xǐ.","j":"今日は天気がいいから、出かける前に服をちょっと洗っておいてね。","e":"The weather's nice today, remember to wash your clothes a little before you go out.","k":"오늘 날씨가 좋으니까 나가기 전에 옷을 좀 빨아 놔."},{"z":"你先<em>把頭髮梳一梳</em>，我們要出門了。","py":"Nǐ xiān bǎ tóufǎ shū yi shū, wǒmen yào chūmén le.","j":"まず髪をちょっととかして、私たちはもう出かけるよ。","e":"Comb your hair a bit first, we're about to head out.","k":"먼저 머리를 좀 빗어, 우리 곧 나가야 해."}]},
{"id":"g3-194","cat":"特殊構文","t":"把 O V到......（來/去）","g":{"j":"動作によってものを目的地まで移動させることを表す(把構文＋到＋場所＋來/去)","e":"Expresses moving something to a destination via an action (把-construction + 到 + place + 來/去)","k":"동작을 통해 사물을 목적지까지 이동시킴을 나타냄(把구문 + 到 + 장소 + 來/去)"},"p":{"j":"把 ＋ O ＋ V到 ＋ 地方（來/去）","e":"把 + Object + V到 + Place (+來/去)","k":"把 + O + V到 + 장소(+來/去)"},"ex":{"j":"「把O V到地方」は動作の結果、目的物が特定の場所に到達したことを表す。話し手に近づく場合は「來」、離れる場合は「去」を付けるが、話し手自身が移動先にいない場合は省略できる。","e":"'把O V到地方' shows that as a result of the action, the object ends up at a specific place. Add 來 if movement is toward the speaker, 去 if away; it can be omitted when the speaker isn't at the destination.","k":"'把O V到장소'는 동작의 결과 목적물이 특정 장소에 도달했음을 나타낸다. 화자 쪽으로 이동하면 來, 멀어지면 去를 붙이며, 화자가 목적지에 없으면 생략할 수 있다."},"eg":[{"z":"請你<em>把車開到停車場</em>。","py":"Qǐng nǐ bǎ chē kāi dào tíngchēchǎng.","j":"駐車場まで車を運転していってください。","e":"Please drive the car to the parking lot.","k":"차를 주차장까지 운전해서 가 주세요."},{"z":"他<em>把行李搬到房間去</em>了。","py":"Tā bǎ xínglǐ bān dào fángjiān qù le.","j":"彼は荷物を部屋まで運んでいった。","e":"He moved the luggage into the room.","k":"그는 짐을 방으로 옮겨 갔다."}]},
{"id":"g3-195","cat":"特殊構文","t":"把 O V 了","g":{"j":"動作によって対象がなくなる/処理済みになることを表す(把構文＋動詞＋了)","e":"Expresses that the object is disposed of/completely dealt with as a result of the action (把-construction + Verb + 了)","k":"동작을 통해 대상이 없어지거나 완전히 처리됨을 나타냄(把구문 + 동사 + 了)"},"p":{"j":"把 ＋ O ＋ V ＋ 了","e":"把 + Object + Verb + 了","k":"把 + O + 동사 + 了"},"ex":{"j":"「把O V了」はその物を処分・消失させる、または完全に処理し終えたことを表す。「賣了」「丟了」「吃了」など、対象がなくなる動詞と組み合わせることが多い。「把O V到...」と違い、移動先ではなく「消える・終わる」結果に焦点がある。","e":"'把O V了' expresses that the object is disposed of, gone, or completely finished with — common verbs include 賣了, 丟了, 吃了. Unlike '把O V到...', the focus isn't on where it went but that it's now gone/done.","k":"'把O V了'는 대상을 처분하거나 없애거나 완전히 끝냈음을 나타낸다. 賣了, 丟了, 吃了처럼 대상이 사라지는 동사와 자주 쓰인다. '把O V到...'와 달리 이동한 곳이 아니라 '없어짐/끝남'이라는 결과에 초점이 있다."},"eg":[{"z":"這件衣服穿不下，我打算<em>把它賣了</em>。","py":"Zhè jiàn yīfu chuān bú xià, wǒ dǎsuàn bǎ tā mài le.","j":"この服は着られないから、売ってしまおうと思う。","e":"This piece of clothing doesn't fit anymore, so I plan to sell it.","k":"이 옷은 안 맞아서 팔아 버리려고 해."},{"z":"冰箱裡的牛奶壞了，媽媽<em>把它倒了</em>。","py":"Bīngxiāng lǐ de niúnǎi huài le, māma bǎ tā dào le.","j":"冷蔵庫の中の牛乳が腐ったので、お母さんはそれを捨てた。","e":"The milk in the fridge went bad, so mom poured it out.","k":"냉장고 안의 우유가 상해서 엄마가 그것을 버렸다."}]},
{"id":"g3-196","cat":"特殊構文","t":"把......V+結果補語","g":{"j":"「把」＋目的語＋動詞＋結果補語(動作の結果を強調)","e":"Bǎ + object + verb + result complement (emphasizes the completed result)","k":"把+목적어+동사+결과보어 (동작의 결과를 강조)"},"p":{"j":"把 ＋ O ＋ V ＋ 結果補語(＋了)","e":"Bǎ + O + V + Result Complement (+ le)","k":"把 + O + V + 결과보어(+了)"},"ex":{"j":"「把」構文で目的語への処置の結果を示す。動詞だけで終えず、必ず好・完などの結果補語を伴う。結果補語がないと文が終わらない印象になる。","e":"A bǎ-sentence stating the result of an action on the object. The verb must be followed by a result complement like 好 or 完; leaving it out makes the sentence feel unfinished.","k":"把구문에서 목적어에 대한 처리 결과를 나타낸다. 동사만 쓰지 않고 반드시 好·完 같은 결과보어를 붙여야 하며, 없으면 문장이 끝나지 않은 느낌을 준다."},"eg":[{"z":"他<em>把菜洗好了</em>。","py":"Tā bǎ cài xǐhǎo le.","j":"彼は野菜を洗い終えた。","e":"He has washed the vegetables clean.","k":"그는 채소를 다 씻었다."},{"z":"我<em>把碗洗乾淨了</em>。","py":"Wǒ bǎ wǎn xǐ gānjìng le.","j":"私は茶碗をきれいに洗った。","e":"I washed the bowls clean.","k":"나는 그릇을 깨끗이 씻었다."}]},
{"id":"g3-197","cat":"特殊構文","t":"把 O V-在 PW","g":{"j":"「把」＋目的語を動詞で特定の場所に置く/移す","e":"Bǎ + object + verb + zài + place (the object ends up at that location)","k":"把+목적어+동사+在+장소 (목적어가 그 장소에 놓이게 됨)"},"p":{"j":"把 ＋ O ＋ V ＋ 在 ＋ 地方","e":"Bǎ + O + V + zài + Place","k":"把 + O + V + 在 + 장소"},"ex":{"j":"動作の結果、物がどこに置かれたかを示す。「在」の後は必ず場所を表す語。「在＋場所」を「把」の前に移すような語順は間違い。","e":"Shows where an object ends up after the action. 在 must be followed by a place word; don't move the 在+place phrase in front of 把.","k":"동작 후 물건이 어디에 놓이는지를 나타낸다. 在 뒤에는 반드시 장소가 와야 하며, 在+장소를 把 앞으로 옮기지 않도록 주의한다."},"eg":[{"z":"我<em>把書放在桌子上</em>。","py":"Wǒ bǎ shū fàng zài zhuōzi shàng.","j":"私は本を机の上に置いた。","e":"I put the book on the table.","k":"나는 책을 책상 위에 놓았다."},{"z":"我<em>把鑰匙放在抽屜裡</em>。","py":"Wǒ bǎ yàoshi fàng zài chōuti lǐ.","j":"私は鍵を引き出しの中に入れた。","e":"I put the key in the drawer.","k":"나는 열쇠를 서랍 안에 넣었다."}]},
{"id":"g3-198","cat":"特殊構文","t":"把+N1+V給+N2","g":{"j":"「把」＋物＋動詞＋「給」＋人 (物を人に渡す・送る)","e":"Bǎ + N1 (thing) + V + gěi + N2 (person) — hand/send the thing to someone","k":"把+N1(사물)+동사+給+N2(사람) (사물을 사람에게 건네줌)"},"p":{"j":"把 ＋ N1 ＋ V ＋ 給 ＋ N2","e":"Bǎ + N1 + V + gěi + N2","k":"把 + N1 + V + 給 + N2"},"ex":{"j":"物を誰かに渡す・送る動作を「把」で強調する言い方。動詞は寄・送・還などの受け渡し系に限られ、「給」の後は必ず受け取る人が来る。","e":"Emphasizes handing or sending a thing to someone using bǎ. The verb is limited to transfer verbs like 寄, 送, 還, and 給 is always followed by the recipient.","k":"물건을 누군가에게 건네주거나 보내는 동작을 把로 강조하는 표현. 동사는 寄·送·還처럼 전달을 뜻하는 것에 한정되며, 給 뒤에는 반드시 받는 사람이 온다."},"eg":[{"z":"回家後再麻煩你<em>把郵件寄給我</em>。","py":"Huí jiā hòu zài máfan nǐ bǎ yóujiàn jì gěi wǒ.","j":"家に帰ったら、メールを私に送っていただけますか。","e":"After you get home, please send the mail to me.","k":"집에 돌아간 후에 메일을 저에게 보내 주세요."},{"z":"我<em>把生日禮物送給姊姊</em>。","py":"Wǒ bǎ shēngrì lǐwù sòng gěi jiějie.","j":"私は誕生日プレゼントを姉に送った。","e":"I gave the birthday present to my older sister.","k":"나는 생일 선물을 언니(누나)에게 주었다."}]},
{"id":"g3-199","cat":"特殊構文","t":"被+（N）+V得","g":{"j":"「被」＋(動作主)＋動詞＋「得」＋結果/程度 (受け身で結果や程度を表す)","e":"Bèi + (agent) + V + de + result/degree — a passive expressing the resulting state or degree","k":"被+(행위자)+동사+得+결과/정도 (피동문에서 결과나 정도를 나타냄)"},"p":{"j":"被 ＋ (N) ＋ V ＋ 得 ＋ 結果/程度補語","e":"Bèi + (N) + V + de + Result/Degree Complement","k":"被 + (N) + V + 得 + 결과/정도보어"},"ex":{"j":"受け身文に程度補語をつけて、その動作がどれほどの結果をもたらしたかを表す。動作主(N)は省略可能。「得」の後には形容詞や可能・不可能形が来る。","e":"Adds a degree complement to a passive sentence to show how strongly the action affected the subject. The agent (N) is optional; after 得 comes an adjective or a potential-form result.","k":"피동문에 정도보어를 붙여 그 동작이 초래한 결과의 정도를 나타낸다. 행위자(N)는 생략 가능하며, 得 뒤에는 형용사나 가능/불가능 표현이 온다."},"eg":[{"z":"鄰居的聲音太大了，妹妹<em>被吵得睡不著</em>。","py":"Línjū de shēngyīn tài dà le, mèimei bèi chǎo de shuì bu zháo.","j":"隣人の音が大きすぎて、妹はうるさくて眠れなかった。","e":"The neighbor's noise was too loud, and my younger sister couldn't sleep because of it.","k":"이웃집 소리가 너무 커서 여동생은 시끄러워서 잠을 잘 수 없었다."},{"z":"考試考不好，他<em>被爸爸罵得很難過</em>。","py":"Kǎoshì kǎo bù hǎo, tā bèi bàba mà de hěn nánguò.","j":"試験の出来が悪くて、彼は父にひどく叱られてつらかった。","e":"He did poorly on the exam, and his father scolded him so much that he felt very upset.","k":"시험을 잘 못 봐서 그는 아버지한테 심하게 혼나서 많이 속상했다."}]},
{"id":"g3-200","cat":"副詞","t":"其實","g":{"j":"「実は」「実際は」(思い込みや表面と違う事実を伝える)","e":"actually / in fact (introduces a truth that differs from what was assumed)","k":"사실은/실제로는 (예상이나 겉모습과 다른 실제 사실을 말할 때)"},"p":{"j":"(前文)，其實 ＋ 事実","e":"(previous statement), qíshí + the actual fact","k":"(앞 문장), 其實 + 실제 사실"},"ex":{"j":"前の内容や思い込みを訂正し、本当はどうなのかを述べる副詞。文頭でも主語の後でもよい。「事實上」と似るが、より口語的。","e":"An adverb that corrects a prior assumption or statement by revealing the real situation. It can appear at the start of a sentence or after the subject; more colloquial than 事實上.","k":"앞의 내용이나 통념을 정정하며 실제 상황을 말할 때 쓰는 부사. 문두나 주어 뒤 어디에나 올 수 있으며, 事實上보다 구어적이다."},"eg":[{"z":"一個禮拜運動兩次，<em>其實</em>不難。","py":"Yí ge lǐbài yùndòng liǎng cì, qíshí bù nán.","j":"一週間に二回運動するのは、実はそんなに難しくない。","e":"Exercising twice a week is actually not that hard.","k":"일주일에 두 번 운동하는 것은 사실 그렇게 어렵지 않다."},{"z":"這道題目看起來很難，<em>其實</em>很簡單。","py":"Zhè dào tímù kànqǐlái hěn nán, qíshí hěn jiǎndān.","j":"この問題は難しそうに見えるが、実は簡単だ。","e":"This question looks hard, but it's actually simple.","k":"이 문제는 어려워 보이지만 사실은 간단하다."}]},
{"id":"g3-201","cat":"特殊構文","t":"什麼都......就是......","g":{"j":"何でも〜だが、ただ〜だけは例外","e":"everything is fine except for one thing","k":"다 그런데 단 하나만은 예외"},"p":{"j":"主語＋什麼都＋VP1，就是＋VP2(例外・否定)","e":"Subject + 什麼都 + VP1, 就是 + VP2 (the one exception, often negative)","k":"주어＋什麼都＋VP1，就是＋VP2(예외・부정)"},"ex":{"j":"「什麼都」で「全般的に何でもOK」と述べ、「就是」で唯一の例外を示す。「就是」はここでは「〜だ」の意味ではなく「ただ〜だけ」という限定の副詞であることに注意。","e":"什麼都 states a broad 'anything goes,' then 就是 marks the single exception. Beginners often mistake this 就是 for the copula 'to be' rather than the adverb meaning 'just/only.'","k":"什麼都로 '무엇이든 다 괜찮다'고 말한 뒤, 就是로 유일한 예외를 짚어준다. 이때 就是는 '~이다'가 아니라 '오직/그저'라는 한정 부사임에 유의해야 한다."},"eg":[{"z":"他<em>什麼都</em>吃，<em>就是</em>不敢吃臭豆腐。","py":"Tā shénme dōu chī, jiùshì bù gǎn chī chòudòufu.","j":"彼は何でも食べるが、臭豆腐だけは怖くて食べられない。","e":"He eats anything, except he's just too scared to eat stinky tofu.","k":"그는 뭐든지 다 먹지만, 취두부만은 무서워서 못 먹는다."},{"z":"我<em>什麼</em>水果<em>都</em>吃，<em>就是</em>不喜歡榴槤。","py":"Wǒ shénme shuǐguǒ dōu chī, jiùshì bù xǐhuān liúlián.","j":"私は果物なら何でも食べるが、ドリアンだけは好きじゃない。","e":"I'll eat any kind of fruit, except I just don't like durian.","k":"나는 무슨 과일이든 다 먹지만, 두리안만은 안 좋아한다."}]},
{"id":"g3-202","cat":"補語","t":"V好","g":{"j":"動作が完了して準備が整う","e":"action completed and ready/well done","k":"동작이 끝나서 준비가 됨"},"p":{"j":"V＋好（＋了）","e":"V + 好 (+ le)","k":"V＋好(+了)"},"ex":{"j":"「好」は動作が完了し、結果として「準備万端・きちんと済んだ」状態になったことを表す。同じ結果補語の「完」は単に動作が終わったことだけを示すので、「準備好」を「準備完」と言い換えるのは不自然な点に注意。","e":"好 as a resultative complement marks that an action is finished AND its result is now ready/satisfactory. Unlike 完, which only marks the action ending, 好 adds a sense of 'all set.' A common error is swapping 好 and 完 freely, e.g. saying 準備完 instead of 準備好.","k":"결과보어 好는 동작이 끝났을 뿐 아니라 그 결과로 '준비가 다 됐다/잘 마쳤다'는 뜻까지 담는다. 단순히 동작이 끝났음만 나타내는 完과 달리, 準備好를 準備完으로 바꿔 쓰면 어색하다는 점에 유의해야 한다."},"eg":[{"z":"颱風快來了，媽媽把食物跟水都先<em>買好</em>了。","py":"Táifēng kuài lái le, māma bǎ shíwù gēn shuǐ dōu xiān mǎihǎo le.","j":"台風が来そうなので、お母さんは先に食べ物と水を買っておいた。","e":"A typhoon is coming soon, so Mom already bought all the food and water in advance.","k":"태풍이 곧 오려고 해서, 엄마는 미리 음식과 물을 다 사 놓았다."},{"z":"晚餐<em>煮好</em>了，我們可以吃飯了。","py":"Wǎncān zhǔhǎo le, wǒmen kěyǐ chīfàn le.","j":"晩ご飯ができたので、もう食べられるよ。","e":"Dinner is ready, we can eat now.","k":"저녁이 다 됐으니까 이제 밥 먹어도 돼요."}]},
{"id":"g3-203","cat":"補語","t":"V完","g":{"j":"動作が終わる・し終える","e":"action is finished/used up","k":"동작이 끝남・다 함"},"p":{"j":"V＋完（＋賓語／了）","e":"V + 完 (+ object / le)","k":"V＋完(+목적어/了)"},"ex":{"j":"「完」は動作が最後まで進んで終わったことだけを表す結果補語。「好」のように「うまくいった・準備万端」というニュアンスは含まない。「V完＋目的語」の語順(例:買完菜)によく注意し、目的語を動詞の前に置かないこと。","e":"完 simply marks that an action ran its full course and is over, without 好's nuance of 'ready/well done.' Pay attention to word order V完+object (e.g. 買完菜), not placing the object before the verb.","k":"完은 동작이 끝까지 진행되어 마무리됐다는 것만 나타내는 결과보어로, 好처럼 '잘 됐다/준비됐다'는 뉘앙스는 없다. V完+목적어(예: 買完菜) 어순에 유의하고 목적어를 동사 앞에 두지 않아야 한다."},"eg":[{"z":"他剛去市場<em>買完</em>菜。","py":"Tā gāng qù shìchǎng mǎiwán cài.","j":"彼はさっき市場で買い物を買い終えたところだ。","e":"He just finished buying groceries at the market.","k":"그는 방금 시장에서 장보기를 다 끝냈다."},{"z":"我已經<em>寫完</em>功課了。","py":"Wǒ yǐjīng xiěwán gōngkè le.","j":"もう宿題をやり終えた。","e":"I've already finished my homework.","k":"나는 이미 숙제를 다 끝냈다."}]},
{"id":"g3-204","cat":"基本文型","t":"VP+VP(連動)","g":{"j":"二つの動作を順番どおりに続けて言う","e":"two actions in a row, no conjunction needed","k":"두 동작을 순서대로 이어 말함"},"p":{"j":"VP1＋VP2(動作の起こる順に並べる)","e":"VP1 + VP2 (in the order the actions occur)","k":"VP1＋VP2(동작이 일어나는 순서대로)"},"ex":{"j":"連動句は同じ主語の二つの動作を、接続詞なしで起こる順番のまま並べる文型。後ろのVPは前のVPの目的や結果を表すことが多い。「然後」や「和」を間に挟むのは誤り。","e":"A serial verb construction places two verb phrases sharing one subject back-to-back, in the order the actions happen, with no conjunction between them; the second VP often shows the purpose of the first. Inserting 然後 or 和 between them is a common mistake.","k":"연동문은 같은 주어의 두 동작을 접속사 없이 일어나는 순서대로 나란히 놓는 문형이다. 뒤의 VP는 앞 VP의 목적을 나타내는 경우가 많으며, 然後나 和를 사이에 넣는 것은 잘못된 표현이다."},"eg":[{"z":"我要<em>回家吃飯</em>了。","py":"Wǒ yào huíjiā chīfàn le.","j":"私は家に帰ってご飯を食べます。","e":"I'm going home to eat dinner now.","k":"나는 집에 가서 밥을 먹을 거예요."},{"z":"他<em>去圖書館看書</em>。","py":"Tā qù túshūguǎn kànshū.","j":"彼は図書館へ本を読みに行く。","e":"He goes to the library to read books.","k":"그는 도서관에 가서 책을 읽는다."}]},
{"id":"g3-205","cat":"接続","t":"才......就......","g":{"j":"〜したばかりなのに、もう〜した","e":"had only just done A when B already happened","k":"방금 A했는데 벌써 B함"},"p":{"j":"才＋VP1，(主語)就＋VP2","e":"才 + VP1, (Subject) + 就 + VP2","k":"才＋VP1，(주어)就＋VP2"},"ex":{"j":"「才」でごく短い時間しか経っていないことを示し、「就」で次の出来事がすぐ続いて起きたことを述べ、意外さや驚きのニュアンスを伴う。「一……就……」は単に即座の連続を述べるだけで「短さへの意外感」は含まない点が異なる。","e":"才 stresses that very little time had passed, and 就 shows the next event followed right away, usually with a sense of surprise at how soon it happened. This differs from 一...就..., which states immediate succession without implying the interval felt surprisingly short.","k":"才로 아주 짧은 시간만 지났음을 강조하고, 就로 다음 일이 곧바로 이어졌음을 말하며 보통 의외라는 느낌을 담는다. 一...就...는 단순히 즉각적인 연속을 나타낼 뿐 '짧아서 의외다'라는 뉘앙스는 없다는 점이 다르다."},"eg":[{"z":"我跟他<em>才</em>談沒多久，他<em>就</em>有事先離開了。","py":"Wǒ gēn tā cái tán méiduōjiǔ, tā jiù yǒushì xiān líkāi le.","j":"私が彼と話し始めてまだ間もないのに、彼はもう用事があって先に帰ってしまった。","e":"I had only been talking with him for a little while when he already left early because he had something to do.","k":"나는 그와 이야기를 나눈 지 얼마 안 됐는데, 그는 벌써 일이 있어서 먼저 가버렸다."},{"z":"妹妹<em>才</em>睡著沒多久<em>就</em>醒了。","py":"Mèimei cái shuìzháo méi duōjiǔ jiù xǐng le.","j":"妹はまだ寝てそんなに経っていないのに、もう目が覚めてしまった。","e":"My little sister had only been asleep for a little while when she already woke up.","k":"여동생은 잠든 지 얼마 안 됐는데 벌써 깼다."}]},
{"id":"g3-206","cat":"否定","t":"時段+否定","g":{"j":"「(期間)ずっと〜していない」","e":"hasn't (done) for (a period of time)","k":"(기간) 동안 계속 ~하지 않았다"},"p":{"j":"時段 ＋ 沒 ＋ Ｖ (＋了)","e":"Duration + méi + V (+ le)","k":"시량사 + 沒 + 동사 (+了)"},"ex":{"j":"「時間の長さ＋沒＋動詞（＋了）」で、その期間ずっと動作が行われていないことを表す。「了」は状態が今も続いていることを示す。普通の否定文と違い、時量詞が動詞より前に置かれる点に注意。","e":"\"Duration + méi + verb (+ le)\" expresses that an action has not occurred for a stretch of time, continuing up to now. Unlike a normal negative sentence, the time duration comes before the verb, not after.","k":"\"시간 길이+沒+동사(+了)\" 형식으로, 그 기간 동안 계속 동작이 일어나지 않았음을 나타낸다. \"了\"는 그 상태가 지금까지 이어지고 있음을 보여준다. 일반 부정문과 달리 시량사가 동사 앞에 온다."},"eg":[{"z":"他<em>兩天沒睡覺了</em>，讓他多睡一點。","py":"Tā liǎng tiān méi shuìjiào le, ràng tā duō shuì yìdiǎn.","j":"彼は二日間眠っていないので、もっと寝かせてあげて。","e":"He hasn't slept for two days, so let him sleep a bit more.","k":"그는 이틀 동안 잠을 못 잤으니, 좀 더 자게 해 줘."},{"z":"我<em>三天沒洗澡了</em>，好想洗個熱水澡。","py":"Wǒ sān tiān méi xǐzǎo le, hǎo xiǎng xǐ ge rèshuǐzǎo.","j":"私は三日間お風呂に入っていない、熱いシャワーを浴びたい。","e":"I haven't showered for three days, I really want to take a hot shower.","k":"나는 사흘 동안 샤워를 안 했어, 뜨거운 물로 샤워하고 싶어."}]},
{"id":"g3-207","cat":"介詞","t":"從......起","g":{"j":"「〜から(起点)」","e":"starting from / from ... on","k":"~부터"},"p":{"j":"從 ＋ 時間點 ＋ 起","e":"Cóng + time point + qǐ","k":"從 + 시점 + 起"},"ex":{"j":"「從＋時間點＋起」で「〜から」という起点を表す。「從＋時間＋開始」とほぼ同じ意味だが、「起」は書き言葉的でやや硬い響きがある。","e":"\"Cóng + time point + qǐ\" marks a starting point, similar to \"cóng...kāishǐ\" but qǐ sounds slightly more formal or written.","k":"\"從+시점+起\"는 '~부터'라는 시작점을 나타낸다. \"從...開始\"와 의미가 비슷하지만 \"起\"는 약간 더 격식적이고 문어체적인 느낌을 준다."},"eg":[{"z":"<em>從現在起</em>，你應該多吃菜少吃肉。","py":"Cóng xiànzài qǐ, nǐ yīnggāi duō chī cài shǎo chī ròu.","j":"今からは、野菜を多く食べて肉を少なく食べるべきだ。","e":"From now on, you should eat more vegetables and less meat.","k":"지금부터, 너는 채소를 많이 먹고 고기를 적게 먹어야 해."},{"z":"<em>從下個月起</em>，我要開始運動。","py":"Cóng xià ge yuè qǐ, wǒ yào kāishǐ yùndòng.","j":"来月から、私は運動を始めるつもりだ。","e":"Starting next month, I'm going to start exercising.","k":"다음 달부터, 나는 운동을 시작할 거야."}]},
{"id":"g3-208","cat":"補語","t":"V  得/不 起","g":{"j":"「(金銭的に)〜できる/できない」","e":"can/cannot afford to V","k":"(경제적으로) ~할 수 있다/없다"},"p":{"j":"Ｖ ＋ 得/不 ＋ 起","e":"V + de/bu + qǐ","k":"동사 + 得/不 + 起"},"ex":{"j":"「動詞＋得/不＋起」は経済力があって(なくて)「〜できる/できない」という意味を表し、主に金銭的な「買える/買えない」に使う。単純な能力を表す「會/可以」とは異なり、経済的余裕に焦点がある。","e":"\"Verb + de/bu + qǐ\" is a potential complement meaning one can or cannot afford something, usually about money. Unlike néng/huì, which express general ability, qǐ specifically implies financial capacity.","k":"\"동사+得/不+起\"는 경제적 여유가 있어서(없어서) '~할 수 있다/없다'는 뜻을 나타내며 주로 금전적으로 '살 수 있다/없다'에 쓰인다. 일반적인 능력을 나타내는 \"會/可以\"와 달리 경제적 여유에 초점이 있다."},"eg":[{"z":"這支手錶現在在打折，一般學生也<em>買得起</em>。","py":"Zhè zhī shǒubiǎo xiànzài zài dǎzhé, yìbān xuéshēng yě mǎi de qǐ.","j":"この腕時計は今セール中なので、普通の学生でも買える。","e":"This watch is on sale now, so even an average student can afford it.","k":"이 손목시계는 지금 할인 중이라 일반 학생도 살 수 있어."},{"z":"這家餐廳太貴了，我<em>吃不起</em>。","py":"Zhè jiā cāntīng tài guì le, wǒ chī bu qǐ.","j":"このレストランは高すぎて、私には手が出ない。","e":"This restaurant is too expensive, I can't afford to eat here.","k":"이 식당은 너무 비싸서 나는 갈 여유가 없어."}]},
{"id":"g3-209","cat":"補語","t":"V （得/不）出來","g":{"j":"「見て(聞いて)〜だと分かる/分からない」","e":"can/cannot tell (by observation)","k":"봐서(들어서) ~라고 알 수 있다/없다"},"p":{"j":"Ｖ ＋（得/不）＋ 出來","e":"V + (de/bu) + chūlái","k":"동사 + (得/不) + 出來"},"ex":{"j":"「動詞＋得/不＋出來」は、見たり聞いたりして判断・識別できる(できない)ことを表す。この「出來」は具体的な移動ではなく、判断や結果が「外に現れる」ことを示す抽象的な用法。","e":"\"Verb + de/bu + chūlái\" expresses being able (or unable) to tell, recognize, or perceive something through observation. Here chūlái is abstract, meaning a judgment or result \"emerges,\" not literal movement outward.","k":"\"동사+得/不+出來\"는 보거나 들어서 판단·식별할 수 있다(없다)는 뜻을 나타낸다. 여기서 \"出來\"는 실제 이동이 아니라 판단이나 결과가 '겉으로 드러남'을 의미하는 추상적 용법이다."},"eg":[{"z":"從他說話的樣子來看，<em>感覺不出來</em>他很緊張。","py":"Cóng tā shuōhuà de yàngzi láikàn, gǎnjué bu chūlái tā hěn jǐnzhāng.","j":"彼の話し方から見ると、緊張しているようには感じられない。","e":"Judging from the way he talks, you can't tell that he's nervous.","k":"그가 말하는 모습을 보면, 그가 긴장했다는 걸 느낄 수 없어."},{"z":"她變了很多，我差點<em>認不出來</em>她是誰。","py":"Tā biàn le hěn duō, wǒ chādiǎn rèn bu chūlái tā shì shéi.","j":"彼女はとても変わっていて、私はもう少しで誰か分からないところだった。","e":"She's changed so much that I almost couldn't recognize who she was.","k":"그녀는 많이 변해서, 나는 하마터면 그녀가 누구인지 못 알아볼 뻔했어."}]},
{"id":"g3-210","cat":"補語","t":"V住","g":{"j":"「〜して固定される・しっかり覚える」","e":"to firmly fix/hold/remember through V","k":"~해서 단단히 고정되다/확실히 기억하다"},"p":{"j":"Ｖ ＋ 住","e":"V + zhù","k":"동사 + 住"},"ex":{"j":"「動詞＋住」は動作の結果、対象がしっかり固定される・とどまることを表す結果補語。「記住」は記憶にしっかり残ることを意味し、単に覚えている状態を表す「記得」とは異なり、「覚える」という動作の完成に重点がある。","e":"\"Verb + zhù\" is a resultative complement showing the object becomes firmly fixed or held in place as a result of the action. \"Jìzhù\" means to firmly commit something to memory — unlike \"jìde\" (to remember, a state), it emphasizes completing the act of memorizing.","k":"\"동사+住\"는 동작의 결과로 대상이 단단히 고정되거나 멈추는 것을 나타내는 결과보어이다. \"記住\"는 기억에 단단히 남기는 것을 의미하며, 단순히 기억하고 있는 상태를 나타내는 \"記得\"와 달리 '외우는' 동작의 완성에 초점이 있다."},"eg":[{"z":"姐姐學一遍，就<em>記住</em>所有作法了。","py":"Jiějie xué yíbiàn, jiù jìzhù suǒyǒu zuòfǎ le.","j":"姉は一回習っただけで、すべての作り方を覚えてしまった。","e":"My older sister learned it just once and remembered all the steps.","k":"언니는 한 번 배우고 모든 방법을 다 외워버렸어."},{"z":"他一把<em>抓住</em>我的手，不讓我走。","py":"Tā yì bǎ zhuāzhù wǒ de shǒu, bú ràng wǒ zǒu.","j":"彼はぱっと私の手をつかんで、行かせてくれなかった。","e":"He grabbed my hand and wouldn't let me go.","k":"그는 갑자기 내 손을 꽉 잡고 나를 못 가게 했어."}]},
{"id":"g3-211","cat":"補語","t":"V著（ㄓㄠˊ）","g":{"j":"動作有了結果、達成目的","e":"the action reaches its goal/result","k":"동작이 목적을 이루거나 결과를 얻음"},"p":{"j":"V＋著（zháo）","e":"V + 著 (zháo)","k":"V + 著(zháo)"},"ex":{"j":"「著」がzháoと読まれるときは動作の達成・結果を表す(例:睡著=眠りに落ちる)。持続を表す軽声の「著(zhe)」と字形が同じで紛らわしいので注意。","e":"\"著\" (zháo) shows an action reached its result, e.g. 睡著 \"fell asleep.\" Don't confuse it with durative 著 (zhe) — same character, different meaning.","k":"\"著\"가 zháo로 읽힐 때는 동작이 목적을 이루었음을 나타낸다(예: 睡著=잠들다). 지속을 나타내는 경성 \"著(zhe)\"와 글자는 같지만 뜻이 다르므로 혼동하지 않도록 주의한다."},"eg":[{"z":"他喝完牛奶很快就<em>睡著</em>了。","py":"Tā hēwán niúnǎi hěnkuài jiù shuìzháo le.","j":"彼は牛乳を飲み終えるとすぐに眠りに落ちた。","e":"He fell asleep quickly right after finishing his milk.","k":"그는 우유를 다 마시고 나서 금방 잠이 들었다."},{"z":"他找了半天終於<em>找著</em>護照了。","py":"Tā zhǎole bàntiān zhōngyú zhǎozháo hùzhào le.","j":"彼は長い間探して、ようやくパスポートを見つけた。","e":"He looked for a long time and finally found his passport.","k":"그는 오랫동안 찾다가 마침내 여권을 찾았다."}]},
{"id":"g3-212","cat":"補語","t":"V 得/不 動","g":{"j":"体力的にある物を動かせるか/動かせないか","e":"whether one has the physical strength to move something","k":"힘으로 어떤 것을 옮길 수 있는지 없는지"},"p":{"j":"V＋得/不＋動","e":"V + de/bu + dòng","k":"V + 得/不 + 動"},"ex":{"j":"「V得/不動」は体力的にその物を動かせるかどうかを表す可能補語。「V得/不了(liǎo)」(できる/できないこと全般)や能力の「能」とは焦点が違うので混同しないよう注意。","e":"\"V得/不動\" is a potential complement showing whether you're physically strong enough to move something. Don't confuse it with the broader \"V得/不了 (liǎo)\" (able/unable to do something) or the modal \"能.\"","k":"\"V得/不動\"은 힘으로 그 물건을 옮길 수 있는지 없는지를 나타내는 가능보어이다. 전반적인 가능 여부를 뜻하는 \"V得/不了(liǎo)\"나 조동사 \"能\"과 혼동하지 않도록 주의한다."},"eg":[{"z":"你<em>拿得動</em>這些書架嗎？","py":"Nǐ nádedòng zhèxiē shūjià ma?","j":"あなたはこの本棚を持ち上げられますか？","e":"Can you carry these bookshelves?","k":"너는 이 책장들을 들 수 있어?"},{"z":"這張桌子太重了，我一個人<em>搬不動</em>。","py":"Zhè zhāng zhuōzi tài zhòng le, wǒ yí ge rén bānbudòng.","j":"このテーブルは重すぎて、私一人では運べない。","e":"This table is too heavy — I can't move it by myself.","k":"이 탁자는 너무 무거워서 나 혼자서는 옮길 수 없다."}]},
{"id":"g3-213","cat":"補語","t":"V慣","g":{"j":"あることに慣れてしまった状態","e":"having become used to / accustomed to doing something","k":"어떤 일에 익숙해진 상태"},"p":{"j":"V＋慣（＋了）","e":"V + guàn (+ le)","k":"V + 慣(+了)"},"ex":{"j":"「V慣」は繰り返しの経験を通して習慣化したことを表す結果補語。名詞・動詞の「習慣」とは品詞も使い方も違うので、そのまま置き換えないよう注意。","e":"\"V慣\" is a result complement showing repeated experience has made something a habit (e.g. 住慣 = used to living somewhere). It differs from the noun/verb \"習慣,\" so the two aren't interchangeable.","k":"\"V慣\"은 반복된 경험으로 어떤 것이 습관이 되었음을 나타내는 결과보어이다(예: 住慣=사는 데 익숙해지다). 명사·동사인 \"習慣\"과는 품사와 쓰임이 다르므로 그대로 바꿔 쓸 수 없다."},"eg":[{"z":"他已經<em>過慣</em>了城市的生活，去鄉下常覺得不習慣。","py":"Tā yǐjīng guòguànle chéngshì de shēnghuó, qù xiāngxià cháng juéde bù xíguàn.","j":"彼はすでに都会の生活に慣れてしまい、田舎へ行くとよく慣れないと感じる。","e":"He's already gotten used to city life, so he often feels out of place when he goes to the countryside.","k":"그는 이미 도시 생활에 익숙해져서, 시골에 가면 자주 낯설다고 느낀다."},{"z":"我在台北<em>住慣</em>了，突然搬到鄉下有點不適應。","py":"Wǒ zài Táiběi zhùguànle, túrán bān dào xiāngxià yǒudiǎn bú shìyìng.","j":"私は台北の暮らしに慣れてしまったので、急に田舎に引っ越すと少し適応できない。","e":"I've gotten used to living in Taipei, so suddenly moving to the countryside feels a bit hard to adjust to.","k":"나는 타이베이 생활에 익숙해져서 갑자기 시골로 이사하면 좀 적응이 안 된다."}]},
{"id":"g3-214","cat":"補語","t":"V掉","g":{"j":"あるものが消える・処理される・使い尽くされること","e":"something disappearing, being disposed of, or used up","k":"어떤 것이 사라지거나 처리되거나 다 없어짐"},"p":{"j":"V＋掉（＋了）","e":"V + diào (+ le)","k":"V + 掉(+了)"},"ex":{"j":"「V掉」は動作の結果、対象が消失・処理されることを表す結果補語(例:賣掉、丟掉、忘掉)。単なる完了を表す「V完」とは異なり、「なくなる」というニュアンスが必ず伴う。","e":"\"V掉\" is a result complement showing something disappears or gets disposed of because of the action (e.g. 賣掉 = sold off, 丟掉 = thrown away). Unlike plain \"V完\" (finished), it always carries the sense of something being removed or gone.","k":"\"V掉\"는 동작의 결과로 대상이 사라지거나 처리됨을 나타내는 결과보어이다(예: 賣掉=팔아버리다, 丟掉=버리다). 단순 완료를 뜻하는 \"V完\"과 달리 반드시 \"없어짐\"의 뉘앙스를 동반한다."},"eg":[{"z":"今天生意很好，一下子就<em>賣掉</em>了四雙皮鞋。","py":"Jīntiān shēngyì hěn hǎo, yíxiàzi jiù màidiàole sì shuāng píxié.","j":"今日は商売がとても良くて、あっという間に靴を4足売り切った。","e":"Business was great today — we sold out four pairs of shoes in no time.","k":"오늘 장사가 아주 잘 돼서 순식간에 구두 네 켤레를 다 팔았다."},{"z":"冰箱裡的水果壞了，我把它們都<em>丟掉</em>了。","py":"Bīngxiāng lǐ de shuǐguǒ huài le, wǒ bǎ tāmen dōu diūdiàole.","j":"冷蔵庫の果物が傷んでしまったので、私はそれらを全部捨てた。","e":"The fruit in the fridge went bad, so I threw it all away.","k":"냉장고 안의 과일이 상해서 나는 그것들을 다 버렸다."}]},
{"id":"g3-215","cat":"特殊構文","t":"V個不停/沒完","g":{"j":"動作がずっと止まらず続くこと","e":"an action continuing on and on without stopping","k":"동작이 멈추지 않고 계속됨"},"p":{"j":"V＋個＋不停/沒完","e":"V + ge + bùtíng/méiwán","k":"V + 個 + 不停/沒完"},"ex":{"j":"「V個不停/沒完」は動作が延々と止まらず続く様子を表す口語表現。ここでの「個」は数える量詞ではなく、様態を強調する構造助詞なので、数量詞の「個」と混同しないこと。","e":"\"V個不停/沒完\" is a colloquial pattern showing an action goes on and on without stopping, often with a complaining tone. Here \"個\" isn't the measure word for counting — it's a structural particle emphasizing manner, so don't confuse the two uses.","k":"\"V個不停/沒完\"은 동작이 멈추지 않고 계속됨을 나타내는 구어 표현으로 불평의 뉘앙스를 띠기도 한다. 여기의 \"個\"는 세는 양사가 아니라 양태를 강조하는 구조조사이므로 수량사 \"個\"와 혼동하지 말아야 한다."},"eg":[{"z":"他很喜歡跳舞，每次聽到音樂就<em>跳個不停</em>。","py":"Tā hěn xǐhuān tiàowǔ, měi cì tīngdào yīnyuè jiù tiàogebùtíng.","j":"彼はダンスが大好きで、音楽を聞くたびに止まらず踊り続ける。","e":"He loves dancing — whenever he hears music, he dances non-stop.","k":"그는 춤추는 것을 아주 좋아해서, 음악을 들을 때마다 쉬지 않고 춤을 춘다."},{"z":"他一講起籃球就<em>講個沒完</em>，大家都聽膩了。","py":"Tā yì jiǎngqǐ lánqiú jiù jiǎnggeméiwán, dàjiā dōu tīngnì le.","j":"彼はバスケットボールの話になると、みんなが聞き飽きるほど延々と話し続ける。","e":"Whenever he starts talking about basketball, he goes on and on until everyone's sick of hearing it.","k":"그는 농구 이야기만 시작하면 끝없이 말해서 다들 듣기 싫증이 날 정도다."}]},
{"id":"g3-216","cat":"補語","t":"V個夠","g":{"j":"V個夠:痛快地做到滿足為止","e":"do something to one's heart's content","k":"V個夠: 만족할 때까지 실컷 하다"},"p":{"j":"V ＋ 個 ＋ 夠","e":"V + 個 + 夠","k":"V + 個 + 夠"},"ex":{"j":"動詞のすぐ後に「個夠」を置き、「思う存分〜する」「~し尽くす」という満足のニュアンスを添える話し言葉表現。「個」は軽声(ge)で発音し、後ろに目的語は基本的につかない。","e":"'V個夠' attaches directly after a verb to add a colloquial nuance of doing something 'to one's heart's content' or 'until fully satisfied.' '個' is unstressed (neutral tone) and no object follows.","k":"'V個夠'는 동사 바로 뒤에 붙어 '실컷 ~하다'라는 만족의 뉘앙스를 더하는 구어체 표현이다. '個'는 경성으로 발음되며 보통 뒤에 목적어가 오지 않는다."},"eg":[{"z":"這次演唱會一共有三十首歌，你可以一次<em>聽個夠</em>。","py":"Zhè cì yǎnchànghuì yígòng yǒu sānshí shǒu gē, nǐ kěyǐ yícì tīng ge gòu.","j":"今回のコンサートは全部で三十曲あるから、一度に思う存分聴ける。","e":"This concert has thirty songs in total, so you can listen to your heart's content in one go.","k":"이번 콘서트는 총 서른 곡이 있어서, 한 번에 실컷 들을 수 있어요."},{"z":"這家吃到飽餐廳很便宜，你可以<em>吃個夠</em>。","py":"Zhè jiā chīdàobǎo cāntīng hěn piányí, nǐ kěyǐ chī ge gòu.","j":"この食べ放題のお店はとても安いから、心ゆくまで食べられるよ。","e":"This all-you-can-eat restaurant is very cheap, so you can eat to your heart's content.","k":"이 무한리필 식당은 아주 싸서, 실컷 먹을 수 있어요."}]},
{"id":"g3-217","cat":"特殊構文","t":"PW+V（存現）","g":{"j":"場所＋動詞：某處存在著某物(存現句)","e":"Place + V: something exists/is located somewhere","k":"장소+동사: 어떤 곳에 무엇이 존재함(존현문)"},"p":{"j":"PW(場所詞)＋V＋著＋(数量)＋名詞","e":"Place Word + V + 著 + (quantity) + Noun","k":"장소어 + V + 著 + (수량) + 명사"},"ex":{"j":"「場所詞＋動詞(＋著)」で「〜に…がある/いる」という存在を表す存現句。主語は場所で、後ろに来る名詞(新出情報)には通常数量詞がつく。","e":"This 'Place + V(+著)' pattern states that something exists at a location (existential sentence). The subject is the place, and the noun that follows is typically new information, often with a quantifier.","k":"'장소어 + 동사(+著)' 구문은 '어디에 무엇이 있다'는 존현문을 나타낸다. 주어는 장소이며 뒤에 오는 명사는 보통 처음 언급되는 대상으로 수량사가 자주 붙는다."},"eg":[{"z":"<em>餐桌上放著</em>很多新鮮的水果。","py":"Cānzhuō shàng fàngzhe hěnduō xīnxiān de shuǐguǒ.","j":"食卓の上にはたくさんの新鮮な果物が置いてある。","e":"There is a lot of fresh fruit placed on the dining table.","k":"식탁 위에는 신선한 과일이 많이 놓여 있다."},{"z":"<em>牆上掛著</em>一幅畫。","py":"Qiáng shàng guàzhe yì fú huà.","j":"壁に一枚の絵がかかっている。","e":"There is a painting hanging on the wall.","k":"벽에 그림 한 폭이 걸려 있다."}]},
{"id":"g3-218","cat":"特殊構文","t":"會......的","g":{"j":"會......的:對未來的變化或結果表示肯定的推測","e":"'會...的': a confident prediction that something will happen","k":"會......的: 미래의 변화나 결과에 대한 확신에 찬 추측"},"p":{"j":"(是)＋會＋Ｖ／形容詞＋的","e":"(是) + 會 + V/Adj + 的","k":"(是) + 會 + V/형용사 + 的"},"ex":{"j":"文末の「的」が「會＋V」につくことで、単なる可能性ではなく「必ずそうなる」という話者の確信を強める。「會V」だけの文より断定のニュアンスが強い。","e":"Adding sentence-final '的' after '會 + V' turns a simple possibility into a confident assertion that something will definitely happen — stronger in certainty than '會V' alone.","k":"문미의 '的'가 '會+V' 뒤에 붙으면 단순한 가능성이 아니라 '반드시 그렇게 될 것'이라는 화자의 확신을 강조한다. '會V'만 쓸 때보다 단정적인 느낌이 강하다."},"eg":[{"z":"長大後，人的想法是<em>會改變的</em>。","py":"Zhǎngdà hòu, rén de xiǎngfǎ shì huì gǎibiàn de.","j":"大人になると、人の考え方は変わるものだ。","e":"As people grow up, their way of thinking will change.","k":"어른이 되면 사람의 생각은 바뀌기 마련이다."},{"z":"只要你努力練習，你的中文<em>會進步的</em>。","py":"Zhǐyào nǐ nǔlì liànxí, nǐ de Zhōngwén huì jìnbù de.","j":"頑張って練習しさえすれば、あなたの中国語はきっと上達するよ。","e":"As long as you practice hard, your Chinese will improve.","k":"열심히 연습하기만 하면 네 중국어는 분명 늘 거야."}]},
{"id":"g3-219","cat":"特殊構文","t":"（連）....../一......都/也+不/沒......","g":{"j":"(連)......都/也+不/沒:強調「連...都不/沒有」，表示程度極端","e":"'(連)...都/也+不/沒...': emphasizes an extreme case ('not even...')","k":"(連)......都/也+不/沒......: '심지어 ~조차도 아니다/않다'라는 극단적 강조"},"p":{"j":"(連)＋名詞／子句＋都／也＋不／沒＋Ｖ","e":"(連) + N/Clause + 都/也 + 不/沒 + V","k":"(連) + 명사/절 + 都/也 + 不/沒 + V"},"ex":{"j":"「連」は省略可能だが、「都/也」は省略できない必須の呼応表現。極端な例を挙げて「〜さえ…ない」と強く否定する。数量詞を使った「一...都/也不/沒」も同じ用法。","e":"'連' can be omitted, but '都/也' cannot — they form the required emphatic pairing. This structure cites an extreme example to strongly deny something ('not even...'). The quantity-word pattern '一...都/也不/沒' works the same way.","k":"'連'은 생략 가능하지만 '都/也'는 생략할 수 없는 필수 호응 표현이다. 극단적인 예를 들어 '~조차도 …않다'라고 강하게 부정한다. 수량사를 쓴 '一...都/也不/沒' 형식도 같은 용법이다."},"eg":[{"z":"我<em>連家旁邊開了一間健身房都不知道</em>。","py":"Wǒ lián jiā pángbiān kāile yì jiān jiànshēnfáng dōu bù zhīdào.","j":"私は家のすぐ隣にジムがオープンしたことさえ知らなかった。","e":"I didn't even know that a gym had opened right next to my house.","k":"나는 집 바로 옆에 헬스장이 생긴 것조차 몰랐다."},{"z":"他<em>一句話也沒說</em>就走了。","py":"Tā yí jù huà yě méi shuō jiù zǒu le.","j":"彼は一言も言わずに去ってしまった。","e":"He left without saying a single word.","k":"그는 한 마디도 하지 않고 가 버렸다."}]},
{"id":"g3-220","cat":"接続","t":"不是......就是......","g":{"j":"不是A，就是B:兩種可能中必有其一，非此即彼","e":"'not A, then B': it must be one or the other of two possibilities","k":"不是A，就是B: 둘 중 하나는 반드시 해당됨(이것 아니면 저것)"},"p":{"j":"不是＋Ａ，就是＋Ｂ","e":"不是 + A, 就是 + B","k":"不是 + A, 就是 + B"},"ex":{"j":"AかBかの2つの選択肢のうち必ずどちらか一方が当てはまることを表す。「或者A或者B」と似るが、こちらはより断定的で「二つに一つしかない」という排他的な語気が強い。","e":"Expresses that one of two options, A or B, is always the case — similar to '或者...或者...' but more assertive, emphasizing that it's strictly one or the other.","k":"A 아니면 B, 둘 중 하나는 반드시 해당된다는 것을 나타낸다. '或者A或者B'와 비슷하지만 이쪽이 더 단정적이며 '둘 중 하나뿐'이라는 배타적 어감이 강하다."},"eg":[{"z":"他週末<em>不是打籃球，就是去慢跑</em>。","py":"Tā zhōumò búshì dǎ lánqiú, jiùshì qù mànpǎo.","j":"彼は週末はバスケットボールをするか、でなければジョギングに行く。","e":"On weekends, he either plays basketball or goes jogging.","k":"그는 주말에 농구를 하거나 아니면 조깅을 하러 간다."},{"z":"這杯飲料<em>不是太甜，就是太酸</em>。","py":"Zhè bēi yǐnliào búshì tài tián, jiùshì tài suān.","j":"この飲み物は甘すぎるか、でなければ酸っぱすぎるかのどちらかだ。","e":"This drink is either too sweet or too sour.","k":"이 음료는 너무 달거나 아니면 너무 시다."}]},
{"id":"g3-221","cat":"アスペクト","t":"V（了）（一）V","g":{"j":"動作を短時間・気軽に行う","e":"doing an action briefly or casually","k":"동작을 짧게, 가볍게 하다"},"p":{"j":"V＋了＋V（単音節動詞を重ねた過去の動作）","e":"V + 了 + V (verb reduplication for a brief, completed action)","k":"V + 了 + V (동사 중첩 + 了, 완료된 짧은 동작)"},"ex":{"j":"動詞を「V了V」の形で重ねると「ちょっと〜した」という軽い意味になる。すでに起こったことには「V了V」を、これからのことや一般的な話には「VV」「V一V」を使う。","e":"Reduplicating a verb softens the action to \"do it a little.\" Use \"V了V\" for something already done; use plain \"VV\" or \"V一V\" for general or future actions.","k":"동사를 중첩하면 \"잠깐 ~하다\"라는 가벼운 의미가 된다. 이미 일어난 일에는 \"V了V\"를, 일반적이거나 미래의 일에는 \"VV\"나 \"V一V\"를 쓴다."},"eg":[{"z":"王小姐高興地<em>笑了笑</em>。","py":"Wáng xiǎojiě gāoxìng de xiào le xiào.","j":"王さんは嬉しそうにちょっと笑った。","e":"Ms. Wang smiled happily for a moment.","k":"왕 양은 기쁘게 살짝 웃었다."},{"z":"他<em>想了想</em>，決定不去了。","py":"Tā xiǎng le xiǎng, juédìng bú qù le.","j":"彼はちょっと考えて、行かないことにした。","e":"He thought about it for a moment and decided not to go.","k":"그는 잠깐 생각하고 가지 않기로 했다."}]},
{"id":"g3-222","cat":"数量","t":"一M一M ......","g":{"j":"「一つずつ」「一歩一歩」という意味を表す","e":"expresses \"one by one\" / \"step by step\"","k":"\"하나씩\", \"차례차례\"라는 뜻을 나타냄"},"p":{"j":"一＋量詞＋一＋量詞","e":"yī + measure word + yī + measure word","k":"一 + 양사 + 一 + 양사"},"ex":{"j":"同じ量詞を「一M一M」の形で繰り返すと、動作や物事が順番に少しずつ進む様子を表す。二つ目の量詞を別のものに変えてはいけない。","e":"Repeating \"yī + measure word\" twice shows an action happening gradually, one unit at a time; the same measure word must be used both times.","k":"\"一 + 양사\"를 두 번 반복하면 동작이 하나씩 순서대로 진행되는 모습을 나타낸다. 두 번 다 같은 양사를 써야 한다."},"eg":[{"z":"他們<em>一步一步</em>爬上去。","py":"Tāmen yíbù yíbù pá shàngqù.","j":"彼らは一歩一歩よじ登っていった。","e":"They climbed up step by step.","k":"그들은 한 걸음 한 걸음 기어 올라갔다."},{"z":"我們<em>一個一個</em>上車。","py":"Wǒmen yí ge yí ge shàng chē.","j":"私たちは一人ずつバスに乗った。","e":"We got on the bus one by one.","k":"우리는 한 명씩 버스를 탔다."}]},
{"id":"g3-223","cat":"否定","t":"不再......了","g":{"j":"「もう〜しない」という変化を表す","e":"expresses a change to \"no longer doing something\"","k":"\"더 이상 ~하지 않다\"라는 변화를 나타냄"},"p":{"j":"不再＋動詞（句）＋了","e":"bú zài + verb (phrase) + le","k":"不再 + 동사(구) + 了"},"ex":{"j":"以前していたことが今はもう起こらない、という変化を表す。文末の「了」は必須で、省略すると変化が伝わりにくくなる。","e":"This shows a change from a past habit or state to no longer being true now. The final \"了\" is required — dropping it makes the change unclear.","k":"예전에 하던 일이 지금은 더 이상 일어나지 않는다는 변화를 나타낸다. 문장 끝의 \"了\"는 반드시 필요하며, 생략하면 변화가 잘 드러나지 않는다."},"eg":[{"z":"找到工作後，他現在<em>不再擔心錢的問題了</em>。","py":"Zhǎodào gōngzuò hòu, tā xiànzài bú zài dānxīn qián de wèntí le.","j":"仕事が見つかってから、彼はもうお金のことで悩まなくなった。","e":"After finding a job, he no longer worries about money.","k":"일자리를 찾은 후, 그는 이제 더 이상 돈 문제로 걱정하지 않는다."},{"z":"搬家以後，我<em>不再坐公車上班了</em>。","py":"Bānjiā yǐhòu, wǒ bú zài zuò gōngchē shàngbān le.","j":"引っ越してから、私はもうバスで通勤しなくなった。","e":"After I moved, I no longer take the bus to work.","k":"이사한 후에, 나는 더 이상 버스로 출근하지 않는다."}]},
{"id":"g3-224","cat":"否定","t":"一點也/都+不/沒","g":{"j":"「少しも〜ない」という強い否定を表す","e":"expresses strong negation, \"not at all\"","k":"\"조금도 ~않다\"라는 강한 부정을 나타냄"},"p":{"j":"一點＋（名詞）＋也/都＋不/沒＋動詞・形容詞","e":"yìdiǎn + (noun) + yě/dōu + bù/méi + verb/adj","k":"一點 + (명사) + 也/都 + 不/沒 + 동사·형용사"},"ex":{"j":"「一點都/也不」は形容詞や状態を強く否定し、「一點也沒＋動詞」は過去の動作を強く否定する。話し言葉では「都」が、否定動詞の前では「也」がよく使われる。","e":"\"一點都/也不\" strongly negates an adjective or state, while \"一點也沒 + verb\" strongly negates a completed action. \"都\" is common in speech; \"也\" often precedes a negated verb.","k":"\"一點都/也不\"는 형용사나 상태를 강하게 부정하고, \"一點也沒 + 동사\"는 완료된 동작을 강하게 부정한다. 회화에서는 \"都\"를, 부정 동사 앞에서는 \"也\"를 자주 쓴다."},"eg":[{"z":"年輕時，整晚不睡<em>一點都不累</em>。","py":"Niánqīng shí, zhěngwǎn bú shuì yìdiǎn dōu bú lèi.","j":"若いとき、一晩中寝なくても全然疲れなかった。","e":"When I was young, I wasn't tired at all even after staying up all night.","k":"젊었을 때는 밤을 새워도 전혀 피곤하지 않았다."},{"z":"我今天<em>一點東西也沒吃</em>。","py":"Wǒ jīntiān yìdiǎn dōngxi yě méi chī.","j":"私は今日、何も少しも食べていない。","e":"I haven't eaten anything at all today.","k":"나는 오늘 조금도 아무것도 먹지 않았다."}]},
{"id":"g3-225","cat":"否定","t":"從來+不/沒......","g":{"j":"「今まで一度も〜ない／絶対に〜ない」という意味を表す","e":"expresses \"never (up to now)\" or \"never, as a firm rule\"","k":"\"지금까지 한 번도 ~않다\" 혹은 \"절대로 ~않다\"라는 뜻을 나타냄"},"p":{"j":"從來＋不/沒＋動詞（過）","e":"cónglái + bù/méi + verb (guo)","k":"從來 + 不/沒 + 동사(過)"},"ex":{"j":"「從來沒＋動詞過」は経験が全くないことを、「從來不＋動詞」は習慣として絶対にしないことを表す。「一點也不」のような程度の否定とは違い、頻度・経験を否定する点に注意。","e":"\"從來沒 + verb過\" means the experience has never happened at all, while \"從來不 + verb\" means it's a firm habit never to do something. Unlike degree negations like \"一點也不\", this negates frequency or experience, not degree.","k":"\"從來沒 + 동사過\"는 경험이 전혀 없다는 뜻이고, \"從來不 + 동사\"는 습관적으로 절대 하지 않는다는 뜻이다. \"一點也不\"와 같은 정도 부정과 달리, 이는 빈도·경험을 부정한다."},"eg":[{"z":"李明華<em>從來沒搭過飛機</em>。","py":"Lǐ Mínghuá cónglái méi dāguò fēijī.","j":"李明華さんは今まで一度も飛行機に乗ったことがない。","e":"Li Minghua has never taken a flight before.","k":"리밍화 씨는 지금까지 한 번도 비행기를 타 본 적이 없다."},{"z":"我<em>從來不喝咖啡</em>。","py":"Wǒ cónglái bù hē kāfēi.","j":"私はコーヒーを全く飲まない。","e":"I never drink coffee.","k":"나는 커피를 전혀 마시지 않는다."}]},
{"id":"g3-226","cat":"疑問","t":"不/沒+嗎","g":{"j":"相手の状況を確認する否定疑問文","e":"Negative question confirming a situation","k":"상대방 상황을 확인하는 부정 의문문"},"p":{"j":"(原因・状況)，主語＋不/沒＋VP＋嗎？","e":"(situation), Subject + 不/沒 + VP + 嗎?","k":"(상황), 주어 + 不/沒 + VP + 嗎?"},"ex":{"j":"相手の様子を見て「〜じゃないの？」と確認する時に使う。過去の動作なら「沒」、状態や習慣なら「不」を使い分ける。単なる是非疑問文(〜嗎?)と違い、話者はすでに何らかの推測を持っている。","e":"Used to confirm a guess about someone's state (\"Aren't you...?\"). Use 沒 for past actions, 不 for states/habits. Unlike a plain yes/no question with 嗎, the speaker already has a hunch based on what they observe.","k":"상대방의 모습을 보고 \"~아니야?\"라고 확인할 때 쓴다. 과거 동작에는 沒, 상태·습관에는 不을 쓴다. 단순한 是非 의문문과 달리 화자가 이미 어떤 추측을 갖고 있다."},"eg":[{"z":"你今天怎麼那麼早就回家了，你<em>不舒服嗎</em>？","py":"Nǐ jīntiān zěnme nàme zǎo jiù huíjiā le, nǐ bù shūfu ma?","j":"今日はどうしてそんなに早く帰ってきたの、具合が悪いの？","e":"Why did you come home so early today—aren't you feeling well?","k":"오늘 왜 이렇게 일찍 집에 왔어, 몸이 안 좋아?"},{"z":"你臉色這麼差，你<em>沒睡好嗎</em>？","py":"Nǐ liǎnsè zhème chà, nǐ méi shuì hǎo ma?","j":"顔色がそんなに悪いね、よく眠れなかったの？","e":"You look so pale—didn't you sleep well?","k":"안색이 이렇게 안 좋은데, 잠을 잘 못 잤어?"}]},
{"id":"g3-227","cat":"疑問","t":"不是/沒......嗎","g":{"j":"「〜じゃないの?」と念を押す反語疑問文","e":"Rhetorical question emphasizing \"Isn't it...?\"","k":"\"~아니야?\"라고 강조하는 반어 의문문"},"p":{"j":"主語＋不是/沒＋VP＋嗎？","e":"Subject + 不是/沒 + VP + 嗎?","k":"주어 + 不是/沒 + VP + 嗎?"},"ex":{"j":"話者は答えを確信していて、強く同意や確認を求める反語文。「不/沒+嗎」より語気が強く、「当然そうでしょ」というニュアンスを持つ。「不是」は名詞・形容詞・すでに起きた事実に、「沒」は「〜していない」ことの確認に使う。","e":"The speaker is confident of the answer and uses this to press agreement or confirmation—stronger in tone than plain 不/沒+嗎, implying \"obviously, right?\" Use 不是 for facts/qualities already true, 沒 to confirm something hasn't happened.","k":"화자가 답을 확신하며 강하게 동의나 확인을 구하는 반어문으로, 단순한 不/沒+嗎보다 어조가 강하고 \"당연히 그렇지?\"라는 뉘앙스다. 不是는 이미 사실인 것에, 沒는 아직 하지 않은 것을 확인할 때 쓴다."},"eg":[{"z":"如果參加活動可以認識更多人，這樣<em>不是很好嗎</em>？","py":"Rúguǒ cānjiā huódòng kěyǐ rènshi gèngduō rén, zhèyàng búshì hěn hǎo ma?","j":"もし活動に参加してもっと多くの人と知り合えるなら、それはいいことじゃない？","e":"If joining the activity means meeting more people, isn't that a good thing?","k":"만약 활동에 참여해서 더 많은 사람을 알게 된다면, 그거 좋은 거 아니야?"},{"z":"你<em>不是已經吃飽了嗎</em>？怎麼還在吃？","py":"Nǐ búshì yǐjīng chībǎo le ma? Zěnme hái zài chī?","j":"もうお腹いっぱいって言ってなかった？どうしてまだ食べてるの？","e":"Didn't you already say you were full? Why are you still eating?","k":"이미 배부르다고 하지 않았어? 왜 아직도 먹고 있어?"}]},
{"id":"g3-228","cat":"特殊構文","t":"......QW......就......QW......","g":{"j":"疑問詞を繰り返して「〜なら何でも」と表す構文","e":"Repeating a question word to mean \"whatever/wherever/whoever...\"","k":"의문사를 반복해 \"무엇이든/어디든\"을 나타내는 구문"},"p":{"j":"主語＋想/要＋QW＋就＋VP＋QW","e":"Subject + 想/要 + QW + 就 + VP + QW","k":"주어 + 想/要 + QW + 就 + VP + QW"},"ex":{"j":"同じ疑問詞(什麼、哪裡、誰など)を前後に繰り返し、「選択は自由、どれでもいい」という意味を表す。前後で疑問詞を変えたり省略したりすると意味が通じなくなるので注意。","e":"The same question word (什麼, 哪裡, 誰, etc.) appears twice to mean \"it's entirely up to you / anything goes.\" A common mistake is changing or dropping the second question word—both must match exactly.","k":"같은 의문사(什麼, 哪裡, 誰 등)를 앞뒤에 반복해서 \"무엇이든 상관없다\"는 뜻을 나타낸다. 앞뒤 의문사를 다르게 쓰거나 생략하면 뜻이 통하지 않으니 주의해야 한다."},"eg":[{"z":"這次作文沒有題目，你<em>想寫什麼就寫什麼</em>。","py":"Zhè cì zuòwén méiyǒu tímù, nǐ xiǎng xiě shénme jiù xiě shénme.","j":"今回の作文はテーマがないので、書きたいことを何でも書いていいですよ。","e":"This essay has no set topic, so you can write about whatever you want.","k":"이번 작문은 주제가 없으니까 쓰고 싶은 걸 뭐든지 써도 돼."},{"z":"你<em>想去哪裡就去哪裡</em>，我都可以。","py":"Nǐ xiǎng qù nǎlǐ jiù qù nǎlǐ, wǒ dōu kěyǐ.","j":"あなたが行きたいところならどこでもいいよ、私はどこでも大丈夫。","e":"You can go wherever you want—I'm fine with anywhere.","k":"네가 가고 싶은 곳이면 어디든 좋아, 나는 다 괜찮아."}]},
{"id":"g3-229","cat":"特殊構文","t":"其中","g":{"j":"「その中で」と全体から一部を取り出す","e":"\"Among them/it\"—picking out part of a whole already mentioned","k":"\"그중에서\"라고 전체에서 일부를 가리킴"},"p":{"j":"(全体を示す文)，其中＋一部分の説明","e":"(sentence naming a whole), 其中 + description of part of it","k":"(전체를 나타내는 문장), 其中 + 그중 일부에 대한 설명"},"ex":{"j":"直前で述べた集合・グループを受けて「そのうちの〜」と一部を取り出す時に使う。必ず先に全体(人数・種類など)が示されている必要があり、いきなり文頭では使えない。","e":"Refers back to a group or set just mentioned to single out part of it (\"among them...\"). The whole must be stated first (a number, a list, a category)—it can't open a sentence on its own.","k":"앞서 언급한 전체 집합을 받아 \"그중에서\"라고 일부를 가리킬 때 쓴다. 반드시 먼저 전체(인원수, 종류 등)가 제시되어야 하며 문장 맨 앞에서 단독으로 쓸 수 없다."},"eg":[{"z":"他們兩兄弟，<em>其中</em>一個適合做生意，一個適合教書。","py":"Tāmen liǎng xiōngdì, qízhōng yí ge shìhé zuò shēngyì, yí ge shìhé jiāoshū.","j":"彼ら兄弟二人のうち、一人は商売に向いていて、一人は教えることに向いている。","e":"Of the two brothers, one is suited to business and the other to teaching.","k":"그 형제 두 명 중, 한 명은 사업에 어울리고 한 명은 가르치는 일에 어울린다."},{"z":"這家店賣很多小吃，<em>其中</em>最有名的是滷肉飯。","py":"Zhè jiā diàn mài hěn duō xiǎochī, qízhōng zuì yǒumíng de shì lǔròufàn.","j":"この店はいろいろな軽食を売っていて、その中で一番有名なのはルーローファンだ。","e":"This shop sells many kinds of snacks; among them, the most famous is braised pork rice.","k":"이 가게는 다양한 간식을 파는데, 그중에서 가장 유명한 것은 루로우판이다."}]},
{"id":"g3-230","cat":"特殊構文","t":"等/等等","g":{"j":"例を挙げた後に「〜など」と続きを示す","e":"\"Etc.\"—added after listing examples to show the list isn't complete","k":"예를 든 뒤 \"~등\"이라고 나열이 더 있음을 나타냄"},"p":{"j":"像是/如＋A、B、C＋等(等)","e":"像是/如 + A, B, C + 等(等)","k":"像是/如 + A, B, C + 等(等)"},"ex":{"j":"具体例を2つ以上並べたあとに置き、「他にも同類のものがある」ことを示す。文末なら「等」一字でも「等等」でもよいが、文が続く場合は「等」だけを使うのが自然。","e":"Placed after two or more listed examples to show there are more of the same kind. At the end of a sentence either 等 or 等等 works, but mid-sentence (before more text follows) only the single 等 sounds natural.","k":"두 개 이상의 예를 나열한 뒤에 붙여 \"그 밖에도 같은 종류가 더 있다\"는 것을 나타낸다. 문장 끝에서는 等과 等等 둘 다 쓸 수 있지만, 문장이 이어질 때는 等만 쓰는 것이 자연스럽다."},"eg":[{"z":"他很喜歡吃甜食，像是巧克力、蛋糕、冰淇淋<em>等</em>。","py":"Tā hěn xǐhuān chī tiánshí, xiàngshì qiǎokèlì, dàngāo, bīngqílín děng.","j":"彼は甘い物が大好きで、チョコレート、ケーキ、アイスクリームなどが好きだ。","e":"He loves sweets, like chocolate, cake, ice cream, and so on.","k":"그는 단 것을 아주 좋아해서 초콜릿, 케이크, 아이스크림 등을 좋아한다."},{"z":"學校教很多語言，像是英文、日文、韓文<em>等</em>。","py":"Xuéxiào jiāo hěn duō yǔyán, xiàngshì Yīngwén, Rìwén, Hánwén děng.","j":"学校ではたくさんの言語を教えていて、例えば英語、日本語、韓国語などだ。","e":"The school teaches many languages, such as English, Japanese, and Korean.","k":"학교에서는 많은 언어를 가르치는데, 영어, 일본어, 한국어 등이다."}]},
{"id":"g3-231","cat":"数量","t":"以+上/下/內/外","g":{"j":"「以上／以下／以內／以外」で数量の範囲を表す","e":"expressing a range with 以上/以下/以內/以外 (\"or more/less,\" \"within/beyond\")","k":"以上/以下/以內/以外로 수량의 범위를 나타냄"},"p":{"j":"數字（＋量詞）＋以上／以下／以內／以外","e":"Number (+ measure word) + 以上/以下/以內/以外","k":"數字（＋量詞）＋以上／以下／以內／以外"},"ex":{"j":"数量の後につけて範囲の境界を示す。「以上」「以下」はその数を含み、「以內」「以外」は範囲の内側・外側を表す。前に必ず数量詞を置くこと。","e":"Attaches after a quantity to mark a boundary: 以上/以下 include the stated number, while 以內/以外 mark inside/outside a range. Common mistake: dropping the number before it.","k":"수량 뒤에 붙어 범위의 경계를 나타낸다. 以上/以下는 그 수를 포함하고, 以內/以外는 범위의 안/밖을 뜻한다. 앞에 반드시 수량사를 붙여야 한다."},"eg":[{"z":"他每天通車要花費兩個小時<em>以上</em>。","py":"Tā měitiān tōngchē yào huāfèi liǎng ge xiǎoshí yǐshàng.","j":"彼は毎日通勤に2時間以上かかる。","e":"He spends more than two hours commuting every day.","k":"그는 매일 통근하는 데 두 시간 이상 걸린다."},{"z":"這附近五分鐘<em>以內</em>就有一家超商。","py":"Zhè fùjìn wǔ fēnzhōng yǐnèi jiù yǒu yì jiā chāoshāng.","j":"この近くには5分以内にコンビニが一軒ある。","e":"There's a convenience store within five minutes of here.","k":"이 근처에는 5분 이내에 편의점이 하나 있다."}]},
{"id":"g3-232","cat":"接続","t":"除了......（以外），......都......","g":{"j":"「除了A以外，都B」で例外を表す","e":"expressing an exception with \"除了A以外，都B\" (all except A)","k":"\"除了A以外，都B\"로 예외를 나타냄"},"p":{"j":"除了＋A（以外），＋都＋B","e":"除了 + A (以外), + 都 + B","k":"除了＋A（以外），＋都＋B"},"ex":{"j":"Aだけを例外として、それ以外は全部同じであることを表す。「都」は例外を除いた「残り全部」を指す。追加を表す「除了A以外，還B」と混同しないよう注意。","e":"Marks A as the sole exception, with 都 referring to everything else. Don't confuse this with the addition pattern \"除了A以外，還B,\" which adds something rather than excluding it.","k":"A만 예외로 두고 나머지는 모두 같다는 뜻. 都는 예외를 뺀 \"나머지 전부\"를 가리킨다. 추가를 뜻하는 \"除了A以外，還B\"와 혼동하지 말 것."},"eg":[{"z":"<em>除了牛肉以外</em>，其他的肉我<em>都</em>可以吃。","py":"Chúle niúròu yǐwài, qítā de ròu wǒ dōu kěyǐ chī.","j":"牛肉以外なら、ほかの肉は全部食べられる。","e":"Except for beef, I can eat all other kinds of meat.","k":"소고기를 빼고 다른 고기는 다 먹을 수 있다."},{"z":"<em>除了星期天以外</em>，我每天<em>都</em>要上班。","py":"Chúle xīngqítiān yǐwài, wǒ měitiān dōu yào shàngbān.","j":"日曜日以外は、毎日仕事に行かなければならない。","e":"Except for Sundays, I have to go to work every day.","k":"일요일을 빼고 나는 매일 출근해야 한다."}]},
{"id":"g3-233","cat":"接続","t":"除了......以外， 還/也......","g":{"j":"「除了A以外，還／也B」で追加を表す","e":"expressing addition with \"除了A以外，還/也B\" (besides A, also B)","k":"\"除了A以外，還/也B\"로 추가를 나타냄"},"p":{"j":"除了＋A＋以外，＋還／也＋B","e":"除了 + A + 以外, + 還/也 + B","k":"除了＋A＋以外，＋還／也＋B"},"ex":{"j":"Aに加えてBもあるという「追加」を表す。例外を表す「除了A以外，都B」と形が似ているので、追加なら「還／也」、例外なら「都」と使い分ける。","e":"Expresses addition: besides A, there is also B. Similar in form to the exclusion pattern \"除了A以外，都B\" — use 還/也 for \"in addition,\" 都 for \"all except.\"","k":"A 외에 B도 있다는 \"추가\"를 나타낸다. 예외를 뜻하는 \"除了A以外，都B\"와 형태가 비슷하므로, 추가는 還/也, 예외는 都로 구분해야 한다."},"eg":[{"z":"這次的活動<em>除了杯子以外</em>，<em>還</em>送毛巾。","py":"Zhècì de huódòng chúle bēizi yǐwài, hái sòng máojīn.","j":"今回のイベントはコップのほかに、タオルも配る。","e":"Besides a cup, this event also gives out a towel.","k":"이번 행사는 컵 외에 수건도 준다."},{"z":"這個房間<em>除了床以外</em>，<em>也</em>有一張桌子。","py":"Zhège fángjiān chúle chuáng yǐwài, yě yǒu yì zhāng zhuōzi.","j":"この部屋にはベッドのほかに、机も一つある。","e":"Besides a bed, this room also has a desk.","k":"이 방에는 침대 외에 책상도 하나 있다."}]},
{"id":"g3-234","cat":"数量","t":"數+（量詞）+左右","g":{"j":"「左右」でおおよその数量を表す","e":"expressing an approximate amount with 左右","k":"左右로 대략적인 수량을 나타냄"},"p":{"j":"數字＋（量詞）＋左右","e":"Number + (measure word) + 左右","k":"數字＋（量詞）＋左右"},"ex":{"j":"数量のおおよその見積もりを表す。時間・金額・年齢など幅広く使える。「大約」など他の「約」の語と重ねて使わないよう注意(左右だけですでに「だいたい」の意味がある)。","e":"Shows an approximate quantity (time, money, age, etc.). Avoid pairing it with 大約/大概 in the same phrase — 左右 alone already means \"approximately.\"","k":"수량의 대략적인 어림을 나타낸다(시간, 금액, 나이 등). 大約/大概 같은 다른 \"약\"의 표현과 겹쳐 쓰지 않도록 주의 — 左右만으로 이미 \"대략\"의 뜻이 있다."},"eg":[{"z":"他每天搭車上班的時間需要<em>一個小時左右</em>。","py":"Tā měitiān dāchē shàngbān de shíjiān xūyào yí ge xiǎoshí zuǒyòu.","j":"彼は毎日、乗り物で通勤するのに1時間くらいかかる。","e":"It takes him about an hour to commute to work by public transportation every day.","k":"그가 매일 차를 타고 출근하는 데는 한 시간 정도 걸린다."},{"z":"這件外套要<em>兩千塊左右</em>。","py":"Zhè jiàn wàitào yào liǎngqiān kuài zuǒyòu.","j":"このジャケットは2000元くらいする。","e":"This jacket costs around NT$2,000.","k":"이 재킷은 대만 돈으로 2천 원 정도 한다."}]},
{"id":"g3-235","cat":"数量","t":"百分數","g":{"j":"「百分之＋數字」でパーセントを表す","e":"expressing percentages with 百分之 + number","k":"百分之+숫자로 퍼센트를 나타냄"},"p":{"j":"百分之＋數字","e":"百分之 + number","k":"百分之＋數字"},"ex":{"j":"「百分之＋数字」でパーセントを表す(百分之五＝5%)。「%」の記号をそのまま読まず必ず「百分之」を使い、語順を「數字＋百分之」と逆にしないよう注意。","e":"\"百分之 + number\" expresses a percentage (百分之五 = 5%). Say 百分之 before the number, and don't read the \"%\" symbol literally.","k":"\"百分之 + 숫자\"로 퍼센트를 나타낸다(百分之五=5%). 숫자를 먼저 말하고 百分之를 뒤에 붙이는 실수를 하지 않도록 주의."},"eg":[{"z":"這裡只有<em>百分之五</em>的人沒出過國。","py":"Zhèlǐ zhǐyǒu bǎifēnzhīwǔ de rén méi chūguò guó.","j":"ここでは、外国に行ったことがない人はわずか5パーセントしかいない。","e":"Only five percent of the people here have never been abroad.","k":"여기서는 외국에 가본 적이 없는 사람이 겨우 5퍼센트밖에 안 된다."},{"z":"這班有<em>百分之八十</em>的學生會說英文。","py":"Zhè bān yǒu bǎifēnzhībāshí de xuéshēng huì shuō Yīngwén.","j":"このクラスは80パーセントの学生が英語を話せる。","e":"Eighty percent of the students in this class can speak English.","k":"이 반은 학생의 80퍼센트가 영어를 할 수 있다."}]},
{"id":"g3-236","cat":"数量","t":"倍數","g":{"j":"「~の何倍」を表す","e":"expressing multiples","k":"~의 몇 배를 나타냄"},"p":{"j":"A＋是＋B＋的＋N倍(＋形容詞)","e":"A + 是 + B + 的 + N + 倍 (+ Adj)","k":"A + 是 + B + 的 + N + 倍(+형용사)"},"ex":{"j":"「A是B的N倍」で、AがBの何倍かを表す。「二倍」ではなく必ず「兩倍」と言う。「倍」は基準より大きい場合に使い、半分は「一半」で表す。","e":"Use \"A是B的N倍\" to say A is N times B. Always say 兩倍, never 二倍. 倍 only works for multiples larger than the base—use 一半 for \"half,\" not a fraction of 倍.","k":"\"A是B的N倍\" 형식으로 A가 B의 몇 배인지 나타낸다. \"二倍\"가 아니라 반드시 \"兩倍\"라고 해야 한다. 倍는 기준보다 큰 경우에만 쓰고, 절반은 一半으로 표현한다."},"eg":[{"z":"姐姐的行李是我的<em>兩倍</em>重。","py":"Jiějie de xínglǐ shì wǒ de liǎng bèi zhòng.","j":"姉の荷物は私のの2倍重い。","e":"My sister's luggage is twice as heavy as mine.","k":"언니의 짐은 내 짐보다 두 배 무겁다."},{"z":"這輛車的價錢是那輛車的<em>三倍</em>。","py":"Zhè liàng chē de jiàqián shì nà liàng chē de sān bèi.","j":"このクルマの値段はあのクルマの3倍だ。","e":"This car costs three times as much as that car.","k":"이 차의 가격은 저 차의 세 배이다."}]},
{"id":"g3-237","cat":"数量","t":"分數","g":{"j":"「~分の~」の分数表現","e":"expressing fractions","k":"~분의 ~ 분수 표현"},"p":{"j":"N分之M","e":"N + 分之 + M","k":"N + 分之 + M"},"ex":{"j":"分数は「分母＋分之＋分子」の順で言う(三分之一＝1/3)。日本語や英語の「◯分の△」と語順が逆なので注意。韓国語の語順とは一致する。","e":"Say fractions as \"denominator + 分之 + numerator\" (三分之一 = 1/3)—reversed from English \"one third.\" Don't flip numerator and denominator.","k":"분수는 \"분모+分之+분자\" 순서로 말한다(三分之一=1/3). 한국어 \"삼분의 일\"과 어순이 같으니 분모를 먼저 말하는 데 주의한다."},"eg":[{"z":"這條腳踏車步道他大概只騎了<em>三分之一</em>。","py":"Zhè tiáo jiǎotàchē bùdào tā dàgài zhǐ qíle sān fēnzhī yī.","j":"この自転車道、彼はだいたい三分の一しか走らなかった。","e":"He probably only rode about a third of this bike path.","k":"이 자전거 도로를 그는 대략 삼분의 일밖에 타지 않았다."},{"z":"這塊蛋糕我只吃了<em>四分之一</em>。","py":"Zhè kuài dàngāo wǒ zhǐ chīle sì fēnzhī yī.","j":"このケーキ、私は4分の1しか食べなかった。","e":"I only ate a quarter of this cake.","k":"이 케이크를 나는 사분의 일밖에 먹지 않았다."}]},
{"id":"g3-238","cat":"数量","t":"四則運算","g":{"j":"加減乗除の読み方","e":"reading arithmetic operations","k":"사칙연산 읽는 법"},"p":{"j":"A＋加/減/乘以/除以＋B＋等於＋C","e":"A + 加/減/乘以/除以 + B + 等於 + C","k":"A + 加/減/乘以/除以 + B + 等於 + C"},"ex":{"j":"加減乗除はそれぞれ「加」「減」「乘以」「除以」で表し、答えの前に「等於」を置く。「乘以」「除以」の「以」を落とすのはよくある誤り。","e":"Use 加/減/乘以/除以 for +,−,×,÷ and place 等於 before the answer. A common mistake is dropping the 以 in 乘以/除以.","k":"덧셈·뺄셈·곱셈·나눗셈은 각각 加/減/乘以/除以로 말하고, 답 앞에 等於를 붙인다. 乘以·除以에서 以를 빠뜨리는 실수가 흔하다."},"eg":[{"z":"<em>三加二等於五</em>,你知道嗎?","py":"Sān jiā èr děngyú wǔ, nǐ zhīdào ma?","j":"3足す2は5だよ、知ってる?","e":"Three plus two equals five, did you know that?","k":"3 더하기 2는 5야, 알고 있어?"},{"z":"<em>八除以四等於二</em>。","py":"Bā chúyǐ sì děngyú èr.","j":"8割る4は2だ。","e":"Eight divided by four equals two.","k":"8 나누기 4는 2이다."}]},
{"id":"g3-239","cat":"数量","t":"小數點","g":{"j":"小数点の読み方","e":"reading decimal points","k":"소수점 읽는 법"},"p":{"j":"整數＋點＋小數(1字ずつ)","e":"Integer + 點 + decimal digits (read one by one)","k":"정수 + 點 + 소수(한 글자씩)"},"ex":{"j":"小数は「整数部＋點＋小数部を1字ずつ」読む(3.25→三點二五)。小数部を「二十五」のようにまとめて読まないよう注意。","e":"Read decimals as \"integer part + 點 + each digit separately\" (3.25 → 三點二五). Don't read the decimal part as a whole number like 二十五.","k":"소수는 \"정수부분+點+소수부분을 한 글자씩\" 읽는다(3.25→三點二五). 소수부분을 二十五처럼 통째로 읽지 않도록 주의한다."},"eg":[{"z":"這條魚重<em>三點二五</em>公斤。","py":"Zhè tiáo yú zhòng sān diǎn èr wǔ gōngjīn.","j":"この魚は3.25キロある。","e":"This fish weighs 3.25 kilograms.","k":"이 물고기는 3.25킬로그램이다."},{"z":"我的身高是<em>一點六五</em>公尺。","py":"Wǒ de shēngāo shì yī diǎn liù wǔ gōngchǐ.","j":"私の身長は1.65メートルです。","e":"My height is 1.65 meters.","k":"제 키는 1.65미터입니다."}]},
{"id":"g3-240","cat":"特殊構文","t":"VP/S+的......","g":{"j":"「~のは…だ」と焦点化する","e":"focusing on what the VP is","k":"~하는 것은…이다(초점 구문)"},"p":{"j":"S＋VP＋的＋是＋O","e":"S + VP + 的 + 是 + O","k":"S + VP + 的 + 是 + O"},"ex":{"j":"「VP＋的＋是＋◯」で「~するのは◯だ」と焦点を絞って説明する。是のない単なる「VP＋的」(~するもの)という名詞化用法とは違うので混同しないこと。","e":"\"VP+的+是+X\" highlights X as the focused answer to \"what [VP] is.\" Don't confuse it with plain \"VP+的\" (no 是) used alone as a nominalized noun phrase.","k":"\"VP+的+是+X\" 형식으로 X를 초점으로 두어 \"~하는 것은 X이다\"라고 설명한다. 是가 없는 단순한 \"VP+的\" 명사화 용법과 혼동하지 않는다."},"eg":[{"z":"這本書<em>討論的是</em>美洲的歷史。","py":"Zhè běn shū tǎolùn de shì Měizhōu de lìshǐ.","j":"この本が論じているのはアメリカ大陸の歴史だ。","e":"What this book discusses is the history of the Americas.","k":"이 책이 논하는 것은 아메리카 대륙의 역사이다."},{"z":"他<em>喜歡的是</em>那間店的牛肉麵。","py":"Tā xǐhuān de shì nà jiān diàn de niúròumiàn.","j":"彼が好きなのはあの店の牛肉麺だ。","e":"What he likes is that shop's beef noodles.","k":"그가 좋아하는 것은 그 가게의 우육면이다."}]},
{"id":"g3-241","cat":"否定","t":"別（再）......了","g":{"j":"もう〜するのはやめて","e":"stop doing X","k":"더 이상 ~하지 마"},"p":{"j":"別（再）＋ 動詞句 ＋ 了","e":"Bié (zài) + VP + le","k":"別（再）＋ 동사구 ＋ 了"},"ex":{"j":"「別再...了」で「もう〜するのはやめて」という意味。文末の「了」が状況の変化を示し、今している動作をやめさせる。「不要」との違いは、継続中の行為を止める点にある。","e":"\"Bié zài...le\" means \"stop doing X\" — used to tell someone to stop an ongoing or repeated action. The final \"le\" marks a change of state. Unlike plain \"不要\", it implies the action was already happening.","k":"「別再...了」는 「더 이상 ~하지 마」라는 뜻으로 진행 중이거나 반복되는 행동을 멈추라고 할 때 쓴다. 문장 끝의 「了」는 상태 변화를 나타낸다. 「不要」와 달리 이미 하고 있는 행동을 멈추게 한다."},"eg":[{"z":"<em>別再說話了</em>，比賽要開始囉！","py":"Bié zài shuōhuà le, bǐsài yào kāishǐ luō!","j":"もうおしゃべりはやめて、試合が始まるよ！","e":"Stop talking now, the match is about to start!","k":"더 이상 떠들지 마, 경기가 곧 시작해!"},{"z":"<em>別再玩手機了</em>，快寫功課！","py":"Bié zài wán shǒujī le, kuài xiě gōngkè!","j":"もうスマホで遊ぶのはやめて、早く宿題をしなさい！","e":"Stop playing with your phone, hurry up and do your homework!","k":"더 이상 휴대폰 갖고 놀지 마, 빨리 숙제해!"}]},
{"id":"l3-13","cat":"語氣","t":"到底","g":{"j":"いったい","e":"on earth / after all","k":"도대체"},"p":{"j":"到底 ＋ 疑問文","e":"到底 + question","k":"到底 + 의문문"},"ex":{"j":"疑問を強める「いったい・結局」。「到底是誰？（いったい誰？）」。平叙文では「結局のところ・やはり」の意味にもなる。疑問文で「嗎」とは併用不可。","e":"到底 intensifies questions: \"on earth / after all\". Not used together with 嗎.","k":"\"到底\"는 의문을 강조하는 '도대체'. \"嗎\"와는 같이 쓰지 않는다."},"eg":[{"z":"你<em>到底</em>要不要去？","py":"Nǐ dàodǐ yào bú yào qù?","j":"いったい行くの、行かないの？","e":"Are you going or not, after all?","k":"도대체 갈 거예요, 말 거예요?"},{"z":"這裡<em>到底</em>發生了什麼事？","py":"Zhèlǐ dàodǐ fāshēng le shénme shì?","j":"ここでいったい何が起きたんですか。","e":"What on earth happened here?","k":"여기서 도대체 무슨 일이 일어난 거예요?"}]}
];
if (typeof window !== "undefined") window.GRAMMAR_L3 = GRAMMAR_L3;
